export default ".0\\n\\n    def monotonic_stub() -> float:\\n        return fake_now\\n\\n    base = \\\"http://localhost:11434\\\"\\n    with (\\n        patch.object(model_utils.time, \\\"monotonic\\\", side_effect=monotonic_stub),\\n        patch.object(model_utils.httpx, \\\"AsyncClient\\\", return_value=client),\\n    ):\\n        first = await model_utils.get_ollama_models(\\n            base_url_value=base,\\n            desired_capability=\\\"completion\\\",\\n            json_models_key=\\\"models\\\",\\n            json_name_key=\\\"name\\\",\\n            json_capabilities_key=\\\"capabilities\\\",\\n        )\\n        assert (base, \\\"transient\\\") in model_utils._ollama_capability_cache\\n\\n        # \\\"transient\\\" drops out of the catalog; advance past the list TTL so\\n        # the catalog is actually re-fetched (and thus pruned).\\n        tags[\\\"models\\\"] = [{\\\"name\\\": \\\"llama3\\\"}]\\n        fake_now = model_utils._OLLAMA_MODEL_LIST_TTL_SECONDS + 1\\n        second = await model_utils.get_ollama_models(\\n            base_url_value=base,\\n            desired_capability=\\\"completion\\\",\\n            json_models_key=\\\"models\\\",\\n            json_name_key=\\\"name\\\",\\n            json_capabilities_key=\\\"capabilities\\\",\\n        )\\n\\n    assert first == [\\\"llama3\\\", \\\"transient\\\"]\\n    assert second == [\\\"llama3\\\"]\\n    # The departed model's capability entry was pruned on the second read.\\n    assert (base, \\\"transient\\\") not in model_utils._ollama_capability_cache\\n    # llama3's entry survives (still listed, still within the capability TTL).\\n    assert (base, \\\"llama3\\\") in model_utils._ollama_capability_cache\\n\\n\\n@pytest.mark.asyncio\\nasync def test_llm_and_embedding_reads_share_one_show_fanout():\\n    \\\"\\\"\\\"The ``model_type=None`` path must not probe the catalog twice.\\n\\n    ``GET /enabled_models`` fetches both llm and embedding live models\\n    (``replace_with_live_models(model_type=None)``) on every refetch. Before\\n    the per-model capability cache that meant ``2 x (N + 1)`` upstream calls\\n    per read on Ollama Cloud's large public catalog \u2014 the root cause of the\\n    toggle slowness in issue #12399. The two reads must now share a single\\n    ``/api/show`` fan-out: ``N`` probes total, not ``2N``.\\n    \\\"\\\"\\\"\\n    from lfx.base.models import model_utils\\n\\n    tags = {\\n        \\\"models\\\": [\\n            {\\\"name\\\": \\\"llama3\\\"},\\n            {\\\"name\\\": \\\"qwen2\\\"},\\n            {\\\"name\\\": \\\"mxbai-embed-large\\\"},\\n            {\\\"name\\\": \\\"nomic-embed-text\\\"},\\n        ]\\n    }\\n    show = {\\n        \\\"llama3\\\": {\\\"capabilities\\\": [\\\"completion\\\", \\\"tools\\\"]},\\n        \\\"qwen2\\\": {\\\"capabilities\\\": [\\\"completion\\\"]},\\n        \\\"mxbai-embed-large\\\": {\\\"capabilities\\\": [\\\"embedding\\\"]},\\n        \\\"nomic-embed-text\\\": {\\\"capabilities\\\": [\\\"embedding\\\"]},\\n    }\\n    client = _build_async_client(tags_payload=tags, show_results=show)\\n\\n    with patch.object(model_utils.httpx, \\\"AsyncClient\\\", return_value=client):\\n        llms = await model_utils.get_ollama_llm_models(\\\"http://ollama.com\\\")\\n        embs = await model_utils.get_ollama_embedding_models(\\\"http://ollama.com\\\")\\n\\n    assert llms == [\\\"llama3\\\", \\\"qwen2\\\"]\\n    assert embs == [\\\"mxbai-embed-large\\\", \\\"nomic-embed-text\\\"]\\n    # 4 models probed exactly once across BOTH reads \u2014 the embedding read\\n    # reused every capability the llm read already fetched.\\n    assert client.post.await_count == len(tags[\\\"models\\\"])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/models/test_openrouter_provider.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"46b61cee3182e848ca05b0d2ebc04748a8f30d8f7aa1bd447b48d6855276673d\",\"content\":\"\\\"\\\"\\\"Unit tests for the OpenRouter unified model provider.\\n\\nCovers:\\n  - Provider metadata registration (variables, mapping, live-fetch flag).\\n  - fetch_live_openrouter_models \u2014 mocks the OpenRouter /models endpoint and\\n    pins the per-model ``tool_calling`` flag, default-set intersection logic,\\n    and degradation paths for transport, status, and payload errors.\\n  - validate_model_provider_key \u2014 success, 401, and transient-network paths.\\n  - get_llm \u2014 base_url + default_headers wiring (including env-var fallback).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import MagicMock, patch\\n\\nimport httpx\\nimport pytest\\nimport requests\\n\\n# ---------------------------------------------------------------------------\\n# Metadata\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_openrouter_in_provider_registry():\\n    from lfx.base.models.model_metadata import LIVE_MODEL_PROVIDERS, MODEL_PROVIDER_METADATA\\n\\n    assert \\\"OpenRouter\\\" in MODEL_PROVIDER_METADATA\\n    assert \\\"OpenRouter\\\" in LIVE_MODEL_PROVIDERS\\n\\n\\ndef test_openrouter_metadata_shape():\\n    from lfx.base.models.model_metadata import MODEL_PROVIDER_METADATA\\n\\n    meta = MODEL_PROVIDER_METADATA[\\\"OpenRouter\\\"]\\n    assert meta[\\\"icon\\\"] == \\\"OpenRouter\\\"\\n    assert meta[\\\"base_url\\\"] == \\\"https://openrouter.ai/api/v1\\\"\\n    assert meta[\\\"mapping\\\"][\\\"model_class\\\"] == \\\"ChatOpenAI\\\"\\n    assert meta[\\\"mapping\\\"][\\\"model_param\\\"] == \\\"model\\\"\\n\\n    var_keys = {v[\\\"variable_key\\\"] for v in meta[\\\"variables\\\"]}\\n    assert var_keys == {\\\"OPENROUTER_API_KEY\\\", \\\"OPENROUTER_SITE_URL\\\", \\\"OPENROUTER_APP_NAME\\\"}\\n\\n    by_key = {v[\\\"variable_key\\\"]: v for v in meta[\\\"variables\\\"]}\\n    assert by_key[\\\"OPENROUTER_API_KEY\\\"][\\\"required\\\"] is True\\n    assert by_key[\\\"OPENROUTER_API_KEY\\\"][\\\"is_secret\\\"] is True\\n    assert by_key[\\\"OPENROUTER_SITE_URL\\\"][\\\"required\\\"] is False\\n    assert by_key[\\\"OPENROUTER_SITE_URL\\\"][\\\"is_header\\\"] is True\\n    assert by_key[\\\"OPENROUTER_SITE_URL\\\"][\\\"header_name\\\"] == \\\"HTTP-Referer\\\"\\n    assert by_key[\\\"OPENROUTER_APP_NAME\\\"][\\\"header_name\\\"] == \\\"X-Title\\\"\\n\\n\\ndef test_openrouter_appears_in_get_model_providers():\\n    from lfx.base.models.unified_models import get_model_providers\\n\\n    assert \\\"OpenRouter\\\" in get_model_providers()\\n\\n\\ndef test_openrouter_param_mapping_resolves_to_chatopenai():\\n    from lfx.base.models.model_metadata import get_provider_param_mapping\\n\\n    mapping = get_provider_param_mapping(\\\"OpenRouter\\\")\\n    assert mapping[\\\"model_class\\\"] == \\\"ChatOpenAI\\\"\\n    assert mapping[\\\"model_param\\\"] == \\\"model\\\"\\n    assert mapping[\\\"api_key_param\\\"] == \\\"api_key\\\"  # pragma: allowlist secret\\n\\n\\ndef test_openrouter_env_vars_registered_for_auto_import():\\n    \\\"\\\"\\\"OPENROUTER_* env vars must be auto-imported as global variables.\\n\\n    Without this, a user with the env vars set would not see the provider as\\n    configured in Settings \u2192 Model Providers (parity with OpenAI/Anthropic/etc.).\\n    \\\"\\\"\\\"\\n    from lfx.services.settings.constants import VARIABLES_TO_GET_FROM_ENVIRONMENT\\n\\n    for var in (\\\"OPENROUTER_API_KEY\\\", \\\"OPENROUTER_SITE_URL\\\", \\\"OPENROUTER_APP_NAME\\\"):\\n        assert var in VARIABLES_TO_GET_FROM_ENVIRONMENT\\n\\n\\n# ---------------------------------------------------------------------------\\n# Live model fetcher\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _models_payload(entries: list[dict]) -> MagicMock:\\n    \\\"\\\"\\\"Build a fake httpx.Response carrying an OpenRouter /models payload.\\n\\n    Each entry should look like ``{\\\"id\\\": \\\"...\\\", \\\"supported_parameters\\\": [...]}``.\\n    \\\"\\\"\\\"\\n    response = MagicMock()\\n    response.json.return_value = {\\\"data\\\": entries}\\n    response.raise_for_status.return_value = None\\n    return response\\n\\n\\ndef test_fetch_live_openrouter_models_returns_empty_for_embeddings():\\n    from lfx.base.models.model_utils import fetch_live_openrouter_models\\n\\n    assert fetch_live_openrouter_models(\\\"user-id\\\", \\\"embeddings\\\") == []\\n\\n\\ndef test_fetch_live_openrouter_models_returns_empty_when_no_key():\\n    from lfx.base.models import model_utils\\n\\n    with patch.object(model_utils, \\\"get_provider_variable_value\\\", return_value=None):\\n        assert model_utils.fetch_live_openrouter_models(\\\"user-id\\\", \\\"llm\\\") == []\\n\\n\\ndef test_fetch_live_openrouter_models_propagates_created_timestamp():\\n    \\\"\\\"\\\"OpenRouter exposes ``created`` as a Unix epoch (seconds).\\\"\\\"\\\"\\n    from lfx.base.models import model_utils\\n\\n    response = _models_payload(\\n        [\\n            {\\\"id\\\": \\\"openai/gpt-4o\\\", \\\"supported_parameters\\\": [\\\"tools\\\"], \\\"created\\\": 1715558400},\\n            {\\\"id\\\": \\\"anthropic/claude-old\\\", \\\"supported_parameters\\\": [\\\"tools\\\"], \\\"created\\\": 1700000000},\\n            {\\\"id\\\": \\\"broken-time\\\", \\\"supported_parameters\\\": [\\\"tools\\\"], \\\"created\\\": \\\"not-a-number\\\"},\\n            {\\\"id\\\": \\\"no-time\\\", \\\"supported_parameters\\\": [\\\"tools\\\"]},\\n        ]\\n    )\\n    with (\\n        patch.object(model_utils, \\\"get_provider_variable_value\\\", return_value=\\\"dummy-key\\\"),  # pragma: allowlist secret\\n        patch.object(model_utils.httpx, \\\"get\\\", return_value=response),\\n    ):\\n        result = model_utils.fetch_live_openrouter_models(\\\"user-id\\\", \\\"llm\\\")\\n\\n    by_name = {m[\\\"name\\\"]: m for m in result}\\n    assert by_name[\\\"openai/gpt-4o\\\"][\\\"created\\\"] == 1715558400\\n    assert by_name[\\\"anthropic/claude-old\\\"][\\\"created\\\"] == 1700000000\\n    assert by_name[\\\"broken-time\\\"][\\\"created\\\"] == 0  # invalid value degrades safely\\n    assert by_name[\\\"no-time\\\"][\\\"created\\\"] == 0\\n\\n\\ndef test_fetch_live_openrouter_models_derives_tool_calling_and_reasoning_per_model():\\n    from lfx.base.models import model_utils\\n\\n    response = _models_payload(\\n        [\\n            # tools + reasoning both present\\n            {\\\"id\\\": \\\"anthropic/claude-opus\\\", \\\"supported_parameters\\\": [\\\"tools\\\", \\\"reasoning\\\", \\\"temperature\\\"]},\\n            # tools only\\n            {\\\"id\\\": \\\"openai/gpt-4o\\\", \\\"supported_parameters\\\": [\\\"tools\\\"]},\\n            # reasoning only \u2014 e.g. older o1-style models\\n            {\\\"id\\\": \\\"openai/o1-think\\\", \\\"supported_parameters\\\": [\\\"reasoning\\\"]},\\n            # neither\\n            {\\\"id\\\": \\\"perceptron/perceptron-mk1\\\", \\\"supported_parameters\\\": [\\\"temperature\\\", \\\"top_p\\\"]},\\n            # missing supported_parameters \u2192 both False\\n            {\\\"id\\\": \\\"broken-model\\\"},\\n        ]\\n    )\\n    with (\\n        patch.object(model_utils, \\\"get_provider_variable_value\\\", return_value=\\\"dummy-key\\\"),  # pragma: allowlist secret\\n        patch.object(model_utils.httpx, \\\"get\\\", return_value=response) as mock_get,\\n    ):\\n        result = model_utils.fetch_live_openrouter_models(\\\"user-id\\\", \\\"llm\\\")\\n\\n    mock_get.assert_called_once()\\n    call = mock_get.call_args\\n    assert call.args[0] == \\\"https://openrouter.ai/api/v1/models\\\"\\n    assert call.kwargs[\\\"headers\\\"][\\\"Authorization\\\"].startswith(\\\"Bearer \\\")\\n\\n    by_name = {m[\\\"name\\\"]: m for m in result}\\n\\n    assert by_name[\\\"anthropic/claude-opus\\\"][\\\"tool_calling\\\"] is True\\n    assert by_name[\\\"anthropic/claude-opus\\\"][\\\"reasoning\\\"] is True\\n\\n    assert by_name[\\\"openai/gpt-4o\\\"][\\\"tool_calling\\\"] is True\\n    assert by_name[\\\"openai/gpt-4o\\\"][\\\"reasoning\\\"] is False\\n\\n    assert by_name[\\\"openai/o1-think\\\"][\\\"tool_calling\\\"] is False\\n    assert by_name[\\\"openai/o1-think\\\"][\\\"reasoning\\\"] is True\\n\\n    assert by_name[\\\"perceptron/perceptron-mk1\\\"][\\\"tool_calling\\\"] is False\\n    assert by_name[\\\"perceptron/perceptron-mk1\\\"][\\\"reasoning\\\"] is False\\n\\n    assert by_name[\\\"broken-model\\\"][\\\"tool_calling\\\"] is False\\n    assert by_name[\\\"broken-model\\\"][\\\"reasoning\\\"] is False\\n\\n    for entry in result:\\n        assert entry[\\\"provider\\\"] == \\\"OpenRouter\\\"\\n        assert entry[\\\"icon\\\"] == \\\"OpenRouter\\\"\\n\\n\\ndef test_fetch_live_openrouter_models_defaults_intersect_with_seed_list():\\n    \\\"\\\"\\\"Seed slugs in the live catalog drive the ``default`` flag.\\n\\n    The curated seed list should win regardless of alphabetical ordering \u2014 seed\\n    slugs that happen to sort late (e.g. ``openai/...``) must still be marked\\n    default when present in the live catalog.\\n    \\\"\\\"\\\"\\n    from lfx.base.models import model_utils\\n    from lfx.base.models.openrouter_constants import OPENROUTER_MODELS_DETAILED\\n\\n    seed_names = [m[\\\"name\\\"] for m in OPENROUTER_MODELS_DETAILED]\\n    # Two seed ids plus three non-seed ids. The seed ids may sort late\\n    # alphabetically (e.g. ``openai/...``), so alphabetical default-picking\\n    # would pick the non-seed ids first \u2014 this asserts we don't do that.\\n    live_entries = [\\n        {\\\"id\\\": \\\"aaa/zzz-non-seed-1\\\", \\\"supported_parameters\\\": [\\\"tools\\\"]},\\n        {\\\"id\\\": \\\"aab/zzz-non-seed-2\\\", \\\"supported_parameters\\\": []},\\n        {\\\"id\\\": \\\"aac/zzz-non-seed-3\\\", \\\"supported_parameters\\\": [\\\"tools\\\"]},\\n        {\\\"id\\\": seed_names[0], \\\"supported_parameters\\\": [\\\"tools\\\"]},\\n        {\\\"id\\\": seed_names[1], \\\"supported_parameters\\\": [\\\"tools\\\"]},\\n    ]\\n    response = _models_payload(live_entries)\\n\\n    with (\\n        patch.object(model_utils, \\\"get_provider_variable_value\\\", return_value=\\\"dummy-key\\\"),  # pragma: allowlist secret\\n        patch.object(model_utils.httpx, \\\"get\\\", return_value=response),\\n    ):\\n        result = model_utils.fetch_live_openrouter_models(\\\"user-id\\\", \\\"llm\\\")\\n\\n    defaults = {m[\\\"name\\\"] for m in result if m.get(\\\"default\\\")}\\n    assert defaults == {seed_names[0], seed_names[1]}\\n\\n\\ndef test_fetch_live_openrouter_models_defaults_fall_back_when_no_seed_overlap():\\n    \\\"\\\"\\\"No seed/live intersection falls back to the first MIN_DEFAULT_MODELS.\\n\\n    Guards against the seed list going stale: if no seed slug appears in the\\n    live catalog, the first ``MIN_DEFAULT_MODELS`` (alphabetical) become the\\n    defaults so the UI is never devoid of suggestions.\\n    \\\"\\\"\\\"\\n    from lfx.base.models import model_utils\\n    from lfx.base.models.model_utils import MIN_DEFAULT_MODELS\\n\\n    live_ids = [f\\\"vendor/model-{ch}\\\" for ch in \\\"abcdefghi\\\"]  # 9 ids, none in seed list\\n    response = _models_payload([{\\\"id\\\": mid, \\\"supported_parameters\\\": [\\\"tools\\\"]} for mid in live_ids])\\n\\n    with (\\n        patch.object(model_utils, \\\"get_provider_variable_value\\\", return_value=\\\"dummy-key\\\"),  # pragma: allowlist secret\\n        patch.object(model_utils.httpx, \\\"get\\\", return_value=response),\\n    ):\\n        result = model_utils.fetch_live_openrouter_models(\\\"user-id\\\", \\\"llm\\\")\\n\\n    defaults = {m[\\\"name\\\"] for m in result if m.get(\\\"default\\\")}\\n    assert len(defaults) == MIN_DEFAULT_MODELS\\n    # The first MIN_DEFAULT_MODELS sorted alphabetically.\\n    assert defaults == set(sorted(live_ids)[:MIN_DEFAULT_MODELS])\\n\\n\\ndef test_fetch_live_openrouter_models_swallows_request_error():\\n    from lfx.base.models import model_utils\\n\\n    failing_get = MagicMock(side_effect=httpx.RequestError(\\\"network down\\\"))\\n    with (\\n        patch.object(model_utils, \\\"get_provider_variable_value\\\", return_value=\\\"dummy-key\\\"),  # pragma: allowlist secret\\n        patch.object(model_utils.httpx, \\\"get\\\", failing_get),\\n    ):\\n        assert model_utils.fetch_live_openrouter_models(\\\"user-id\\\", \\\"llm\\\") == []\\n\\n\\ndef test_fetch_live_openrouter_models_swallows_http_status_error():\\n    \\\"\\\"\\\"A non-2xx response must degrade to ``[]``.\\n\\n    For example a 503 from OpenRouter during a brownout must not crash the\\n    caller; the user sees an empty live catalog plus a warning log.\\n    \\\"\\\"\\\"\\n    from lfx.base.models import model_utils\\n\\n    bad_response = MagicMock()\\n    bad_response.status_code = 503\\n    bad_response.raise_for_status.side_effect = httpx.HTTPStatusError(\\n        \\\"service unavailable\\\", request=MagicMock(), response=bad_response\\n    )\\n    with (\\n        patch.object(model_utils, \\\"get_provider_variable_value\\\", return_value=\\\"dummy-key\\\"),  # pragma: allowlist secret\\n        patch.object(model_utils.httpx, \\\"get\\\", return_value=bad_response),\\n    ):\\n        assert model_utils.fetch_live_openrouter_models(\\\"user-id\\\", \\\"llm\\\") == []\\n\\n\\ndef test_fetch_live_openrouter_models_swallows_malformed_payload():\\n    \\\"\\\"\\\"A 200 response with a non-list ``data`` field must not raise.\\\"\\\"\\\"\\n    from lfx.base.models import model_utils\\n\\n    weird_response = MagicMock()\\n    weird_response.json.return_value = {\\\"data\\\": \\\"not-a-list\\\"}\\n    weird_response.raise_for_status.return_value = None\\n    with (\\n        patch.object(model_utils, \\\"get_provider_variable_value\\\", return_value=\\\"dummy-key\\\"),  # pragma: allowlist secret\\n        patch.object(model_utils.httpx, \\\"get\\\", return_value=weird_response),\\n    ):\\n        assert model_utils.fetch_live_openrouter_models(\\\"user-id\\\", \\\"llm\\\") == []\\n\\n\\ndef test_get_live_models_dispatches_to_openrouter():\\n    from lfx.base.models import model_utils\\n\\n    with patch.object(model_utils, \\\"fetch_live_openrouter_models\\\", return_value=[{\\\"name\\\": \\\"x\\\"}]) as mocked:\\n        result = model_utils.get_live_models_for_provider(\\\"user-id\\\", \\\"OpenRouter\\\", \\\"llm\\\")\\n    mocked.assert_called_once_with(\\\"user-id\\\", \\\"llm\\\")\\n    assert result == [{\\\"name\\\": \\\"x\\\"}]\\n\\n\\n# ---------------------------------------------------------------------------\\n# Validation\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_validate_openrouter_no_key_returns_silently():\\n    from lfx.base.models.unified_models import validate_model_provider_key\\n\\n    # No exception expected \u2014 empty key short-circuits without raising.\\n    validate_model_provider_key(\\\"OpenRouter\\\", {})\\n\\n\\ndef test_validate_provider_uses_requested_model_name():\\n    \\\"\\\"\\\"Dynamic catalog order must not change which model a toggle validates.\\\"\\\"\\\"\\n    from types import SimpleNamespace\\n\\n    from lfx.base.models.unified_models import validate_model_provider_key\\n\\n    calls = []\\n\\n    class FakeChatOpenAI:\\n        def __init__(self, **kwargs):\\n            calls.append(kwargs)\\n\\n        def invoke(self, _prompt):\\n            return \\\"ok\\\"\\n\\n    catalog = [{\\\"provider\\\": \\\"OpenAI\\\", \\\"models\\\": [{\\\"model_name\\\": \\\"gpt-5.5-pro\\\"}]}]\\n    with (\\n        patch.dict(\\\"sys.modules\\\", {\\\"langchain_openai\\\": SimpleNamespace(ChatOpenAI=FakeChatOpenAI)}),\\n        patch(\\\"lfx.base.models.unified_models.model_catalog.get_unified_models_detailed\\\", return_value=catalog),\\n    ):\\n        validate_model_provider_key(\\n            \\\"OpenAI\\\",\\n            {\\\"OPENAI_API_KEY\\\": \\\"dummy-openai-key\\\"},  # pragma: allowlist secret\\n            model_name=\\\"gpt-4o-mini\\\",\\n        )\\n\\n    assert calls[0][\\\"model_name\\\"] == \\\"gpt-4o-mini\\\"\\n\\n\\ndef test_validate_openrouter_happy_path():\\n    \\\"\\\"\\\"Validation passes when ``GET /api/v1/auth/key`` returns 200.\\n\\n    Patches ``requests.get`` on the actually-imported module (not via\\n    ``sys.modules``) so the test stays correct if the lazy import inside\\n    ``credentials.py`` is ever hoisted to module-level.\\n    \\\"\\\"\\\"\\n    from lfx.base.models.unified_models import validate_model_provider_key\\n\\n    response = MagicMock()\\n    response.status_code = 200\\n    response.raise_for_status.return_value = None\\n\\n    with patch.object(requests, \\\"get\\\", return_value=response) as mock_get:\\n        validate_model_provider_key(\\n            \\\"OpenRouter\\\",\\n            {\\\"OPENROUTER_API_KEY\\\": \\\"dummy-openrouter-key\\\"},  # pragma: allowlist secret\\n        )\\n\\n    mock_get.assert_called_once()\\n    call = mock_get.call_args\\n    # ``/api/v1/auth/key`` is auth-required (returns 401 on invalid bearer).\\n    # The previous ``/api/v1/models`` URL is a public endpoint that returns\\n    # 200 for any auth, so it could never detect an invalid key.\\n    assert call.args[0] == \\\"https://openrouter.ai/api/v1/auth/key\\\"\\n    assert call.kwargs[\\\"headers\\\"][\\\"Authorization\\\"].startswith(\\\"Bearer \\\")\\n\\n\\ndef test_validate_openrouter_raises_on_401():\\n    from lfx.base.models.unified_models import validate_model_provider_key\\n\\n    response = MagicMock()\\n    response.status_code = 401\\n    response.raise_for_status.side_effect = AssertionError(\\\"should not be called when 401 path triggers\\\")\\n\\n    with (\\n        patch.object(requests, \\\"get\\\", return_value=response),\\n        pytest.raises(ValueError, match=\\\"Invalid OpenRouter API key\\\"),\\n    ):\\n        validate_model_provider_key(\\n            \\\"OpenRouter\\\",\\n            {\\\"OPENROUTER_API_KEY\\\": \\\"dummy-openrouter-bad\\\"},  # pragma: allowlist secret\\n        )\\n\\n\\ndef test_validate_openrouter_uses_auth_endpoint_not_public_models_endpoint():\\n    \\\"\\\"\\\"Regression: the validation endpoint must be auth-required.\\n\\n    OpenRouter's ``/api/v1/models`` returns 200 regardless of the Authorization\\n    header (it is a public catalog). The previous implementation called that\\n    endpoint, so invalid keys were accepted silently and the credential save\\n    flow returned 201 instead of the documented 400. This test pins the URL to\\n    an auth-required endpoint so a future refactor cannot regress it.\\n    \\\"\\\"\\\"\\n    from lfx.base.models.unified_models import validate_model_provider_key\\n\\n    response = MagicMock()\\n    response.status_code = 200\\n    response.raise_for_status.return_value = None\\n\\n    with patch.object(requests, \\\"get\\\", return_value=response) as mock_get:\\n        validate_model_provider_key(\\n            \\\"OpenRouter\\\",\\n            {\\\"OPENROUTER_API_KEY\\\": \\\"dummy-openrouter-key\\\"},  # pragma: allowlist secret\\n        )\\n\\n    call_url = mock_get.call_args.args[0]\\n    assert call_url != \\\"https://openrouter.ai/api/v1/models\\\", (\\n        \\\"OpenRouter /api/v1/models is public \u2014 using it for validation cannot detect invalid keys\\\"\\n    )\\n    assert call_url.startswith(\\\"https://openrouter.ai/api/v1/\\\")\\n\\n\\ndef test_validate_openrouter_network_error_raises_value_error():\\n    \\\"\\\"\\\"Transport errors must surface as ``ValueError``.\\n\\n    The variable API only catches ``ValueError`` and returns a user-facing 400;\\n    any other exception escapes as an unhandled 500. A DNS / timeout / 5xx\\n    during validation must take that ValueError path.\\n    \\\"\\\"\\\"\\n    from lfx.base.models.unified_models import validate_model_provider_key\\n\\n    with (\\n        patch.object(requests, \\\"get\\\", side_effect=requests.ConnectionError(\\\"DNS lookup failed\\\")),\\n        pytest.raises(ValueError, match=\\\"Could not reach OpenRouter\\\"),\\n    ):\\n        validate_model_provider_key(\\n            \\\"OpenRouter\\\",\\n            {\\\"OPENROUTER_API_KEY\\\": \\\"dummy-openrouter-key\\\"},  # pragma: allowlist secret\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# Instantiation\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _build_model_selection(name: str = \\\"anthropic/claude-3.5-sonnet\\\") -> list[dict]:\\n    return [\\n        {\\n            \\\"name\\\": name,\\n            \\\"provider\\\": \\\"OpenRouter\\\",\\n            \\\"metadata\\\": {\\n                \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                \\\"model_name_param\\\": \\\"model\\\",\\n                \\\"api_key_param\\\": \\\"api_key\\\",  # pragma: allowlist secret\\n            },\\n        }\\n    ]\\n\\n\\ndef test_get_llm_for_openrouter_sets_base_url_and_headers():\\n    from lfx.base.models import unified_models as unified_models_module\\n    from lfx.base.models.unified_models.instantiation import get_llm\\n\\n    captured_kwargs: dict = {}\\n\\n    class FakeChatOpenAI:\\n        def __init__(self, **kwargs):\\n            captured_kwargs.update(kwargs)\\n\\n    with (\\n        patch.object(\\n            unified_models_module, \\\"get_api_key_for_provider\\\", return_value=\\\"dummy-openrouter-key\\\"\\n        ),  # pragma: allowlist secret\\n        patch.object(unified_models_module, \\\"get_model_class\\\", return_value=FakeChatOpenAI),\\n        patch.object(\\n            unified_models_module,\\n            \\\"get_all_variables_for_provider\\\",\\n            return_value={\\n                \\\"OPENROUTER_API_KEY\\\": \\\"dummy-openrouter-key\\\",  # pragma: allowlist secret\\n                \\\"OPENROUTER_SITE_URL\\\": \\\"https://example.com\\\",\\n                \\\"OPENROUTER_APP_NAME\\\": \\\"My App\\\",\\n            },\\n        ),\\n    ):\\n        get_llm(_build_model_selection(), user_id=None)\\n\\n    assert captured_kwargs[\\\"model\\\"] == \\\"anthropic/claude-3.5-sonnet\\\"\\n    assert captured_kwargs[\\\"api_key\\\"] == \\\"dummy-openrouter-key\\\"  # pragma: allowlist secret\\n    assert captured_kwargs[\\\"base_url\\\"] == \\\"https://openrouter.ai/api/v1\\\"\\n    assert captured_kwargs[\\\"default_headers\\\"] == {\\n        \\\"HTTP-Referer\\\": \\\"https://example.com\\\",\\n        \\\"X-Title\\\": \\\"My App\\\",\\n    }\\n\\n\\ndef test_get_llm_for_openrouter_omits_headers_when_not_configured():\\n    from lfx.base.models import unified_models as unified_models_module\\n    from lfx.base.models.unified_models.instantiation import get_llm\\n\\n    captured_kwargs: dict = {}\\n\\n    class FakeChatOpenAI:\\n        def __init__(self, **kwargs):\\n            captured_kwargs.update(kwargs)\\n\\n    with (\\n        patch.object(\\n            unified_models_module, \\\"get_api_key_for_provider\\\", return_value=\\\"dummy-openrouter-key\\\"\\n        ),  # pragma: allowlist secret\\n        patch.object(unified_models_module, \\\"get_model_class\\\", return_value=FakeChatOpenAI),\\n        patch.object(\\n            unified_models_module,\\n            \\\"get_all_variables_for_provider\\\",\\n            return_value={\\\"OPENROUTER_API_KEY\\\": \\\"dummy-openrouter-key\\\"},  # pragma: allowlist secret\\n        ),\\n    ):\\n        get_llm(_build_model_selection(), user_id=None)\\n\\n    assert captured_kwargs[\\\"base_url\\\"] == \\\"https://openrouter.ai/api/v1\\\"\\n    assert \\\"default_headers\\\" not in captured_kwargs\\n\\n\\ndef test_get_llm_for_openrouter_reads_attribution_headers_from_environment(monkeypatch):\\n    \\\"\\\"\\\"Header vars resolve from os.environ when no global variable is stored.\\n\\n    Mirrors the OpenAI / Ollama env-fallback pattern so a self-hosted operator\\n    can wire attribution via shell env without touching the database.\\n    \\\"\\\"\\\"\\n    from lfx.base.models import unified_models as unified_models_module\\n    from lfx.base.models.unified_models.instantiation import get_llm\\n\\n    monkeypatch.setenv(\\\"OPENROUTER_SITE_URL\\\", \\\"https://env.example.com\\\")\\n    monkeypatch.setenv(\\\"OPENROUTER_APP_NAME\\\", \\\"EnvApp\\\")\\n\\n    captured_kwargs: dict = {}\\n\\n    class FakeChatOpenAI:\\n        def __init__(self, **kwargs):\\n            captured_kwargs.update(kwargs)\\n\\n    with (\\n        patch.object(\\n            unified_models_module, \\\"get_api_key_for_provider\\\", return_value=\\\"dummy-openrouter-key\\\"\\n        ),  # pragma: allowlist secret\\n        patch.object(unified_models_module, \\\"get_model_class\\\", return_value=FakeChatOpenAI),\\n        patch.object(\\n            unified_models_module,\\n            \\\"get_all_variables_for_provider\\\",\\n            return_value={\\\"OPENROUTER_API_KEY\\\": \\\"dummy-openrouter-key\\\"},  # pragma: allowlist secret\\n        ),\\n    ):\\n        get_llm(_build_model_selection(), user_id=None)\\n\\n    assert captured_kwargs[\\\"default_headers\\\"] == {\\n        \\\"HTTP-Referer\\\": \\\"https://env.example.com\\\",\\n        \\\"X-Title\\\": \\\"EnvApp\\\",\\n    }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/models/test_provider_registry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"38413c4e4312cf7541c44f7485cd86ae391d782c93c755fc28298f85f61cd19c\",\"content\":\"\\\"\\\"\\\"Unit tests for the bundle model-provider registry.\\n\\nCovers:\\n  - register_provider merges a provider into the core tables in place and is\\n    visible through every existing accessor (get_model_providers,\\n    get_model_provider_metadata, the @lru_cache-d variable map).\\n  - Core providers win on name collision; duplicate bundle registration is a\\n    no-op.\\n  - api-key-optional, live-discovery, and credential-validation dispatch route\\n    to the registered provider.\\n  - Embedding wiring lands in the class/param tables.\\n  - clear() restores the byte-identical baseline (zero-bundle behavior).\\n  - Invalid specs raise.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom lfx.base.models import provider_registry\\nfrom lfx.base.models.model_metadata import LIVE_MODEL_PROVIDERS, MODEL_PROVIDER_METADATA\\nfrom lfx.base.models.model_utils import get_live_models_for_provider\\nfrom lfx.base.models.provider_registry import ProviderSpec, register_provider, resolve_provider_id\\nfrom lfx.base.models.unified_models import (\\n    get_live_only_providers,\\n    get_model_provider_metadata,\\n    get_model_provider_variable_mapping,\\n    get_model_providers,\\n    get_models_detailed,\\n    get_provider_all_variables,\\n    get_provider_secret_variable_key,\\n    instantiation,\\n    validate_model_provider_key,\\n)\\nfrom lfx.base.models.unified_models.class_registry import (\\n    EMBEDDING_PARAM_MAPPINGS,\\n    EMBEDDING_PROVIDER_CLASS_MAPPING,\\n)\\n\\n# ---------------------------------------------------------------------------\\n# Importable callables referenced by ProviderSpec dotted paths. Resolved via\\n# importlib against this module's name -- robust because the running test module\\n# is already in sys.modules, so import_module returns it from cache.\\n# ---------------------------------------------------------------------------\\n\\n_validator_calls: list[tuple] = []\\n\\n\\ndef fake_live_discovery(user_id, model_type):  # noqa: ARG001\\n    return [{\\\"provider\\\": \\\"FakeCo\\\", \\\"name\\\": f\\\"fake-{model_type}\\\", \\\"icon\\\": \\\"FakeCo\\\"}]\\n\\n\\ndef fake_validator(provider, variables, model_name):\\n    _validator_calls.append((provider, dict(variables), model_name))\\n    if variables.get(\\\"FAKECO_API_KEY\\\") == \\\"bad\\\":  # pragma: allowlist secret\\n        msg = \\\"FakeCo credentials rejected\\\"\\n        raise ValueError(msg)\\n\\n\\n_LIVE_DISCOVERY_PATH = f\\\"{__name__}:fake_live_discovery\\\"\\n_VALIDATOR_PATH = f\\\"{__name__}:fake_validator\\\"\\n\\n\\ndef fake_catalog_loader():\\n    \\\"\\\"\\\"Return rows whose provider ownership must be stamped by the registry.\\\"\\\"\\\"\\n    return [\\n        {\\n            \\\"provider\\\": \\\"Untrusted manifest value\\\",\\n            \\\"name\\\": \\\"fake-chat-1\\\",\\n            \\\"icon\\\": \\\"FakeCo\\\",\\n            \\\"default\\\": True,\\n            \\\"model_type\\\": \\\"llm\\\",\\n        },\\n        {\\n            \\\"name\\\": \\\"fake-embed-1\\\",\\n            \\\"icon\\\": \\\"FakeCo\\\",\\n            \\\"default\\\": True,\\n            \\\"model_type\\\": \\\"embeddings\\\",\\n        },\\n    ]\\n\\n\\ndef duplicate_whitespace_catalog_loader():\\n    \\\"\\\"\\\"Return duplicate model identities after registry normalization.\\\"\\\"\\\"\\n    return [\\n        {\\\"name\\\": \\\"fake-chat-1\\\", \\\"model_type\\\": \\\"llm\\\"},\\n        {\\\"name\\\": \\\" fake-chat-1 \\\", \\\"model_type\\\": \\\"llm\\\"},\\n    ]\\n\\n\\n_CATALOG_LOADER_PATH = f\\\"{__name__}:fake_catalog_loader\\\"\\n_DUPLICATE_CATALOG_LOADER_PATH = f\\\"{__name__}:duplicate_whitespace_catalog_loader\\\"\\n\\n\\ndef _fakeco_metadata() -> dict:\\n    return {\\n        \\\"icon\\\": \\\"FakeCo\\\",\\n        \\\"max_tokens_field_name\\\": \\\"max_tokens\\\",\\n        \\\"variables\\\": [\\n            {\\n                \\\"variable_name\\\": \\\"FakeCo API Key\\\",\\n                \\\"variable_key\\\": \\\"FAKECO_API_KEY\\\",\\n                \\\"required\\\": True,\\n                \\\"is_secret\\\": True,\\n                \\\"is_list\\\": False,\\n                \\\"options\\\": [],\\n                \\\"langchain_param\\\": \\\"api_key\\\",\\n            },\\n        ],\\n        \\\"api_docs_url\\\": \\\"https://fakeco.example/docs\\\",\\n        \\\"mapping\\\": {\\\"model_class\\\": \\\"ChatOpenAI\\\", \\\"model_param\\\": \\\"model\\\"},\\n    }\\n\\n\\ndef _fakeco_spec(**overrides) -> ProviderSpec:\\n    kwargs: dict = {\\\"name\\\": \\\"FakeCo\\\", \\\"metadata\\\": _fakeco_metadata()}\\n    kwargs.update(overrides)\\n    return ProviderSpec(**kwargs)\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _isolate_registry():\\n    \\\"\\\"\\\"Ensure no registration leaks across tests.\\\"\\\"\\\"\\n    provider_registry.clear()\\n    _validator_calls.clear()\\n    yield\\n    provider_registry.clear()\\n\\n\\n# ---------------------------------------------------------------------------\\n# Registration + visibility\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_register_adds_metadata_and_appears_in_accessors():\\n    assert \\\"FakeCo\\\" not in get_model_providers()\\n\\n    assert register_provider(_fakeco_spec()) is True\\n\\n    assert MODEL_PROVIDER_METADATA[\\\"FakeCo\\\"][\\\"icon\\\"] == \\\"FakeCo\\\"\\n    assert \\\"FakeCo\\\" in get_model_provider_metadata()\\n    # Appears even though FakeCo ships no static model catalog.\\n    assert \\\"FakeCo\\\" in get_model_providers()\\n\\n\\ndef test_register_exposes_stable_identity_display_name_and_aliases():\\n    register_provider(\\n        _fakeco_spec(\\n            provider_id=\\\"fakeco.enterprise\\\",\\n            display_name=\\\"FakeCo Enterprise\\\",\\n            aliases=(\\\"fake-co\\\", \\\"FakeCo Legacy\\\"),\\n        )\\n    )\\n\\n    assert provider_registry.provider_id_for(\\\"FakeCo\\\") == \\\"fakeco.enterprise\\\"\\n    assert provider_registry.provider_id_for(\\\"fake-co\\\") == \\\"fakeco.enterprise\\\"\\n    assert provider_registry.provider_id_for(\\\"FakeCo Legacy\\\") == \\\"fakeco.enterprise\\\"\\n    assert provider_registry.provider_name_for_id(\\\"fakeco.enterprise\\\") == \\\"FakeCo\\\"\\n    assert MODEL_PROVIDER_METADATA[\\\"FakeCo\\\"][\\\"provider_id\\\"] == \\\"fakeco.enterprise\\\"\\n    assert MODEL_PROVIDER_METADATA[\\\"FakeCo\\\"][\\\"display_name\\\"] == \\\"FakeCo Enterprise\\\"\\n\\n\\ndef test_resolve_provider_id_accepts_names_ids_aliases_and_legacy_unknowns():\\n    register_provider(\\n        _fakeco_spec(\\n            provider_id=\\\"fakeco.enterprise\\\",\\n            display_name=\\\"FakeCo Enterprise\\\",\\n            aliases=(\\\"FakeCo Legacy\\\",),\\n        )\\n    )\\n\\n    assert resolve_provider_id(\\\"FakeCo\\\") == \\\"fakeco.enterprise\\\"\\n    assert resolve_provider_id(\\\"fakeco.enterprise\\\") == \\\"fakeco.enterprise\\\"\\n    assert resolve_provider_id(\\\"FakeCo Enterprise\\\") == \\\"fakeco.enterprise\\\"\\n    assert resolve_provider_id(\\\"FakeCo Legacy\\\") == \\\"fakeco.enterprise\\\"\\n    assert resolve_provider_id(\\\"Legacy Custom Provider\\\") == \\\"legacy-custom-provider\\\"\\n\\n\\ndef test_resolve_provider_id_uses_opaque_fallback_for_non_sluggable_legacy_selectors():\\n    provider_id = resolve_provider_id(\\\" \u0394 \\\")\\n\\n    assert provider_id == resolve_provider_id(\\\"\u03b4\\\")\\n    assert provider_id.startswith(\\\"legacy-\\\")\\n    assert provider_registry._PROVIDER_ID_RE.fullmatch(provider_id)\\n    assert \\\"\u0394\\\" not in provider_id\\n    assert provider_id != resolve_provider_id(\\\"!!!\\\")\\n\\n\\ndef test_provider_registration_remains_strict_for_non_sluggable_names():\\n    with pytest.raises(ValueError, match=\\\"Could not derive a provider_id\\\"):\\n        register_provider(_fakeco_spec(name=\\\"!!!\\\"))\\n\\n\\ndef test_provider_queries_accept_stable_id_and_legacy_alias():\\n    canonical_variables = get_provider_all_variables(\\\"IBM WatsonX\\\")\\n\\n    assert canonical_variables\\n    assert get_provider_all_variables(\\\"IBM watsonx.ai\\\") == canonical_variables\\n    assert get_provider_all_variables(\\\"ibm-watsonx\\\") == canonical_variables\\n    assert get_provider_secret_variable_key(\\\"IBM watsonx.ai\\\") == get_provider_secret_variable_key(\\\"IBM WatsonX\\\")\\n\\n\\n@pytest.mark.parametrize(\\\"provider\\\", [\\\"\\\", \\\"   \\\"])\\ndef test_resolve_provider_id_rejects_empty_values(provider):\\n    with pytest.raises(ValueError, match=\\\"non-empty\\\"):\\n        resolve_provider_id(provider)\\n\\n\\ndef test_model_component_explicit_identity_wins_over_ambiguous_module_name():\\n    class AzureEmbeddingComponent:\\n        display_name = \\\"Azure OpenAI Embeddings\\\"\\n        model_provider_id = \\\"azure-openai\\\"\\n\\n    assert provider_registry.model_component_provider_id(AzureEmbeddingComponent()) == \\\"azure-openai\\\"\\n\\n\\ndef test_model_component_policy_mode_distinguishes_delegate_and_opt_out():\\n    class Component:\\n        model_provider_policy_mode = \\\"delegate\\\"\\n\\n    assert provider_registry.uses_standalone_model_provider_policy(Component()) is False\\n    Component.model_provider_policy_mode = \\\"none\\\"\\n    assert provider_registry.uses_standalone_model_provider_policy(Component()) is False\\n\\n\\ndef test_model_component_policy_mode_reads_inherited_annotated_declaration():\\n    class DelegatingBase:\\n        model_provider_policy_mode: str = \\\"delegate\\\"\\n\\n    class Component(DelegatingBase):\\n        pass\\n\\n    assert provider_registry.model_component_policy_mode(Component()) == \\\"delegate\\\"\\n    assert provider_registry.uses_standalone_model_provider_policy(Component()) is False\\n\\n\\n@pytest.mark.parametrize(\\\"mode\\\", [\\\"standalone\\\", \\\"standlone\\\", \\\"\\\", None])\\ndef test_model_component_policy_mode_fails_closed_for_unknown_modes(mode):\\n    class Component:\\n        model_provider_policy_mode = mode\\n\\n    assert provider_registry.model_component_policy_mode(Component()) == \\\"standalone\\\"\\n    assert provider_registry.uses_standalone_model_provider_policy(Component()) is True\\n\\n\\ndef test_model_component_policy_mode_defaults_to_standalone():\\n    class Component:\\n        pass\\n\\n    assert provider_registry.uses_standalone_model_provider_policy(Component()) is True\\n\\n\\ndef test_registry_snapshot_deep_freezes_descriptor_payloads():\\n    register_provider(_fakeco_spec(provider_id=\\\"fakeco\\\"))\\n\\n    descriptor = provider_registry.get_registry_snapshot().descriptors_by_id[\\\"fakeco\\\"]\\n\\n    with pytest.raises(TypeError):\\n        descriptor.metadata[\\\"icon\\\"] = \\\"Spoofed\\\"  # type: ignore[index]\\n    variables = descriptor.metadata[\\\"variables\\\"]\\n    with pytest.raises(TypeError):\\n        variables[0][\\\"variable_key\\\"] = \\\"SPOOFED_KEY\\\"  # type: ignore[index]\\n\\n    assert MODEL_PROVIDER_METADATA[\\\"FakeCo\\\"][\\\"icon\\\"] == \\\"FakeCo\\\"\\n    assert MODEL_PROVIDER_METADATA[\\\"FakeCo\\\"][\\\"variables\\\"][0][\\\"variable_key\\\"] == \\\"FAKECO_API_KEY\\\"\\n\\n\\ndef test_registered_catalog_loader_contributes_static_models():\\n    register_provider(\\n        _fakeco_spec(\\n            provider_id=\\\"fakeco\\\",\\n            catalog_loader=_CATALOG_LOADER_PATH,\\n        )\\n    )\\n\\n    fakeco_groups = [\\n        group for group in get_models_detailed() if group and all(row.get(\\\"provider\\\") == \\\"FakeCo\\\" for row in group)\\n    ]\\n\\n    assert len(fakeco_groups) == 1\\n    assert [row[\\\"name\\\"] for row in fakeco_groups[0]] == [\\\"fake-chat-1\\\", \\\"fake-embed-1\\\"]\\n    assert {row[\\\"provider\\\"] for row in fakeco_groups[0]} == {\\\"FakeCo\\\"}\\n\\n\\ndef test_registered_catalog_rejects_duplicate_normalized_model_names():\\n    register_provider(\\n        _fakeco_spec(\\n            provider_id=\\\"fakeco\\\",\\n            catalog_loader=_DUPLICATE_CATALOG_LOADER_PATH,\\n        )\\n    )\\n\\n    with pytest.raises(ValueError, match=\\\"duplicate model identity\\\"):\\n        provider_registry.validate_registered_provider_catalogs()\\n\\n\\ndef test_duplicate_provider_id_is_rejected_even_when_names_differ():\\n    register_provider(_fakeco_spec(provider_id=\\\"fakeco\\\"))\\n\\n    with pytest.raises(ValueError, match=\\\"provider_id\\\"):\\n        register_provider(\\n            ProviderSpec(\\n                name=\\\"OtherCo\\\",\\n                provider_id=\\\"fakeco\\\",\\n                metadata={**_fakeco_metadata(), \\\"icon\\\": \\\"OtherCo\\\"},\\n            )\\n        )\\n\\n\\n@pytest.mark.parametrize(\\\"reserved_key\\\", [\\\"provider\\\", \\\"models\\\", \\\"num_models\\\", \\\"provider_id\\\", \\\"aliases\\\"])\\ndef test_provider_metadata_cannot_override_identity_or_catalog_structure(reserved_key):\\n    with pytest.raises(ValueError, match=\\\"reserved keys\\\"):\\n        register_provider(\\n            _fakeco_spec(\\n                metadata={**_fakeco_metadata(), reserved_key: \\\"OpenAI\\\"},\\n            )\\n        )\\n\\n\\ndef test_variable_mapping_cache_refreshed_after_register():\\n    # Prime the lru_cache before registration.\\n    before = get_model_provider_variable_mapping()\\n    assert \\\"FakeCo\\\" not in before\\n\\n    register_provider(_fakeco_spec())\\n\\n    after = get_model_provider_variable_mapping()\\n    assert after.get(\\\"FakeCo\\\") == \\\"FAKECO_API_KEY\\\"\\n\\n\\ndef test_core_provider_name_is_not_overwritten():\\n    original = MODEL_PROVIDER_METADATA[\\\"OpenAI\\\"]\\n    spoof = ProviderSpec(name=\\\"OpenAI\\\", metadata=_fakeco_metadata())\\n\\n    assert register_provider(spoof) is False\\n    assert MODEL_PROVIDER_METADATA[\\\"OpenAI\\\"] is original\\n    assert not provider_registry.is_registered(\\\"OpenAI\\\")\\n\\n\\ndef test_duplicate_bundle_registration_is_ignored():\\n    assert register_provider(_fakeco_spec()) is True\\n    assert register_provider(_fakeco_spec(metadata={**_fakeco_metadata(), \\\"icon\\\": \\\"Other\\\"})) is False\\n    # First registration wins.\\n    assert MODEL_PROVIDER_METADATA[\\\"FakeCo\\\"][\\\"icon\\\"] == \\\"FakeCo\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Live-only provider surface (feeds the /api/v1/models union)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_live_only_providers_empty_at_core_baseline():\\n    # Azure OpenAI / Groq carry metadata but no live gate and must not surface;\\n    # every live-capable core provider ships static catalog rows.\\n    assert get_live_only_providers() == []\\n\\n\\ndef test_live_registration_appears_in_live_only_providers():\\n    register_provider(_fakeco_spec(live=True, live_discovery=_LIVE_DISCOVERY_PATH))\\n    assert get_live_only_providers() == [\\\"FakeCo\\\"]\\n\\n\\ndef test_conditional_live_registration_appears_in_live_only_providers():\\n    register_provider(_fakeco_spec(conditional_live=True, live_discovery=_LIVE_DISCOVERY_PATH))\\n    assert get_live_only_providers() == [\\\"FakeCo\\\"]\\n\\n\\ndef test_non_live_registration_excluded_from_live_only_providers():\\n    # Without a live gate the provider could never list models; excluding it\\n    # mirrors the deliberate absence of Azure OpenAI / Groq from the unified UI.\\n    register_provider(_fakeco_spec())\\n    assert get_live_only_providers() == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# Behavior dispatch\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_api_key_optional_flag():\\n    register_provider(_fakeco_spec(api_key_required=False))\\n    assert provider_registry.is_api_key_optional(\\\"FakeCo\\\") is True\\n\\n\\ndef test_api_key_required_by_default():\\n    register_provider(_fakeco_spec())\\n    assert provider_registry.is_api_key_optional(\\\"FakeCo\\\") is False\\n\\n\\ndef test_live_provider_added_to_live_list_and_dispatches():\\n    register_provider(_fakeco_spec(live=True, live_discovery=_LIVE_DISCOVERY_PATH))\\n    assert \\\"FakeCo\\\" in LIVE_MODEL_PROVIDERS\\n\\n    models = get_live_models_for_provider(\\\"user-1\\\", \\\"FakeCo\\\", \\\"llm\\\")\\n    assert [m[\\\"name\\\"] for m in models] == [\\\"fake-llm\\\"]\\n\\n\\ndef _boom_discovery(user_id, model_type):  # noqa: ARG001\\n    msg = \\\"network down\\\"\\n    raise RuntimeError(msg)\\n\\n\\ndef test_live_discovery_failure_degrades_to_empty():\\n    # _boom_discovery imports fine but raises when called -> degrade to [].\\n    register_provider(_fakeco_spec(live=True, live_discovery=f\\\"{__name__}:_boom_discovery\\\"))\\n    assert get_live_models_for_provider(\\\"user-1\\\", \\\"FakeCo\\\", \\\"llm\\\") == []\\n\\n\\ndef test_unknown_live_discovery_path_degrades_to_empty():\\n    register_provider(_fakeco_spec(live=True, live_discovery=f\\\"{__name__}:does_not_exist\\\"))\\n    assert get_live_models_for_provider(\\\"user-1\\\", \\\"FakeCo\\\", \\\"llm\\\") == []\\n\\n\\ndef test_validator_dispatch_pass():\\n    register_provider(_fakeco_spec(validator=_VALIDATOR_PATH))\\n    validate_model_provider_key(\\\"FakeCo\\\", {\\\"FAKECO_API_KEY\\\": \\\"good\\\"})  # pragma: allowlist secret\\n    assert _validator_calls\\n    assert _validator_calls[0][0] == \\\"FakeCo\\\"\\n\\n\\ndef test_validator_dispatch_raises_on_bad_key():\\n    register_provider(_fakeco_spec(validator=_VALIDATOR_PATH))\\n    with pytest.raises(ValueError, match=\\\"FakeCo credentials rejected\\\"):\\n        validate_model_provider_key(\\\"FakeCo\\\", {\\\"FAKECO_API_KEY\\\": \\\"bad\\\"})  # pragma: allowlist secret\\n\\n\\ndef test_registered_provider_without_validator_is_noop():\\n    register_provider(_fakeco_spec())\\n    # No validator configured -> generic pass, no exception.\\n    validate_model_provider_key(\\\"FakeCo\\\", {\\\"FAKECO_API_KEY\\\": \\\"anything\\\"})  # pragma: allowlist secret\\n\\n\\ndef _boom_validator(provider, variables, model_name):  # noqa: ARG001\\n    msg = \\\"transport exploded\\\"\\n    raise RuntimeError(msg)\\n\\n\\ndef test_validator_non_value_error_is_normalized():\\n    # A bundle validator that raises a non-ValueError (e.g. a transport error)\\n    # is normalized to ValueError so it can't escape as an unhandled 500.\\n    register_provider(_fakeco_spec(validator=f\\\"{__name__}:_boom_validator\\\"))\\n    with pytest.raises(ValueError, match=\\\"Could not validate credentials\\\"):\\n        validate_model_provider_key(\\\"FakeCo\\\", {\\\"FAKECO_API_BASE\\\": \\\"x\\\"})\\n\\n\\n# ---------------------------------------------------------------------------\\n# Connection-variable application (get_llm / get_embeddings)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _fakeco_metadata_with_base_url() -> dict:\\n    meta = _fakeco_metadata()\\n    meta[\\\"variables\\\"] = [\\n        {\\n            \\\"variable_name\\\": \\\"FakeCo Base URL\\\",\\n            \\\"variable_key\\\": \\\"FAKECO_API_BASE\\\",\\n            \\\"required\\\": True,\\n            \\\"is_secret\\\": False,\\n            \\\"is_list\\\": False,\\n            \\\"options\\\": [],\\n            \\\"langchain_param\\\": \\\"base_url\\\",\\n        },\\n        *meta[\\\"variables\\\"],\\n    ]\\n    return meta\\n\\n\\ndef _fakeco_metadata_with_only_base_url() -> dict:\\n    \\\"\\\"\\\"Provider metadata with required connection config but no secret variable.\\\"\\\"\\\"\\n    meta = _fakeco_metadata()\\n    meta[\\\"variables\\\"] = [\\n        {\\n            \\\"variable_name\\\": \\\"FakeCo Base URL\\\",\\n            \\\"variable_key\\\": \\\"FAKECO_API_BASE\\\",\\n            \\\"required\\\": True,\\n            \\\"is_secret\\\": False,\\n            \\\"is_list\\\": False,\\n            \\\"options\\\": [],\\n            \\\"langchain_param\\\": \\\"base_url\\\",\\n        }\\n    ]\\n    return meta\\n\\n\\ndef test_get_llm_applies_registered_provider_base_url(monkeypatch):\\n    from lfx.base.models import unified_models as um\\n    from lfx.base.models.unified_models.instantiation import get_llm\\n\\n    captured: dict = {}\\n\\n    class FakeChat:\\n        def __init__(self, **kwargs):\\n            captured.update(kwargs)\\n\\n    register_provider(_fakeco_spec(metadata=_fakeco_metadata_with_base_url(), api_key_required=False))\\n    monkeypatch.setattr(um, \\\"get_api_key_for_provider\\\", lambda *_a, **_k: None)\\n    monkeypatch.setattr(um, \\\"get_model_class\\\", lambda _name: FakeChat)\\n    monkeypatch.setattr(\\n        um, \\\"get_all_variables_for_provider\\\", lambda *_a, **_k: {\\\"FAKECO_API_BASE\\\": \\\"http://vllm.example:8000\\\"}\\n    )\\n    monkeypatch.setattr(instantiation, \\\"ssrf_protected_openai_clients_for_url\\\", lambda _url: {})\\n\\n    model_selection = [\\n        {\\n            \\\"name\\\": \\\"m1\\\",\\n            \\\"provider\\\": \\\"FakeCo\\\",\\n            \\\"metadata\\\": {\\n                \\\"model_class\\\": \\\"ChatOpenAI\\\",\\n                \\\"model_name_param\\\": \\\"model\\\",\\n                \\\"api_key_param\\\": \\\"api_key\\\",  # pragma: allowlist secret\\n            },\\n        }\\n    ]\\n    get_llm(model_selection, user_id=None)\\n\\n    assert captured[\\\"model\\\"] == \\\"m1\\\"\\n    assert captured[\\\"base_url\\\"] == \\\"http://vllm.example:8000\\\"\\n    # api_key_optional provider with no configured key gets a non-empty placeholder.\\n    assert captured[\\\"api_key\\\"] == \\\"EMPTY\\\"  # pragma: allowlist secret\\n\\n\\ndef test_variable_mapping_prefers_secret_over_first_variable():\\n    # A provider whose first (required) variable is a non-secret base URL and\\n    # whose API key is an optional secret must map to the secret, not the base\\n    # URL -- otherwise get_api_key_for_provider would send the endpoint as the\\n    # bearer token.\\n    from lfx.base.models.unified_models import get_model_provider_variable_mapping\\n\\n    register_provider(_fakeco_spec(metadata=_fakeco_metadata_with_base_url(), api_key_required=False))\\n    assert get_model_provider_variable_mapping()[\\\"FakeCo\\\"] == \\\"FAKECO_API_KEY\\\"\\n\\n\\ndef test_get_llm_real_resolver_uses_placeholder_not_base_url(monkeypatch):\\n    # Exercise the REAL get_api_key_for_provider path (not a patched stub): with\\n    # only the base URL configured, the api_key must resolve to the \\\"EMPTY\\\"\\n    # placeholder, never the base URL.\\n    from lfx.base.models import unified_models as um\\n    from lfx.base.models.unified_models.instantiation import get_llm\\n\\n    captured: dict = {}\\n\\n    class FakeChat:\\n        def __init__(self, **kwargs):\\n            captured.update(kwargs)\\n\\n    register_provider(_fakeco_spec(metadata=_fakeco_metadata_with_only_base_url(), api_key_required=False))\\n    monkeypatch.setenv(\\\"FAKECO_API_BASE\\\", \\\"http://vllm.example:8000\\\")\\n    monkeypatch.setattr(um, \\\"get_model_class\\\", lambda _name: FakeChat)\\n    # Base URL comes from the env via the connection handler; do NOT patch the\\n    # api-key resolver -- that is the path under test.\\n    monkeypatch.setattr(um, \\\"get_all_variables_for_provider\\\", lambda *_a, **_k: {})\\n    monkeypatch.setattr(instantiation, \\\"ssrf_protected_openai_clients_for_url\\\", lambda _url: {})\\n\\n    # The broad mapping remains available to provider enablement/UI callers,\\n    # but neither implicit nor explicit API-key lookup may consume it.\\n    assert um.get_model_provider_variable_mapping()[\\\"FakeCo\\\"] == \\\"FAKECO_API_BASE\\\"\\n    assert um.get_api_key_for_provider(None, \\\"FakeCo\\\") is None\\n    assert um.get_api_key_for_provider(None, \\\"FakeCo\\\", \\\"FAKECO_API_BASE\\\") is None\\n\\n    model_selection = [{\\\"name\\\": \\\"m1\\\", \\\"provider\\\": \\\"FakeCo\\\", \\\"metadata\\\": {\\\"model_class\\\": \\\"ChatOpenAI\\\"}}]\\n    get_llm(model_selection, user_id=None)\\n\\n    assert captured[\\\"api_key\\\"] == \\\"EMPTY\\\"  # pragma: allowlist secret\\n    assert captured[\\\"base_url\\\"] == \\\"http://vllm.example:8000\\\"\\n\\n\\ndef test_get_embeddings_applies_registered_provider_base_url_and_key(monkeypatch):\\n    from lfx.base.models import unified_models as um\\n    from lfx.base.models.unified_models.instantiation import get_embeddings\\n\\n    captured: dict = {}\\n\\n    class FakeEmbeddings:\\n        def __init__(self, **kwargs):\\n            captured.update(kwargs)\\n\\n    register_provider(\\n        _fakeco_spec(\\n            metadata=_fakeco_metadata_with_base_url(),\\n            api_key_required=False,\\n            embedding_class_name=\\\"OpenAIEmbeddings\\\",\\n            embedding_param_key=\\\"FakeCo\\\",\\n            embedding_param_mapping={\\\"model\\\": \\\"model\\\", \\\"api_base\\\": \\\"base_url\\\"},\\n        )\\n    )\\n    monkeypatch.setattr(um, \\\"get_api_key_for_provider\\\", lambda *_a, **_k: None)\\n    monkeypatch.setattr(um, \\\"get_embedding_class\\\", lambda _name: FakeEmbeddings)\\n    monkeypatch.setattr(\\n        um, \\\"get_all_variables_for_provider\\\", lambda *_a, **_k: {\\\"FAKECO_API_BASE\\\": \\\"http://vllm.example:8000\\\"}\\n    )\\n    monkeypatch.setattr(instantiation, \\\"ssrf_protected_openai_clients_for_url\\\", lambda _url: {})\\n\\n    model_selection = [\\n        {\\n            \\\"name\\\": \\\"emb-1\\\",\\n            \\\"provider\\\": \\\"FakeCo\\\",\\n            \\\"metadata\\\": {\\n                \\\"embedding_class\\\": \\\"OpenAIEmbeddings\\\",\\n                \\\"param_mapping\\\": {\\\"model\\\": \\\"model\\\", \\\"api_base\\\": \\\"base_url\\\"},\\n            },\\n        }\\n    ]\\n    get_embeddings(model_selection, user_id=None)\\n\\n    assert captured[\\\"model\\\"] == \\\"emb-1\\\"\\n    assert captured[\\\"base_url\\\"] == \\\"http://vllm.example:8000\\\"\\n    # No \\\"api_key\\\" slot in param_mapping -> the seam still passes the placeholder.\\n    assert captured[\\\"api_key\\\"] == \\\"EMPTY\\\"  # pragma: allowlist secret\\n\\n\\n# ---------------------------------------------------------------------------\\n# Embedding wiring\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_embedding_wiring_registered():\\n    register_provider(\\n        _fakeco_spec(\\n            embedding_class_name=\\\"OpenAIEmbeddings\\\",\\n            embedding_param_key=\\\"FakeCo Embeddings\\\",\\n            embedding_param_mapping={\\\"model\\\": \\\"model\\\", \\\"api_key\\\": \\\"api_key\\\"},  # pragma: allowlist secret\\n        )\\n    )\\n    assert EMBEDDING_PROVIDER_CLASS_MAPPING[\\\"FakeCo\\\"] == \\\"OpenAIEmbeddings\\\"\\n    assert EMBEDDING_PARAM_MAPPINGS[\\\"FakeCo\\\"][\\\"api_key\\\"] == \\\"api_key\\\"  # pragma: allowlist secret\\n    assert EMBEDDING_PARAM_MAPPINGS[\\\"FakeCo Embeddings\\\"][\\\"api_key\\\"] == \\\"api_key\\\"  # pragma: allowlist secret\\n\\n\\n# ---------------------------------------------------------------------------\\n# Validation + baseline restoration\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_invalid_spec_missing_model_class_raises():\\n    bad_meta = {\\\"icon\\\": \\\"X\\\", \\\"variables\\\": [], \\\"mapping\\\": {}}\\n    with pytest.raises(ValueError, match=\\\"model_class\\\"):\\n        register_provider(ProviderSpec(name=\\\"BadCo\\\", metadata=bad_meta))\\n\\n\\ndef test_live_and_conditional_live_mutually_exclusive():\\n    with pytest.raises(ValueError, match=\\\"both live and conditional_live\\\"):\\n        register_provider(_fakeco_spec(live=True, conditional_live=True))\\n\\n\\ndef test_unknown_model_class_without_import_raises():\\n    meta = {**_fakeco_metadata(), \\\"mapping\\\": {\\\"model_class\\\": \\\"NoSuchModelClass\\\", \\\"model_param\\\": \\\"model\\\"}}\\n    with pytest.raises(ValueError, match=\\\"unknown model class\\\"):\\n        register_provider(_fakeco_spec(metadata=meta))\\n\\n\\ndef test_conflicting_model_class_import_raises():\\n    meta = {**_fakeco_metadata(), \\\"mapping\\\": {\\\"model_class\\\": \\\"ChatOpenAI\\\", \\\"model_param\\\": \\\"model\\\"}}\\n    # ChatOpenAI already maps to langchain_openai; a divergent import must be rejected.\\n    with pytest.raises(ValueError, match=\\\"conflicts with an existing import\\\"):\\n        register_provider(_fakeco_spec(metadata=meta, model_class=(\\\"some_other_pkg\\\", \\\"ChatOpenAI\\\", None)))\\n\\n\\ndef test_embedding_param_key_conflict_raises():\\n    # \\\"OpenAI\\\" is a core EMBEDDING_PARAM_MAPPINGS key; reusing it would let clear()\\n    # later delete the core mapping, so registration must be rejected.\\n    with pytest.raises(ValueError, match=\\\"conflict with an existing mapping\\\"):\\n        register_provider(\\n            _fakeco_spec(\\n                embedding_class_name=\\\"OpenAIEmbeddings\\\",\\n                embedding_param_key=\\\"OpenAI\\\",\\n                embedding_param_mapping={\\\"model\\\": \\\"model\\\"},\\n            )\\n        )\\n\\n\\n_NOT_CALLABLE = 42\\n\\n\\ndef _non_list_discovery(user_id, model_type):  # noqa: ARG001\\n    return \\\"not-a-list\\\"\\n\\n\\ndef test_non_callable_live_discovery_degrades_to_none():\\n    register_provider(_fakeco_spec(live=True, live_discovery=f\\\"{__name__}:_NOT_CALLABLE\\\"))\\n    assert provider_registry.live_discovery_for(\\\"FakeCo\\\") is None\\n    assert get_live_models_for_provider(\\\"user-1\\\", \\\"FakeCo\\\", \\\"llm\\\") == []\\n\\n\\ndef test_non_list_live_discovery_return_is_normalized():\\n    register_provider(_fakeco_spec(live=True, live_discovery=f\\\"{__name__}:_non_list_discovery\\\"))\\n    assert get_live_models_for_provider(\\\"user-1\\\", \\\"FakeCo\\\", \\\"llm\\\") == []\\n\\n\\ndef test_clear_restores_baseline():\\n    baseline_providers = get_model_providers()\\n    baseline_meta_keys = set(MODEL_PROVIDER_METADATA)\\n    baseline_live = list(LIVE_MODEL_PROVIDERS)\\n\\n    register_provider(\\n        _fakeco_spec(\\n            live=True,\\n            live_discovery=_LIVE_DISCOVERY_PATH,\\n            embedding_class_name=\\\"OpenAIEmbeddings\\\",\\n            embedding_param_key=\\\"FakeCo Embeddings\\\",\\n            embedding_param_mapping={\\\"model\\\": \\\"model\\\"},\\n        )\\n    )\\n    assert \\\"FakeCo\\\" in get_model_providers()\\n\\n    provider_registry.clear()\\n\\n    assert get_model_providers() == baseline_providers\\n    assert set(MODEL_PROVIDER_METADATA) == baseline_meta_keys\\n    assert list(LIVE_MODEL_PROVIDERS) == baseline_live\\n    assert \\\"FakeCo\\\" not in EMBEDDING_PROVIDER_CLASS_MAPPING\\n    assert \\\"FakeCo\\\" not in EMBEDDING_PARAM_MAPPINGS\\n    assert \\\"FakeCo Embeddings\\\" not in EMBEDDING_PARAM_MAPPINGS\\n\\n\\ndef test_unregister_provider_removes_only_the_target_registration():\\n    register_provider(\\n        _fakeco_spec(\\n            provider_id=\\\"fakeco\\\",\\n            aliases=(\\\"FakeCo Legacy\\\",),\\n            live=True,\\n            live_discovery=_LIVE_DISCOVERY_PATH,\\n            catalog_loader=_CATALOG_LOADER_PATH,\\n            embedding_class_name=\\\"OpenAIEmbeddings\\\",\\n            embedding_param_key=\\\"FakeCo Embeddings\\\",\\n            embedding_param_mapping={\\\"model\\\": \\\"model\\\"},\\n        )\\n    )\\n    register_provider(_fakeco_spec(name=\\\"OtherCo\\\", provider_id=\\\"otherco\\\"))\\n    provider_registry.live_discovery_for(\\\"FakeCo\\\")\\n    provider_registry.validate_registered_provider_catalogs([\\\"FakeCo\\\"])\\n\\n    assert provider_registry.unregister_provider(\\\"FakeCo\\\") is True\\n\\n    assert provider_registry.is_registered(\\\"FakeCo\\\") is False\\n    assert provider_registry.is_registered(\\\"OtherCo\\\") is True\\n    assert provider_registry.provider_id_for(\\\"FakeCo Legacy\\\") is None\\n    assert \\\"FakeCo\\\" not in MODEL_PROVIDER_METADATA\\n    assert \\\"FakeCo\\\" not in LIVE_MODEL_PROVIDERS\\n    assert \\\"FakeCo\\\" not in EMBEDDING_PROVIDER_CLASS_MAPPING\\n    assert \\\"FakeCo\\\" not in EMBEDDING_PARAM_MAPPINGS\\n    assert \\\"FakeCo Embeddings\\\" not in EMBEDDING_PARAM_MAPPINGS\\n    assert provider_registry.unregister_provider(\\\"FakeCo\\\") is False\\n\\n\\ndef test_zero_registration_is_noop():\\n    before = set(MODEL_PROVIDER_METADATA)\\n    provider_registry.clear()\\n    assert set(MODEL_PROVIDER_METADATA) == before\\n    assert provider_registry.registered_provider_names() == frozenset()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/models/test_provider_ssrf.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d60d5125e34fb2009436a766002f6a08cb574378da3a2218da2aaa83ca3bf45a\",\"content\":\"\\\"\\\"\\\"Unit coverage for the shared model-provider base-URL SSRF helpers.\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.base.models.provider_ssrf import openai_compatible_client_kwargs, validate_provider_base_url\\nfrom lfx.utils.ssrf_transport import SSRFProtectedSyncTransport, SSRFProtectedTransport\\n\\nBLOCKED_URLS = [\\n    \\\"http://169.254.169.254/latest/meta-data\\\",\\n    \\\"http://10.0.0.5:8000/v1\\\",\\n    \\\"http://192.168.1.10/v1\\\",\\n    \\\"http://172.16.0.9/v1\\\",\\n    \\\"http://[fd00::1]/v1\\\",\\n    \\\"http://localhost:1234/v1\\\",\\n    \\\"http://127.0.0.1:1234/v1\\\",\\n    \\\"http://127.1:1234/v1\\\",\\n    \\\"http://2130706433:1234/v1\\\",\\n    \\\"http://[::1]:1234/v1\\\",\\n]\\n\\nDEFAULT_URL = \\\"https://api.example-provider.com/v1\\\"\\n\\n\\nclass TestValidateProviderBaseUrl:\\n    @pytest.mark.parametrize(\\\"blocked_url\\\", BLOCKED_URLS)\\n    def test_should_block_internal_hosts(self, blocked_url):\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            validate_provider_base_url(blocked_url)\\n\\n    @pytest.mark.parametrize(\\\"empty\\\", [None, \\\"\\\"])\\n    def test_should_no_op_for_empty_url(self, empty):\\n        assert validate_provider_base_url(empty) is None\\n\\n    def test_should_no_op_for_provider_default(self):\\n        \\\"\\\"\\\"The provider default is server-chosen, so it never needs resolving.\\\"\\\"\\\"\\n        assert validate_provider_base_url(DEFAULT_URL, default_url=DEFAULT_URL) is None\\n\\n    def test_should_ignore_trailing_slash_when_matching_the_default(self):\\n        assert validate_provider_base_url(DEFAULT_URL + \\\"/\\\", default_url=DEFAULT_URL) is None\\n\\n    def test_should_still_validate_a_non_default_url(self):\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            validate_provider_base_url(\\\"http://169.254.169.254/v1\\\", default_url=DEFAULT_URL)\\n\\n    def test_should_reject_non_http_scheme(self):\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            validate_provider_base_url(\\\"file:///etc/passwd\\\")\\n\\n    def test_should_respect_global_kill_switch(self, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"false\\\")\\n        assert validate_provider_base_url(\\\"http://10.0.0.5:8000/v1\\\") is None\\n\\n    def test_should_honor_the_operator_allowlist(self, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", \\\"10.0.0.5\\\")\\n        assert validate_provider_base_url(\\\"http://10.0.0.5:8000/v1\\\") is None\\n\\n    def test_should_not_inherit_the_connector_loopback_exemption(self, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\", \\\"true\\\")\\n\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            validate_provider_base_url(\\\"http://127.0.0.1:1234/v1\\\")\\n\\n    def test_should_allow_explicitly_allowlisted_loopback(self, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", \\\"127.0.0.1\\\")\\n\\n        assert validate_provider_base_url(\\\"http://127.0.0.1:1234/v1\\\") is None\\n\\n\\nclass TestOpenAICompatibleClientKwargs:\\n    @pytest.mark.parametrize(\\\"blocked_url\\\", BLOCKED_URLS)\\n    def test_should_block_internal_hosts(self, blocked_url):\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            openai_compatible_client_kwargs(blocked_url)\\n\\n    @pytest.mark.parametrize(\\\"empty\\\", [None, \\\"\\\"])\\n    def test_should_return_empty_kwargs_for_empty_url(self, empty):\\n        assert openai_compatible_client_kwargs(empty) == {}\\n\\n    def test_should_return_empty_kwargs_for_provider_default(self):\\n        assert openai_compatible_client_kwargs(DEFAULT_URL, default_url=DEFAULT_URL) == {}\\n\\n    def test_should_return_pinned_clients_for_allowed_custom_url(self, monkeypatch):\\n        monkeypatch.setattr(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\", lambda _hostname: [\\\"93.184.216.34\\\"])\\n\\n        kwargs = openai_compatible_client_kwargs(\\\"https://provider.example/v1\\\")\\n\\n        assert set(kwargs) == {\\\"http_client\\\", \\\"http_async_client\\\"}\\n        assert kwargs[\\\"http_client\\\"].follow_redirects is False\\n        assert kwargs[\\\"http_async_client\\\"].follow_redirects is False\\n        assert isinstance(kwargs[\\\"http_client\\\"]._transport, SSRFProtectedSyncTransport)\\n        assert isinstance(kwargs[\\\"http_async_client\\\"]._transport, SSRFProtectedTransport)\\n        assert kwargs[\\\"http_client\\\"]._transport.pinned_ips == {\\\"provider.example\\\": [\\\"93.184.216.34\\\"]}\\n        assert kwargs[\\\"http_async_client\\\"]._transport.pinned_ips == {\\\"provider.example\\\": [\\\"93.184.216.34\\\"]}\\n\\n    def test_should_return_empty_kwargs_when_protection_is_disabled(self, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"false\\\")\\n        assert openai_compatible_client_kwargs(\\\"http://10.0.0.5:8000/v1\\\") == {}\\n\\n    def test_should_allow_explicitly_allowlisted_loopback(self, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", \\\"127.0.0.1\\\")\\n\\n        kwargs = openai_compatible_client_kwargs(\\\"http://127.0.0.1:1234/v1\\\")\\n\\n        assert set(kwargs) == {\\\"http_client\\\", \\\"http_async_client\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/models/test_static_catalog_tool_calling.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0998ca8da861dbeef6f6ec6c59f5fd37c1e1f5c44619c6cd252243219a3d8f6f\",\"content\":\"\\\"\\\"\\\"Pin tool_calling defaults for image-output models in the static catalogs.\\n\\nThe Agent picker filters on ``tool_calling=True``. Image-generation models\\n(outputs include ``image``) can't run with tools per the upstream APIs and\\nmust not pass through that filter. Earlier revisions of the Google catalog\\ndefaulted these models to ``tool_calling=True``, which leaked\\n``gemini-3.1-flash-image-preview`` into the Agent dropdown.\\n\\nThis file pins the correct flag on the known image models and exposes a\\ngeneric check that flags any future image-output model defaulted incorrectly\\nwhen added to a static ``*_constants.py`` list.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\n\\nGOOGLE_IMAGE_MODELS = (\\n    \\\"gemini-2.5-flash-image\\\",\\n    \\\"gemini-2.0-flash-preview-image-generation\\\",\\n    \\\"gemini-3-pro-image-preview\\\",\\n    \\\"gemini-3.1-flash-image-preview\\\",\\n)\\n\\n\\n@pytest.mark.parametrize(\\\"model_name\\\", GOOGLE_IMAGE_MODELS)\\ndef test_google_image_models_have_tool_calling_disabled(model_name: str):\\n    \\\"\\\"\\\"Known Google image-output models declare tool_calling=False.\\n\\n    The Agent picker filters on ``tool_calling=True``; image-generation\\n    models can't run with tools per Google's API and must not leak through\\n    the filter before the models.dev override hydrates.\\n    \\\"\\\"\\\"\\n    from lfx.base.models.google_generative_ai_constants import (\\n        GOOGLE_GENERATIVE_AI_MODELS_DETAILED,\\n    )\\n\\n    by_name = {m[\\\"name\\\"]: m for m in GOOGLE_GENERATIVE_AI_MODELS_DETAILED}\\n    assert model_name in by_name, (\\n        f\\\"{model_name} should remain in the static Google catalog so the static-only \\\"\\n        \\\"fallback retains its tool_calling=False curation; remove this test entry if \\\"\\n        \\\"the upstream model is intentionally dropped.\\\"\\n    )\\n    assert by_name[model_name].get(\\\"tool_calling\\\") is False, (\\n        f\\\"{model_name} is an image-output model and must declare tool_calling=False; \\\"\\n        \\\"the Agent picker filters on tool_calling=True and would otherwise surface it.\\\"\\n    )\\n\\n\\ndef test_no_google_model_with_image_in_name_defaults_to_tool_calling_true():\\n    \\\"\\\"\\\"Heuristic regression guard catches future image-in-name offenders.\\n\\n    If a model legitimately breaks the convention (e.g. a future\\n    ``gemini-Nx-image`` that does support tool calling), extend the\\n    ``allowlist`` below with a justification.\\n    \\\"\\\"\\\"\\n    from lfx.base.models.google_generative_ai_constants import (\\n        GOOGLE_GENERATIVE_AI_MODELS_DETAILED,\\n    )\\n\\n    allowlist: set[str] = set()\\n    suspects = [\\n        m for m in GOOGLE_GENERATIVE_AI_MODELS_DETAILED if \\\"image\\\" in m[\\\"name\\\"].lower() and m[\\\"name\\\"] not in allowlist\\n    ]\\n    offenders = [m[\\\"name\\\"] for m in suspects if m.get(\\\"tool_calling\\\")]\\n    assert offenders == [], (\\n        f\\\"Image-output Google models with tool_calling=True (will leak into Agent picker): {offenders}\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/models/test_temperature_remediation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4d1c5cdd9812c8b7e673b6f294ad824c9d7e5f2c6cee65ef52cfa55fca909f01\",\"content\":\"\\\"\\\"\\\"Regression tests for GH-14291 \u2014 models that reject an explicit ``temperature``.\\n\\nAnthropic's Claude 5 family (``claude-sonnet-5``, ``claude-opus-5``) answers any\\nrequest carrying ``temperature`` with HTTP 400 ```temperature`` is deprecated for\\nthis model.``, while ``claude-sonnet-4-6`` accepts it. The constraint is not\\nexposed by the provider's model listing, so it is matched on the ERROR TEXT and\\nworked around by clearing ``temperature`` and retrying once \u2014 the same\\nerror-driven remediation contract as the OpenAI Responses-API constraint.\\n\\nImpact this pins: the assistant's TranslationFlow hardcodes ``temperature: 0.1``,\\nso before the fix every intent classification on a Claude 5 model raised, was\\nswallowed by ``classify_intent``, and silently degraded to the ``question``\\nintent \u2014 \\\"build me a flow\\\" was answered in prose instead of building a flow.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\nfrom fastapi.encoders import jsonable_encoder\\nfrom langchain_core.language_models import BaseChatModel\\nfrom langchain_core.messages import AIMessage, AIMessageChunk, BaseMessage, HumanMessage\\nfrom langchain_core.output_parsers import StrOutputParser\\nfrom langchain_core.outputs import ChatGeneration, ChatResult\\nfrom langchain_core.prompts import ChatPromptTemplate\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.base.models.model_remediation import find_remediation, reset_remediation_cache\\nfrom lfx.schema.message import Message\\nfrom pydantic import Field\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Iterator\\n\\n    from langchain_core.callbacks import CallbackManagerForLLMRun\\n\\n# Verbatim provider response captured from a live claude-sonnet-5 call.\\nANTHROPIC_TEMPERATURE_ERROR = (\\n    \\\"Error code: 400 - {'type': 'error', 'error': {'type': 'invalid_request_error', \\\"\\n    \\\"'message': '`temperature` is deprecated for this model.'}, \\\"\\n    \\\"'request_id': 'req_011CdY7B6Rx9fGzrwztE6gYX'}\\\"\\n)\\n\\nUNRELATED_ERROR = (\\n    \\\"Error code: 429 - {'type': 'error', 'error': {'type': 'rate_limit_error', \\\"\\n    \\\"'message': 'Number of requests has exceeded your rate limit.'}}\\\"\\n)\\n\\n\\nclass ProviderBadRequestError(Exception):\\n    \\\"\\\"\\\"Stands in for ``anthropic.BadRequestError`` \u2014 matching is on the message, not the class.\\\"\\\"\\\"\\n\\n\\nclass TemperatureSensitiveChatModel(BaseChatModel):\\n    \\\"\\\"\\\"A real chat model that mirrors Claude 5: rejects any explicitly set temperature.\\n\\n    This is the one failure mode a real sandbox cannot reproduce deterministically,\\n    so it is modeled here rather than mocked at the call site.\\n    \\\"\\\"\\\"\\n\\n    temperature: float | None = None\\n    always_fail: bool = False\\n    seen_temperatures: list[float | None] = Field(default_factory=list)\\n\\n    @property\\n    def _llm_type(self) -> str:\\n        return \\\"temperature-sensitive-fake\\\"\\n\\n    def _generate(\\n        self,\\n        messages: list[BaseMessage],  # noqa: ARG002\\n        stop: list[str] | None = None,  # noqa: ARG002\\n        run_manager: CallbackManagerForLLMRun | None = None,  # noqa: ARG002\\n        **kwargs: Any,  # noqa: ARG002\\n    ) -> ChatResult:\\n        self.seen_temperatures.append(self.temperature)\\n        if self.always_fail:\\n            raise ProviderBadRequestError(ANTHROPIC_TEMPERATURE_ERROR)\\n        if self.temperature is not None:\\n            raise ProviderBadRequestError(ANTHROPIC_TEMPERATURE_ERROR)\\n        return ChatResult(generations=[ChatGeneration(message=AIMessage(content=\\\"ok\\\"))])\\n\\n\\nclass RateLimitedChatModel(BaseChatModel):\\n    \\\"\\\"\\\"Fails with an error no remediation covers, to prove unrelated errors still propagate.\\\"\\\"\\\"\\n\\n    temperature: float | None = None\\n    call_count: int = 0\\n\\n    @property\\n    def _llm_type(self) -> str:\\n        return \\\"rate-limited-fake\\\"\\n\\n    def _generate(\\n        self,\\n        messages: list[BaseMessage],  # noqa: ARG002\\n        stop: list[str] | None = None,  # noqa: ARG002\\n        run_manager: CallbackManagerForLLMRun | None = None,  # noqa: ARG002\\n        **kwargs: Any,  # noqa: ARG002\\n    ) -> ChatResult:\\n        self.call_count += 1\\n        raise ProviderBadRequestError(UNRELATED_ERROR)\\n\\n\\nclass PartialThenFailStreamingModel:\\n    \\\"\\\"\\\"Yield once before failing to verify retries never duplicate partial output.\\\"\\\"\\\"\\n\\n    temperature: float | None = 0.1\\n    call_count: int = 0\\n\\n    def stream(self, _inputs: Any) -> Iterator[AIMessageChunk]:\\n        self.call_count += 1\\n        yield AIMessageChunk(content=\\\"partial\\\")\\n        raise ProviderBadRequestError(ANTHROPIC_TEMPERATURE_ERROR)\\n\\n\\nclass _Probe(LCModelComponent):\\n    \\\"\\\"\\\"Minimal LCModelComponent usable without going through Component init.\\\"\\\"\\\"\\n\\n    display_name = \\\"Probe\\\"\\n    description = \\\"test\\\"\\n\\n    def build_model(self):  # pragma: no cover - not exercised; the runnable is injected\\n        raise NotImplementedError\\n\\n\\ndef _make_probe() -> _Probe:\\n    probe = _Probe.__new__(_Probe)\\n    probe.is_connected_to_chat_output = MagicMock(return_value=False)\\n    probe.get_project_name = MagicMock(return_value=\\\"test-project\\\")\\n    probe.get_langchain_callbacks = MagicMock(return_value=[])\\n    probe._id = \\\"probe-1\\\"\\n    probe._event_manager = None\\n    return probe\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _clear_cache():\\n    reset_remediation_cache()\\n    yield\\n    reset_remediation_cache()\\n\\n\\nclass TestTemperatureRemediationRegistry:\\n    def test_should_match_the_temperature_deprecated_error(self):\\n        remediation = find_remediation(ANTHROPIC_TEMPERATURE_ERROR, provider=\\\"Anthropic\\\", already_applied=set())\\n\\n        assert remediation is not None\\n        assert remediation.overrides == {\\\"temperature\\\": None}\\n\\n    def test_should_match_regardless_of_provider(self):\\n        \\\"\\\"\\\"The constraint is not Anthropic-specific; match on the error text alone.\\\"\\\"\\\"\\n        assert find_remediation(ANTHROPIC_TEMPERATURE_ERROR, provider=None, already_applied=set()) is not None\\n\\n    def test_should_not_match_unrelated_provider_errors(self):\\n        assert find_remediation(UNRELATED_ERROR, provider=\\\"Anthropic\\\", already_applied=set()) is None\\n\\n    def test_should_not_match_a_temperature_error_that_is_not_about_deprecation(self):\\n        \\\"\\\"\\\"Guard against over-matching: an invalid *value* must still surface to the user.\\\"\\\"\\\"\\n        invalid_value = \\\"400 - temperature must be between 0 and 1\\\"\\n\\n        assert find_remediation(invalid_value, provider=\\\"Anthropic\\\", already_applied=set()) is None\\n\\n\\nclass TestApplyOverridesToModel:\\n    \\\"\\\"\\\"``apply_overrides_to_model`` is imported per-test so the retry tests above stay collectable.\\\"\\\"\\\"\\n\\n    def test_should_set_a_known_attribute_and_report_success(self):\\n        from lfx.base.models.model_remediation import apply_overrides_to_model\\n\\n        model = TemperatureSensitiveChatModel(temperature=0.1)\\n\\n        assert apply_overrides_to_model(model, {\\\"temperature\\\": None}) is True\\n        assert model.temperature is None\\n\\n    def test_should_report_failure_when_the_attribute_is_unknown(self):\\n        \\\"\\\"\\\"Never attach a junk attribute \u2014 an unappliable override must let the error propagate.\\\"\\\"\\\"\\n        from lfx.base.models.model_remediation import apply_overrides_to_model\\n\\n        model = TemperatureSensitiveChatModel(temperature=0.1)\\n\\n        assert apply_overrides_to_model(model, {\\\"use_responses_api\\\": True}) is False\\n        assert not hasattr(model, \\\"use_responses_api\\\")\\n\\n    def test_should_report_failure_for_a_non_model_object(self):\\n        from lfx.base.models.model_remediation import apply_overrides_to_model\\n\\n        assert apply_overrides_to_model(object(), {\\\"temperature\\\": None}) is False\\n\\n\\nclass TestGetChatResultRetry:\\n    @pytest.mark.asyncio\\n    async def test_should_retry_without_temperature_when_the_model_rejects_it(self):\\n        probe = _make_probe()\\n        model = TemperatureSensitiveChatModel(temperature=0.1)\\n\\n        result = await probe._get_chat_result(runnable=model, stream=False, input_value=\\\"say ok\\\")\\n\\n        assert result.text == \\\"ok\\\"\\n        assert model.seen_temperatures == [0.1, None], \\\"expected exactly one retry, with temperature cleared\\\"\\n        assert model.temperature is None\\n\\n    @pytest.mark.asyncio\\n    async def test_should_not_retry_when_the_error_is_unrelated(self):\\n        probe = _make_probe()\\n        model = RateLimitedChatModel(temperature=0.1)\\n\\n        with pytest.raises(ValueError, match=\\\"rate_limit_error\\\"):\\n            await probe._get_chat_result(runnable=model, stream=False, input_value=\\\"say ok\\\")\\n\\n        assert model.call_count == 1, \\\"unrelated errors must propagate without a retry\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_propagate_when_the_retry_also_fails(self):\\n        \\\"\\\"\\\"Retry exactly once: a second failure is a real error, not a parameter constraint.\\\"\\\"\\\"\\n        probe = _make_probe()\\n        model = TemperatureSensitiveChatModel(temperature=0.1, always_fail=True)\\n\\n        with pytest.raises(ValueError, match=\\\"temperature\\\"):\\n            await probe._get_chat_result(runnable=model, stream=False, input_value=\\\"say ok\\\")\\n\\n        assert model.seen_temperatures == [0.1, None]\\n\\n    @pytest.mark.asyncio\\n    async def test_should_retry_with_a_system_message(self):\\n        \\\"\\\"\\\"The system message must survive the retry \u2014 the request is rebuilt, not truncated.\\\"\\\"\\\"\\n        probe = _make_probe()\\n        model = TemperatureSensitiveChatModel(temperature=0.1)\\n\\n        result = await probe._get_chat_result(\\n            runnable=model, stream=False, input_value=\\\"say ok\\\", system_message=\\\"You are terse.\\\"\\n        )\\n\\n        assert result.text == \\\"ok\\\"\\n        assert model.seen_temperatures == [0.1, None]\\n\\n    @pytest.mark.asyncio\\n    async def test_should_retry_when_a_prompt_component_wraps_the_model(self):\\n        \\\"\\\"\\\"A Prompt wired into a Language Model turns the runnable into a chain.\\n\\n        The override has to reach the chat model inside it, otherwise the most common\\n        Basic Prompting flow shape stays broken while the bare-input shape is fixed.\\n        \\\"\\\"\\\"\\n        probe = _make_probe()\\n        model = TemperatureSensitiveChatModel(temperature=0.1)\\n        # ``prompt`` reaches the component jsonable_encoded, which is what load_lc_prompt expects.\\n        template = ChatPromptTemplate.from_messages([HumanMessage(content=\\\"say ok\\\")])\\n        prompt_message = Message(prompt=jsonable_encoder(template.to_json()))\\n\\n        result = await probe._get_chat_result(runnable=model, stream=False, input_value=prompt_message)\\n\\n        assert result.text == \\\"ok\\\"\\n        assert model.seen_temperatures == [0.1, None]\\n\\n\\nclass TestSyncGetChatResultRetry:\\n    \\\"\\\"\\\"``chat_result.get_chat_result`` backs Structured Output and LLM Selector.\\n\\n    Those components receive an already-built model over a connection, so a Language\\n    Model component configured with temperature 0.1 hands them a client that fails\\n    identically \u2014 the same bug reached through a different component.\\n    \\\"\\\"\\\"\\n\\n    def test_should_retry_without_temperature_when_the_model_rejects_it(self):\\n        from lfx.base.models.chat_result import get_chat_result\\n\\n        model = TemperatureSensitiveChatModel(temperature=0.1)\\n\\n        result = get_chat_result(runnable=model, input_value=\\\"say ok\\\")\\n\\n        assert result == \\\"ok\\\"\\n        assert model.seen_temperatures == [0.1, None]\\n\\n    def test_should_retry_when_a_prompt_component_wraps_the_model(self):\\n        from lfx.base.models.chat_result import get_chat_result\\n\\n        model = TemperatureSensitiveChatModel(temperature=0.1)\\n        template = ChatPromptTemplate.from_messages([HumanMessage(content=\\\"say ok\\\")])\\n        prompt_message = Message(prompt=jsonable_encoder(template.to_json()))\\n\\n        result = get_chat_result(runnable=model, input_value=prompt_message)\\n\\n        assert result == \\\"ok\\\"\\n        assert model.seen_temperatures == [0.1, None]\\n\\n    def test_should_remediate_the_model_inside_an_incoming_wrapper(self):\\n        from lfx.base.models.chat_result import get_chat_result\\n\\n        model = TemperatureSensitiveChatModel(temperature=0.1)\\n        wrapped = model | StrOutputParser()\\n\\n        result = get_chat_result(\\n            runnable=wrapped,\\n            remediation_target=model,\\n            input_value=\\\"say ok\\\",\\n        )\\n\\n        assert result == \\\"ok\\\"\\n        assert model.seen_temperatures == [0.1, None]\\n\\n    def test_should_retry_a_lazy_stream_before_the_first_chunk(self):\\n        from lfx.base.models.chat_result import get_chat_result\\n\\n        model = TemperatureSensitiveChatModel(temperature=0.1)\\n\\n        chunks = list(get_chat_result(runnable=model, input_value=\\\"say ok\\\", stream=True))\\n\\n        assert [chunk.content for chunk in chunks] == [\\\"ok\\\"]\\n        assert model.seen_temperatures == [0.1, None]\\n\\n    def test_should_not_retry_a_stream_after_emitting_a_chunk(self):\\n        from lfx.base.models.chat_result import get_chat_result\\n\\n        model = PartialThenFailStreamingModel()\\n        chunks = iter(get_chat_result(runnable=model, input_value=\\\"say ok\\\", stream=True))\\n\\n        assert next(chunks).content == \\\"partial\\\"\\n        with pytest.raises(ProviderBadRequestError, match=\\\"temperature\\\"):\\n            next(chunks)\\n\\n        assert model.call_count == 1\\n        assert model.temperature == 0.1\\n\\n    def test_should_not_retry_when_the_error_is_unrelated(self):\\n        from lfx.base.models.chat_result import get_chat_result\\n\\n        model = RateLimitedChatModel(temperature=0.1)\\n\\n        with pytest.raises(ProviderBadRequestError, match=\\\"rate_limit_error\\\"):\\n            get_chat_result(runnable=model, input_value=\\\"say ok\\\")\\n\\n        assert model.call_count == 1\\n\\n    def test_should_propagate_when_the_retry_also_fails(self):\\n        from lfx.base.models.chat_result import get_chat_result\\n\\n        model = TemperatureSensitiveChatModel(temperature=0.1, always_fail=True)\\n\\n        with pytest.raises(ProviderBadRequestError, match=\\\"temperature\\\"):\\n            get_chat_result(runnable=model, input_value=\\\"say ok\\\")\\n\\n        assert model.seen_temperatures == [0.1, None]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/models/test_unified_model_ssrf.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3f51fbd7d6b4e4b38ce2b1d58ea5445941195888488bae5519898314b27b7c74\",\"content\":\"\\\"\\\"\\\"SSRF regression coverage for unified model and embedding instantiation.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport os\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom lfx.base.models import unified_models as unified_models_module\\nfrom lfx.base.models.unified_models import instantiation\\n\\n\\ndef _capture_factory():\\n    captured: dict = {}\\n\\n    class FakeModel:\\n        def __init__(self, **kwargs):\\n            captured.update(kwargs)\\n\\n    return FakeModel, captured\\n\\n\\ndef _model_selection(provider: str, model_class: str, **metadata) -> list[dict]:\\n    return [\\n        {\\n            \\\"name\\\": \\\"test-model\\\",\\n            \\\"provider\\\": provider,\\n            \\\"metadata\\\": {\\n                \\\"model_class\\\": model_class,\\n                \\\"model_name_param\\\": \\\"model\\\",\\n                \\\"api_key_param\\\": \\\"api_key\\\",  # pragma: allowlist secret\\n                **metadata,\\n            },\\n        }\\n    ]\\n\\n\\ndef _embedding_selection(provider: str, embedding_class: str, param_mapping: dict[str, str]) -> list[dict]:\\n    return [\\n        {\\n            \\\"name\\\": \\\"test-embedding\\\",\\n            \\\"provider\\\": provider,\\n            \\\"metadata\\\": {\\n                \\\"embedding_class\\\": embedding_class,\\n                \\\"param_mapping\\\": param_mapping,\\n            },\\n        }\\n    ]\\n\\n\\ndef _blocked_connector_policy() -> dict[str, str]:\\n    return {\\n        \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n        \\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"true\\\",\\n        \\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\": \\\"false\\\",\\n    }\\n\\n\\ndef test_get_llm_blocks_disallowed_ollama_loopback_before_model_construction():\\n    fake_cls, captured = _capture_factory()\\n\\n    with (\\n        patch.dict(os.environ, _blocked_connector_policy()),\\n        patch.object(unified_models_module, \\\"get_api_key_for_provider\\\", return_value=None),\\n        patch.object(unified_models_module, \\\"get_model_class\\\", return_value=fake_cls),\\n        patch.object(unified_models_module, \\\"get_all_variables_for_provider\\\", return_value={}),\\n        pytest.raises(ValueError, match=r\\\"SSRF Protection:.*127\\\\.0\\\\.0\\\\.1.*blocked\\\"),\\n    ):\\n        instantiation.get_llm(\\n            _model_selection(\\\"Ollama\\\", \\\"ChatOllama\\\", base_url_param=\\\"base_url\\\"),\\n            user_id=\\\"user-1\\\",\\n            ollama_base_url=\\\"http://127.0.0.1:17864\\\",\\n        )\\n\\n    assert captured == {}\\n\\n\\ndef test_get_embeddings_blocks_disallowed_ollama_loopback_before_model_construction():\\n    fake_cls, captured = _capture_factory()\\n\\n    with (\\n        patch.dict(os.environ, _blocked_connector_policy()),\\n        patch.object(unified_models_module, \\\"get_api_key_for_provider\\\", return_value=None),\\n        patch.object(unified_models_module, \\\"get_embedding_class\\\", return_value=fake_cls),\\n        patch.object(unified_models_module, \\\"get_all_variables_for_provider\\\", return_value={}),\\n        patch.object(instantiation, \\\"_build_available_embedding_models\\\", return_value={}),\\n        pytest.raises(ValueError, match=r\\\"SSRF Protection:.*127\\\\.0\\\\.0\\\\.1.*blocked\\\"),\\n    ):\\n        instantiation.get_embeddings(\\n            _embedding_selection(\\n                \\\"Ollama\\\",\\n                \\\"OllamaEmbeddings\\\",\\n                {\\\"model\\\": \\\"model\\\", \\\"base_url\\\": \\\"base_url\\\"},\\n            ),\\n            user_id=\\\"user-1\\\",\\n            ollama_base_url=\\\"http://127.0.0.1:17864\\\",\\n        )\\n\\n    assert captured == {}\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"policy\\\",\\n    [\\n        {\\n            \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n            \\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"true\\\",\\n            \\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\": \\\"true\\\",\\n        },\\n        {\\n            \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n            \\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"false\\\",\\n            \\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\": \\\"false\\\",\\n        },\\n    ],\\n)\\ndef test_get_llm_preserves_explicit_ollama_ssrf_opt_outs(policy):\\n    fake_cls, captured = _capture_factory()\\n\\n    with (\\n        patch.dict(os.environ, policy),\\n        patch.object(unified_models_module, \\\"get_api_key_for_provider\\\", return_value=None),\\n        patch.object(unified_models_module, \\\"get_model_class\\\", return_value=fake_cls),\\n        patch.object(unified_models_module, \\\"get_all_variables_for_provider\\\", return_value={}),\\n    ):\\n        instantiation.get_llm(\\n            _model_selection(\\\"Ollama\\\", \\\"ChatOllama\\\", base_url_param=\\\"base_url\\\"),\\n            user_id=\\\"user-1\\\",\\n            ollama_base_url=\\\"http://127.0.0.1:11434\\\",\\n        )\\n\\n    assert captured[\\\"base_url\\\"] == \\\"http://127.0.0.1:11434\\\"\\n    assert captured[\\\"sync_client_kwargs\\\"] == {\\\"follow_redirects\\\": False}\\n    assert captured[\\\"async_client_kwargs\\\"] == {\\\"follow_redirects\\\": False}\\n\\n\\ndef test_get_llm_protects_final_openai_base_url_after_overrides():\\n    fake_cls, captured = _capture_factory()\\n\\n    with (\\n        patch.dict(os.environ, _blocked_connector_policy()),\\n        patch.object(unified_models_module, \\\"get_api_key_for_provider\\\", return_value=\\\"test-key\\\"),\\n        patch.object(unified_models_module, \\\"get_model_class\\\", return_value=fake_cls),\\n        patch.object(unified_models_module, \\\"get_all_variables_for_provider\\\", return_value={}),\\n        pytest.raises(ValueError, match=r\\\"SSRF Protection:.*169\\\\.254\\\\.169\\\\.254.*blocked\\\"),\\n    ):\\n        instantiation.get_llm(\\n            _model_selection(\\\"OpenAI\\\", \\\"ChatOpenAI\\\"),\\n            user_id=\\\"user-1\\\",\\n            overrides={\\\"base_url\\\": \\\"http://169.254.169.254/latest/meta-data/\\\"},\\n        )\\n\\n    assert captured == {}\\n\\n\\ndef test_get_llm_injects_protected_openai_clients_for_custom_base_url():\\n    fake_cls, captured = _capture_factory()\\n    protected_clients = {\\\"http_client\\\": object(), \\\"http_async_client\\\": object()}\\n\\n    with (\\n        patch.object(unified_models_module, \\\"get_api_key_for_provider\\\", return_value=\\\"test-key\\\"),\\n        patch.object(unified_models_module, \\\"get_model_class\\\", return_value=fake_cls),\\n        patch.object(\\n            unified_models_module,\\n            \\\"get_all_variables_for_provider\\\",\\n            return_value={\\\"OPENAI_BASE_URL\\\": \\\"https://models.example/v1\\\"},\\n        ),\\n        patch.object(\\n            instantiation,\\n            \\\"ssrf_protected_openai_clients_for_url\\\",\\n            return_value=protected_clients,\\n            create=True,\\n        ) as protect_clients,\\n    ):\\n        instantiation.get_llm(_model_selection(\\\"OpenAI\\\", \\\"ChatOpenAI\\\"), user_id=\\\"user-1\\\")\\n\\n    protect_clients.assert_called_once_with(\\\"https://models.example/v1\\\")\\n    assert captured[\\\"http_client\\\"] is protected_clients[\\\"http_client\\\"]\\n    assert captured[\\\"http_async_client\\\"] is protected_clients[\\\"http_async_client\\\"]\\n\\n\\ndef test_get_embeddings_injects_protected_openai_clients_for_custom_base_url():\\n    fake_cls, captured = _capture_factory()\\n    protected_clients = {\\\"http_client\\\": object(), \\\"http_async_client\\\": object()}\\n\\n    with (\\n        patch.object(unified_models_module, \\\"get_api_key_for_provider\\\", return_value=\\\"test-key\\\"),\\n        patch.object(unified_models_module, \\\"get_embedding_class\\\", return_value=fake_cls),\\n        patch.object(unified_models_module, \\\"get_all_variables_for_provider\\\", return_value={}),\\n        patch.object(instantiation, \\\"_build_available_embedding_models\\\", return_value={}),\\n        patch.object(\\n            instantiation,\\n            \\\"ssrf_protected_openai_clients_for_url\\\",\\n            return_value=protected_clients,\\n            create=True,\\n        ) as protect_clients,\\n    ):\\n        instantiation.get_embeddings(\\n            _embedding_selection(\\n                \\\"OpenAI\\\",\\n                \\\"OpenAIEmbeddings\\\",\\n                {\\\"model\\\": \\\"model\\\", \\\"api_key\\\": \\\"api_key\\\", \\\"api_base\\\": \\\"base_url\\\"},  # pragma: allowlist secret\\n            ),\\n            user_id=\\\"user-1\\\",\\n            api_base=\\\"https://embeddings.example/v1\\\",\\n        )\\n\\n    protect_clients.assert_called_once_with(\\\"https://embeddings.example/v1\\\")\\n    assert captured[\\\"http_client\\\"] is protected_clients[\\\"http_client\\\"]\\n    assert captured[\\\"http_async_client\\\"] is protected_clients[\\\"http_async_client\\\"]\\n\\n\\ndef test_get_llm_validates_watsonx_url_before_model_construction():\\n    fake_cls, captured = _capture_factory()\\n\\n    with (\\n        patch.object(unified_models_module, \\\"get_api_key_for_provider\\\", return_value=\\\"test-key\\\"),\\n        patch.object(unified_models_module, \\\"get_model_class\\\", return_value=fake_cls),\\n        patch.object(unified_models_module, \\\"get_all_variables_for_provider\\\", return_value={}),\\n        patch.object(\\n            instantiation,\\n            \\\"validate_url_for_ssrf_or_raise\\\",\\n            create=True,\\n        ) as validate_url,\\n    ):\\n        instantiation.get_llm(\\n            _model_selection(\\\"IBM WatsonX\\\", \\\"ChatWatsonx\\\"),\\n            user_id=\\\"user-1\\\",\\n            watsonx_url=\\\"https://us-south.ml.cloud.ibm.com\\\",\\n            watsonx_project_id=\\\"project-1\\\",\\n        )\\n\\n    validate_url.assert_called_once_with(\\\"https://us-south.ml.cloud.ibm.com\\\")\\n    assert captured[\\\"url\\\"] == \\\"https://us-south.ml.cloud.ibm.com\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/models/test_unified_model_status_identity.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6b7da15a1e9272164569e8ca9132bef0403e4a5061c9b9efd661561d0b5a070a\",\"content\":\"from __future__ import annotations\\n\\nimport sys\\nfrom unittest.mock import AsyncMock, patch\\n\\nimport pytest\\n\\n\\ndef _shared_alias_catalog() -> list[dict]:\\n    return [\\n        {\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"icon\\\": \\\"OpenAI\\\",\\n            \\\"models\\\": [{\\\"model_name\\\": \\\"gpt-4o\\\", \\\"metadata\\\": {\\\"default\\\": True}}],\\n        },\\n        {\\n            \\\"provider\\\": \\\"Azure AI Foundry\\\",\\n            \\\"icon\\\": \\\"Azure\\\",\\n            \\\"models\\\": [{\\\"model_name\\\": \\\"gpt-4o\\\", \\\"metadata\\\": {\\\"default\\\": True}}],\\n        },\\n    ]\\n\\n\\ndef test_status_membership_supports_qualified_and_legacy_entries():\\n    from lfx.base.models.unified_models.credentials import model_status_contains\\n\\n    assert model_status_contains({\\\"OpenAI::gpt-4o\\\"}, \\\"OpenAI\\\", \\\"gpt-4o\\\")\\n    assert not model_status_contains({\\\"OpenAI::gpt-4o\\\"}, \\\"Azure AI Foundry\\\", \\\"gpt-4o\\\")\\n    assert model_status_contains({\\\"gpt-4o\\\"}, \\\"OpenAI\\\", \\\"gpt-4o\\\")\\n    assert model_status_contains({\\\"gpt-4o\\\"}, \\\"Azure AI Foundry\\\", \\\"gpt-4o\\\")\\n\\n\\ndef test_status_membership_scopes_typed_entries_and_preserves_separator_names():\\n    from lfx.base.models.unified_models.credentials import model_status_contains, model_status_key\\n\\n    provider = \\\"Azure AI Foundry\\\"\\n    model_name = \\\"shared::deployment\\\"\\n    typed_entry = \\\"Azure AI Foundry::llm::shared::deployment\\\"\\n\\n    assert model_status_key(provider, model_name, model_type=\\\"llm\\\") == typed_entry\\n    assert model_status_contains({typed_entry}, provider, model_name, model_type=\\\"llm\\\")\\n    assert not model_status_contains({typed_entry}, provider, model_name, model_type=\\\"embeddings\\\")\\n\\n    # Provider-qualified and bare pre-type entries remain readable, including\\n    # deployment names that contain the status separator themselves.\\n    legacy_entry = \\\"Azure AI Foundry::shared::deployment\\\"\\n    assert model_status_contains({legacy_entry}, provider, model_name, model_type=\\\"llm\\\")\\n    assert model_status_contains({legacy_entry}, provider, model_name, model_type=\\\"embeddings\\\")\\n    assert model_status_contains({model_name}, provider, model_name, model_type=\\\"embeddings\\\")\\n\\n\\ndef test_custom_injection_uses_persisted_type_and_defaults_legacy_to_llm():\\n    from lfx.base.models.model_utils import inject_custom_enabled_models\\n\\n    typed_models: list[dict] = []\\n    inject_custom_enabled_models(\\n        typed_models,\\n        {\\n            \\\"Azure AI Foundry::llm::chat::deployment\\\",\\n            \\\"Azure AI Foundry::embeddings::embed::deployment\\\",\\n        },\\n    )\\n\\n    typed_pairs = {\\n        (model[\\\"model_name\\\"], model[\\\"metadata\\\"][\\\"model_type\\\"])\\n        for provider in typed_models\\n        for model in provider[\\\"models\\\"]\\n    }\\n    assert typed_pairs == {\\n        (\\\"chat::deployment\\\", \\\"llm\\\"),\\n        (\\\"embed::deployment\\\", \\\"embeddings\\\"),\\n    }\\n\\n    legacy_models: list[dict] = []\\n    inject_custom_enabled_models(\\n        legacy_models,\\n        {\\\"Azure AI Foundry::legacy::deployment\\\"},\\n    )\\n    legacy_pairs = [\\n        (model[\\\"model_name\\\"], model[\\\"metadata\\\"][\\\"model_type\\\"])\\n        for provider in legacy_models\\n        for model in provider[\\\"models\\\"]\\n    ]\\n    assert legacy_pairs == [(\\\"legacy::deployment\\\", \\\"llm\\\")]\\n\\n\\ndef test_custom_injection_skips_mismatched_typed_entry_without_provider_stub():\\n    from lfx.base.models.model_utils import inject_custom_enabled_models\\n\\n    provider_models: list[dict] = []\\n    inject_custom_enabled_models(\\n        provider_models,\\n        {\\\"Azure AI Foundry::llm::chat-deployment\\\"},\\n        model_type=\\\"embeddings\\\",\\n    )\\n\\n    assert provider_models == []\\n\\n\\ndef test_custom_injection_does_not_fabricate_capabilities_for_non_custom_provider():\\n    from lfx.base.models.model_utils import inject_custom_enabled_models\\n\\n    provider_models = [{\\\"provider\\\": \\\"OpenAI\\\", \\\"models\\\": [], \\\"num_models\\\": 0}]\\n    inject_custom_enabled_models(\\n        provider_models,\\n        {\\\"OpenAI::llm::gpt-5-chat-latest\\\"},\\n        model_type=\\\"llm\\\",\\n        metadata_filters={\\\"tool_calling\\\": True},\\n    )\\n\\n    assert provider_models[0][\\\"models\\\"] == []\\n\\n\\ndef test_language_options_scope_status_to_provider():\\n    from lfx.base.models.unified_models import model_catalog\\n\\n    with (\\n        patch.object(model_catalog, \\\"get_unified_models_detailed\\\", return_value=_shared_alias_catalog()),\\n        patch.object(\\n            model_catalog,\\n            \\\"_get_model_status\\\",\\n            # OpenAI gpt-4o disabled; Foundry gpt-4o must be explicitly enabled\\n            # (Foundry ignores seed defaults so deployment names never auto-select).\\n            new=AsyncMock(return_value=({\\\"OpenAI::gpt-4o\\\"}, {\\\"Azure AI Foundry::gpt-4o\\\"})),\\n        ),\\n        patch.object(\\n            model_catalog,\\n            \\\"_fetch_enabled_providers_for_user\\\",\\n            new=AsyncMock(return_value={\\\"OpenAI\\\", \\\"Azure AI Foundry\\\"}),\\n        ),\\n        patch.object(model_catalog, \\\"replace_with_live_models\\\"),\\n    ):\\n        options = model_catalog.get_language_model_options(user_id=\\\"00000000-0000-0000-0000-000000000001\\\")\\n\\n    assert {(option[\\\"provider\\\"], option[\\\"name\\\"]) for option in options} == {(\\\"Azure AI Foundry\\\", \\\"gpt-4o\\\")}\\n\\n\\ndef test_language_options_include_custom_foundry_deployment():\\n    \\\"\\\"\\\"Free-text Foundry deployments must appear in the Agent/Language Model picker.\\\"\\\"\\\"\\n    from lfx.base.models.unified_models import model_catalog\\n\\n    with (\\n        patch.object(model_catalog, \\\"get_unified_models_detailed\\\", return_value=_shared_alias_catalog()),\\n        patch.object(\\n            model_catalog,\\n            \\\"_get_model_status\\\",\\n            new=AsyncMock(return_value=(set(), {\\\"Azure AI Foundry::gpt-5-mini\\\"})),\\n        ),\\n        patch.object(\\n            model_catalog,\\n            \\\"_fetch_enabled_providers_for_user\\\",\\n            new=AsyncMock(return_value={\\\"Azure AI Foundry\\\"}),\\n        ),\\n        patch.object(model_catalog, \\\"replace_with_live_models\\\"),\\n    ):\\n        options = model_catalog.get_language_model_options(user_id=\\\"00000000-0000-0000-0000-000000000001\\\")\\n\\n    assert {(option[\\\"provider\\\"], option[\\\"name\\\"]) for option in options} == {\\n        (\\\"Azure AI Foundry\\\", \\\"gpt-5-mini\\\"),\\n    }\\n\\n\\ndef test_typed_custom_deployment_only_appears_in_matching_picker():\\n    from lfx.base.models.unified_models import model_catalog\\n\\n    provider = \\\"Azure AI Foundry\\\"\\n    deployment_name = \\\"shared::deployment\\\"\\n\\n    def catalog_for_requested_type(*_args, **kwargs):\\n        model_type = kwargs.get(\\\"model_type\\\")\\n        return [\\n            {\\n                \\\"provider\\\": provider,\\n                \\\"icon\\\": \\\"Azure\\\",\\n                \\\"models\\\": [\\n                    {\\n                        \\\"model_name\\\": deployment_name,\\n                        \\\"metadata\\\": {\\\"default\\\": False, \\\"model_type\\\": model_type},\\n                    }\\n                ],\\n            }\\n        ]\\n\\n    with (\\n        patch.object(model_catalog, \\\"get_unified_models_detailed\\\", side_effect=catalog_for_requested_type),\\n        patch.object(\\n            model_catalog,\\n            \\\"_get_model_status\\\",\\n            new=AsyncMock(return_value=(set(), {f\\\"{provider}::embeddings::{deployment_name}\\\"})),\\n        ),\\n        patch.object(\\n            model_catalog,\\n            \\\"_fetch_enabled_providers_for_user\\\",\\n            new=AsyncMock(return_value={provider}),\\n        ),\\n        patch.object(model_catalog, \\\"replace_with_live_models\\\"),\\n    ):\\n        language_options = model_catalog.get_language_model_options(user_id=\\\"00000000-0000-0000-0000-000000000001\\\")\\n        embedding_options = model_catalog.get_embedding_model_options(user_id=\\\"00000000-0000-0000-0000-000000000001\\\")\\n\\n    assert language_options == []\\n    assert {(option[\\\"provider\\\"], option[\\\"name\\\"]) for option in embedding_options} == {(provider, deployment_name)}\\n\\n\\ndef test_embedding_lookup_preserves_type_for_same_name_catalog_rows():\\n    from lfx.base.models.unified_models import instantiation\\n\\n    provider = \\\"Azure AI Foundry\\\"\\n    deployment_name = \\\"shared::deployment\\\"\\n    catalog_rows = [\\n        {\\n            \\\"model_name\\\": deployment_name,\\n            \\\"metadata\\\": {\\\"default\\\": False, \\\"model_type\\\": \\\"embeddings\\\"},\\n        },\\n        {\\n            \\\"model_name\\\": deployment_name,\\n            \\\"metadata\\\": {\\\"default\\\": False, \\\"model_type\\\": \\\"llm\\\"},\\n        },\\n    ]\\n\\n    with (\\n        patch.object(instantiation, \\\"_get_provider_catalog_models\\\", return_value=catalog_rows),\\n        patch.object(\\n            instantiation,\\n            \\\"_get_model_status\\\",\\n            new=AsyncMock(return_value=(set(), {f\\\"{provider}::embeddings::{deployment_name}\\\"})),\\n        ),\\n        patch.object(\\n            instantiation,\\n            \\\"_fetch_enabled_providers_for_user\\\",\\n            new=AsyncMock(return_value={provider}),\\n        ),\\n    ):\\n        names = instantiation._get_provider_embedding_model_names(\\n            provider,\\n            \\\"00000000-0000-0000-0000-000000000001\\\",\\n        )\\n\\n    assert names == [deployment_name]\\n\\n\\ndef test_legacy_name_normalization_preserves_first_provider():\\n    from lfx.base.models.unified_models import model_catalog\\n\\n    with (\\n        patch.object(model_catalog, \\\"get_unified_models_detailed\\\", return_value=_shared_alias_catalog()),\\n        patch.object(model_catalog, \\\"get_provider_param_mapping\\\", return_value={}),\\n    ):\\n        normalized = model_catalog.normalize_model_names_to_dicts(\\\"gpt-4o\\\")\\n\\n    assert normalized[0][\\\"provider\\\"] == \\\"OpenAI\\\"\\n\\n\\ndef test_reasoning_model_instantiation_omits_temperature_and_preserves_max_tokens():\\n    from lfx.base.models import unified_models as unified_models_module\\n    from lfx.base.models.unified_models import instantiation\\n    from lfx.base.models.unified_models.instantiation import get_llm\\n\\n    captured: dict = {}\\n\\n    class FakeFoundryChatModel:\\n        def __init__(self, **kwargs):\\n            captured.update(kwargs)\\n\\n    selection = [\\n        {\\n            \\\"name\\\": \\\"o3-mini\\\",\\n            \\\"provider\\\": \\\"Azure AI Foundry\\\",\\n            \\\"metadata\\\": {\\\"reasoning\\\": True},\\n        }\\n    ]\\n    with (\\n        patch.object(unified_models_module, \\\"get_api_key_for_provider\\\", return_value=\\\"test-key\\\"),\\n        patch.object(unified_models_module, \\\"get_model_class\\\", return_value=FakeFoundryChatModel),\\n        patch.object(\\n            unified_models_module,\\n            \\\"get_all_variables_for_provider\\\",\\n            return_value={\\\"AZURE_AI_FOUNDRY_ENDPOINT\\\": \\\"https://example.services.ai.azure.com/openai/v1\\\"},\\n        ),\\n        patch.object(instantiation, \\\"validate_url_for_ssrf_or_raise\\\"),\\n    ):\\n        get_llm(selection, user_id=\\\"user-1\\\", temperature=0.7, max_tokens=25)\\n\\n    assert \\\"temperature\\\" not in captured\\n    assert captured[\\\"max_tokens\\\"] == 25\\n    assert captured[\\\"request_timeout\\\"] == 10.0\\n\\n\\ndef test_openai_reasoning_instantiation_omits_temperature_and_preserves_max_tokens():\\n    \\\"\\\"\\\"OpenAI reasoning models keep the caller's explicit output limit.\\n\\n    ChatOpenAI normalizes ``max_tokens`` to ``max_completion_tokens`` for\\n    reasoning models, so Langflow must forward the configured cap instead of\\n    silently discarding it.\\n    \\\"\\\"\\\"\\n    from lfx.base.models import unified_models as unified_models_module\\n    from lfx.base.models.unified_models.instantiation import get_llm\\n\\n    captured: dict = {}\\n\\n    class FakeChatOpenAI:\\n        def __init__(self, **kwargs):\\n            captured.update(kwargs)\\n\\n    selection = [\\n        {\\n            \\\"name\\\": \\\"o1\\\",\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"metadata\\\": {\\\"reasoning\\\": True, \\\"max_tokens_field_name\\\": \\\"max_tokens\\\"},\\n        }\\n    ]\\n    with (\\n        patch.object(unified_models_module, \\\"get_api_key_for_provider\\\", return_value=\\\"test-key\\\"),\\n        patch.object(unified_models_module, \\\"get_model_class\\\", return_value=FakeChatOpenAI),\\n        patch.object(unified_models_module, \\\"get_all_variables_for_provider\\\", return_value={}),\\n    ):\\n        get_llm(selection, user_id=\\\"user-1\\\", temperature=0.7, max_tokens=25)\\n\\n    assert \\\"temperature\\\" not in captured\\n    assert captured[\\\"max_tokens\\\"] == 25\\n    assert \\\"max_completion_tokens\\\" not in captured\\n\\n\\ndef test_foundry_validation_fails_when_sdk_is_missing():\\n    from lfx.base.models.unified_models.credentials import validate_model_provider_key\\n\\n    with (\\n        patch.dict(\\n            sys.modules,\\n            {\\\"langchain_azure_ai\\\": None, \\\"langchain_azure_ai.chat_models\\\": None},\\n        ),\\n        pytest.raises(ValueError, match=\\\"langchain-azure-ai\\\"),\\n    ):\\n        validate_model_provider_key(\\n            \\\"Azure AI Foundry\\\",\\n            {\\n                \\\"AZURE_AI_FOUNDRY_API_KEY\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n                \\\"AZURE_AI_FOUNDRY_ENDPOINT\\\": \\\"https://example.services.ai.azure.com/openai/v1\\\",\\n            },\\n            model_name=\\\"gpt-4o\\\",\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/models/test_watsonx_catalog.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"20db2556d39bb8144fbe9ab4ed34fe53c0aca4bb654e77ac999a89aafcd35f29\",\"content\":\"\\\"\\\"\\\"WatsonX seed-catalog and live-fetch metadata regressions.\\n\\nThe static seed list once marked every WatsonX model ``deprecated=True`` and\\n``fetch_live_watsonx_models`` copied that flag onto matching live results, so\\nthe Models page showed \\\"0 models\\\" for IBM WatsonX before *and* after\\ncredentials were configured \u2014 the catalog's default deprecated filter dropped\\neverything.\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import patch\\n\\nfrom lfx.base.models import model_utils\\nfrom lfx.base.models.watsonx_constants import (\\n    WATSONX_DEFAULT_EMBEDDING_MODELS,\\n    WATSONX_DEFAULT_LLM_MODELS,\\n)\\n\\n\\ndef test_seed_catalog_offers_active_models():\\n    active_llms = [m for m in WATSONX_DEFAULT_LLM_MODELS if not m.get(\\\"deprecated\\\")]\\n    active_embeddings = [m for m in WATSONX_DEFAULT_EMBEDDING_MODELS if not m.get(\\\"deprecated\\\")]\\n    assert active_llms, \\\"every seed LLM is deprecated: the provider renders as '0 models'\\\"\\n    assert active_embeddings, \\\"every seed embedding is deprecated: the embedding picker renders empty\\\"\\n\\n\\ndef test_fallback_names_exclude_withdrawn_models():\\n    withdrawn_llms = {m[\\\"name\\\"] for m in WATSONX_DEFAULT_LLM_MODELS if m.get(\\\"deprecated\\\")}\\n    assert withdrawn_llms.isdisjoint(model_utils.WATSONX_DEFAULT_LLM_MODEL_NAMES)\\n\\n    withdrawn_embeddings = {m[\\\"name\\\"] for m in WATSONX_DEFAULT_EMBEDDING_MODELS if m.get(\\\"deprecated\\\")}\\n    assert withdrawn_embeddings.isdisjoint(model_utils.WATSONX_DEFAULT_EMBEDDING_MODEL_NAMES)\\n\\n\\ndef _fetch_live(model_type: str, names: list[str]) -> list[dict]:\\n    with (\\n        patch.object(model_utils, \\\"get_provider_variable_value\\\", return_value=\\\"https://us-south.ml.cloud.ibm.com\\\"),\\n        patch.object(model_utils, \\\"get_watsonx_llm_models\\\", return_value=names),\\n        patch.object(model_utils, \\\"get_watsonx_embedding_models\\\", return_value=names),\\n    ):\\n        return model_utils.fetch_live_watsonx_models(\\\"00000000-0000-0000-0000-000000000000\\\", model_type)\\n\\n\\ndef test_live_models_do_not_inherit_static_deprecated_flag():\\n    # The live query already excludes withdrawn models (!lifecycle_withdrawn):\\n    # whatever it returns is current, even when the static seed flags the same\\n    # name as deprecated (stale seed data must never hide live models).\\n    deprecated_seed_name = next(m[\\\"name\\\"] for m in WATSONX_DEFAULT_LLM_MODELS if m.get(\\\"deprecated\\\"))\\n    result = _fetch_live(\\\"llm\\\", [deprecated_seed_name, \\\"brand-new-model\\\"])\\n    assert [m[\\\"deprecated\\\"] for m in result] == [False, False]\\n\\n\\ndef test_live_models_keep_static_tool_calling_flags():\\n    result = _fetch_live(\\\"llm\\\", [\\\"ibm/granite-guardian-3-8b\\\", \\\"unknown-model\\\"])\\n    by_name = {m[\\\"name\\\"]: m for m in result}\\n    assert by_name[\\\"ibm/granite-guardian-3-8b\\\"][\\\"tool_calling\\\"] is False\\n    assert by_name[\\\"unknown-model\\\"][\\\"tool_calling\\\"] is True\\n\\n\\ndef test_live_embedding_models_do_not_inherit_static_deprecated_flag():\\n    deprecated_seed_name = next(m[\\\"name\\\"] for m in WATSONX_DEFAULT_EMBEDDING_MODELS if m.get(\\\"deprecated\\\"))\\n    result = _fetch_live(\\\"embeddings\\\", [deprecated_seed_name])\\n    assert result[0][\\\"deprecated\\\"] is False\\n    assert result[0][\\\"model_type\\\"] == \\\"embeddings\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/models/test_watsonx_provider.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2984f05d8dcb60b37ba3e3fb51eabf50e1de444d346ffc653cc255b47f823ab6\",\"content\":\"\\\"\\\"\\\"Regression tests for IBM WatsonX credential validation.\\\"\\\"\\\"\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import patch\\n\\nimport pytest\\n\\nWATSONX_VARIABLES = {\\n    \\\"WATSONX_APIKEY\\\": \\\"test-watsonx-key\\\",  # pragma: allowlist secret\\n    \\\"WATSONX_PROJECT_ID\\\": \\\"test-project-id\\\",\\n    \\\"WATSONX_URL\\\": \\\"https://us-south.ml.cloud.ibm.com\\\",\\n}\\n\\n\\ndef test_validate_watsonx_uses_live_model_when_static_catalog_has_no_active_models():\\n    from lfx.base.models import model_utils\\n    from lfx.base.models.unified_models import validate_model_provider_key\\n\\n    calls = {}\\n\\n    class FakeChatWatsonx:\\n        def __init__(self, **kwargs):\\n            calls[\\\"kwargs\\\"] = kwargs\\n\\n        def invoke(self, prompt):\\n            calls[\\\"prompt\\\"] = prompt\\n            return \\\"ok\\\"\\n\\n    with (\\n        patch.dict(\\\"sys.modules\\\", {\\\"langchain_ibm\\\": SimpleNamespace(ChatWatsonx=FakeChatWatsonx)}),\\n        patch(\\\"lfx.base.models.unified_models.model_catalog.get_unified_models_detailed\\\", return_value=[]),\\n        patch(\\\"lfx.base.models.unified_models.credentials.validate_connector_url_for_ssrf\\\"),\\n        patch.object(\\n            model_utils,\\n            \\\"get_watsonx_llm_models\\\",\\n            return_value=[\\\"ibm/granite-current\\\"],\\n        ) as get_live_models,\\n    ):\\n        validate_model_provider_key(\\\"IBM WatsonX\\\", WATSONX_VARIABLES)\\n\\n    get_live_models.assert_called_once_with(\\n        \\\"https://us-south.ml.cloud.ibm.com\\\",\\n        default_models=[],\\n    )\\n    assert calls[\\\"kwargs\\\"][\\\"apikey\\\"] == \\\"test-watsonx-key\\\"  # pragma: allowlist secret\\n    assert calls[\\\"kwargs\\\"][\\\"model_id\\\"] == \\\"ibm/granite-current\\\"\\n    assert calls[\\\"kwargs\\\"][\\\"project_id\\\"] == \\\"test-project-id\\\"\\n    assert calls[\\\"prompt\\\"] == \\\"test\\\"\\n\\n\\ndef test_validate_watsonx_rejects_ibm_iam_error():\\n    from lfx.base.models import model_utils\\n    from lfx.base.models.unified_models import validate_model_provider_key\\n\\n    class FakeChatWatsonx:\\n        def __init__(self, **_kwargs):\\n            pass\\n\\n        def invoke(self, _prompt):\\n            msg = \\\"BXNIM0410E: Provided user not found or active.\\\"\\n            raise RuntimeError(msg)\\n\\n    with (\\n        patch.dict(\\\"sys.modules\\\", {\\\"langchain_ibm\\\": SimpleNamespace(ChatWatsonx=FakeChatWatsonx)}),\\n        patch(\\\"lfx.base.models.unified_models.model_catalog.get_unified_models_detailed\\\", return_value=[]),\\n        patch(\\\"lfx.base.models.unified_models.credentials.validate_connector_url_for_ssrf\\\"),\\n        patch.object(model_utils, \\\"get_watsonx_llm_models\\\", return_value=[\\\"ibm/granite-current\\\"]),\\n        pytest.raises(ValueError, match=\\\"Could not validate IBM WatsonX credentials\\\"),\\n    ):\\n        validate_model_provider_key(\\\"IBM WatsonX\\\", WATSONX_VARIABLES)\\n\\n\\ndef test_validate_watsonx_fails_when_no_test_model_is_available():\\n    from lfx.base.models import model_utils\\n    from lfx.base.models.unified_models import validate_model_provider_key\\n\\n    with (\\n        patch(\\\"lfx.base.models.unified_models.model_catalog.get_unified_models_detailed\\\", return_value=[]),\\n        patch(\\\"lfx.base.models.unified_models.credentials.validate_connector_url_for_ssrf\\\"),\\n        patch.object(model_utils, \\\"get_watsonx_llm_models\\\", return_value=[]),\\n        pytest.raises(ValueError, match=\\\"No IBM WatsonX chat model is available\\\"),\\n    ):\\n        validate_model_provider_key(\\\"IBM WatsonX\\\", WATSONX_VARIABLES)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/test_base_datastax_shim.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"59b850511d4fe385201fa9ee7e18d163dc5bbfaac3a1c065073f6dc071ac79f0\",\"content\":\"\\\"\\\"\\\"Contract tests for the ``lfx.base.datastax`` compatibility shim.\\n\\nThe datastax graduation moved ``lfx.base.datastax`` into the\\n``lfx-datastax`` distribution (``lfx_datastax.base``).  Saved flows and\\nstarter-project templates embed ``from lfx.base.datastax.astradb_base\\nimport AstraDBBaseComponent`` inside their stored component ``code``\\nfields, and that source is re-executed verbatim at flow build time --\\nso the legacy import path must keep resolving whenever the bundle is\\ninstalled.\\n\\\"\\\"\\\"\\n\\nimport importlib\\nimport importlib.util\\nimport sys\\nfrom pathlib import Path\\n\\nimport pytest\\n\\nimport lfx\\n\\n_SHIM_PATH = Path(lfx.__file__).resolve().parent / \\\"base\\\" / \\\"datastax\\\" / \\\"__init__.py\\\"\\n\\n_BUNDLE_INSTALLED = importlib.util.find_spec(\\\"lfx_datastax\\\") is not None\\n\\n\\ndef test_shim_file_shape() -> None:\\n    \\\"\\\"\\\"The shim is a single marker-tagged file with no sibling implementations.\\\"\\\"\\\"\\n    source = _SHIM_PATH.read_text(encoding=\\\"utf-8\\\")\\n    first_line = source.splitlines()[0]\\n    assert first_line == \\\"# lfx-bundles-shim\\\"\\n    assert 'importlib.import_module(\\\"lfx_datastax.base\\\")' in source\\n    # Narrow except: only a missing bundle is translated; transitive\\n    # dep failures must re-raise untouched.\\n    assert 'exc.name == \\\"lfx_datastax\\\"' in source\\n    siblings = [p for p in _SHIM_PATH.parent.iterdir() if p.name not in {\\\"__init__.py\\\", \\\"__pycache__\\\"}]\\n    assert not siblings, f\\\"shim dir must contain only __init__.py, found: {siblings}\\\"\\n\\n\\n@pytest.mark.skipif(not _BUNDLE_INSTALLED, reason=\\\"lfx-datastax not installed in this environment\\\")\\ndef test_shim_aliases_to_bundle_base() -> None:\\n    \\\"\\\"\\\"``import lfx.base.datastax`` resolves to ``lfx_datastax.base``.\\\"\\\"\\\"\\n    for mod in (\\\"lfx.base.datastax\\\", \\\"lfx.base.datastax.astradb_base\\\"):\\n        sys.modules.pop(mod, None)\\n    shim = importlib.import_module(\\\"lfx.base.datastax\\\")\\n    real = importlib.import_module(\\\"lfx_datastax.base\\\")\\n    assert shim is real\\n\\n\\n@pytest.mark.skipif(not _BUNDLE_INSTALLED, reason=\\\"lfx-datastax not installed in this environment\\\")\\ndef test_stored_flow_import_path_resolves() -> None:\\n    \\\"\\\"\\\"The exact import embedded in saved-flow code fields keeps working.\\\"\\\"\\\"\\n    for mod in (\\\"lfx.base.datastax\\\", \\\"lfx.base.datastax.astradb_base\\\"):\\n        sys.modules.pop(mod, None)\\n    namespace: dict[str, object] = {}\\n    exec(\\\"from lfx.base.datastax.astradb_base import AstraDBBaseComponent\\\", namespace)  # noqa: S102\\n    assert namespace[\\\"AstraDBBaseComponent\\\"] is not None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/tools/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/vectorstores/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/base/vectorstores/test_user_scoping.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e53d0f6da9c7b62d18d9c3f1aacd789e8460f2a3394b4aab6e0fb4cb469f061d\",\"content\":\"\\\"\\\"\\\"Unit tests for the shared per-user vector-store scoping helpers.\\\"\\\"\\\"\\n\\nfrom types import SimpleNamespace\\n\\nfrom lfx.base.vectorstores.user_scoping import runtime_user_id, scoped_collection_name\\n\\n\\nclass TestScopedCollectionName:\\n    def test_scopes_name_for_a_user(self) -> None:\\n        scoped = scoped_collection_name(\\\"shared\\\", \\\"owner-user\\\")\\n        assert scoped != \\\"shared\\\"\\n        assert scoped.startswith(\\\"lf_\\\")\\n        # \\\"lf_\\\" + 16 hex characters\\n        assert len(scoped) == 19\\n\\n    def test_is_stable_for_same_inputs(self) -> None:\\n        assert scoped_collection_name(\\\"shared\\\", \\\"owner-user\\\") == scoped_collection_name(\\\"shared\\\", \\\"owner-user\\\")\\n\\n    def test_different_users_get_different_names(self) -> None:\\n        owner = scoped_collection_name(\\\"shared\\\", \\\"owner-user\\\")\\n        attacker = scoped_collection_name(\\\"shared\\\", \\\"attacker-user\\\")\\n        assert owner != attacker\\n\\n    def test_different_collections_get_different_names(self) -> None:\\n        first = scoped_collection_name(\\\"collection-a\\\", \\\"owner-user\\\")\\n        second = scoped_collection_name(\\\"collection-b\\\", \\\"owner-user\\\")\\n        assert first != second\\n\\n    def test_separator_boundary_is_unambiguous(self) -> None:\\n        # A bare \\\"{user_id}:{collection_name}\\\" join collides for these two pairs\\n        # (\\\"a:b\\\" + \\\":\\\" + \\\"c\\\"  ==  \\\"a\\\" + \\\":\\\" + \\\"b:c\\\"); length-prefixing must keep\\n        # them distinct so different users/collections never share a local store.\\n        assert scoped_collection_name(\\\"c\\\", \\\"a:b\\\") != scoped_collection_name(\\\"b:c\\\", \\\"a\\\")\\n\\n    def test_falls_back_when_user_id_is_none(self) -> None:\\n        assert scoped_collection_name(\\\"shared\\\", None) == \\\"shared\\\"\\n\\n    def test_falls_back_when_user_id_is_literal_none_string(self) -> None:\\n        # PlaceholderGraph stringifies a missing user id to \\\"None\\\"\\n        assert scoped_collection_name(\\\"shared\\\", \\\"None\\\") == \\\"shared\\\"\\n\\n    def test_falls_back_when_user_id_is_blank(self) -> None:\\n        assert scoped_collection_name(\\\"shared\\\", \\\"   \\\") == \\\"shared\\\"\\n\\n    def test_falls_back_when_collection_name_is_empty(self) -> None:\\n        assert scoped_collection_name(\\\"\\\", \\\"owner-user\\\") == \\\"\\\"\\n\\n    def test_accepts_non_string_user_id(self) -> None:\\n        scoped = scoped_collection_name(\\\"shared\\\", 1234)\\n        assert scoped.startswith(\\\"lf_\\\")\\n        assert scoped == scoped_collection_name(\\\"shared\\\", \\\"1234\\\")\\n\\n\\nclass TestRuntimeUserId:\\n    def test_returns_none_without_user_or_graph(self) -> None:\\n        component = SimpleNamespace()\\n        assert runtime_user_id(component) is None\\n\\n    def test_prefers_direct_user_id(self) -> None:\\n        component = SimpleNamespace(_user_id=\\\"u42\\\")\\n        assert runtime_user_id(component) == \\\"u42\\\"\\n\\n    def test_falls_back_to_graph_user_id(self) -> None:\\n        graph = SimpleNamespace(user_id=\\\"graph-user\\\")\\n        vertex = SimpleNamespace(graph=graph)\\n        component = SimpleNamespace(_user_id=None, _vertex=vertex)\\n        assert runtime_user_id(component) == \\\"graph-user\\\"\\n\\n    def test_direct_user_id_wins_over_graph(self) -> None:\\n        graph = SimpleNamespace(user_id=\\\"graph-user\\\")\\n        vertex = SimpleNamespace(graph=graph)\\n        component = SimpleNamespace(_user_id=\\\"u42\\\", _vertex=vertex)\\n        assert runtime_user_id(component) == \\\"u42\\\"\\n\\n    def test_handles_vertex_without_graph(self) -> None:\\n        component = SimpleNamespace(_user_id=None, _vertex=SimpleNamespace(graph=None))\\n        assert runtime_user_id(component) is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"01e0d2b01b86b227576ed433b55990b034981068161cb4aa9b7d159e929c1639\",\"content\":\"\\\"\\\"\\\"Test suite for LFX CLI.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_cli_help_smoke.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"820755ba0753a858f9fcd13ee86dc87c935e432621d022b2206ad6cb7abbf7ce\",\"content\":\"\\\"\\\"\\\"Smoke tests: every lfx subcommand's --help must exit 0.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom lfx.__main__ import app\\nfrom typer.testing import CliRunner\\n\\nrunner = CliRunner()\\n\\nALL_SUBCOMMANDS = [\\n    \\\"init\\\",\\n    \\\"login\\\",\\n    \\\"create\\\",\\n    \\\"requirements\\\",\\n    \\\"validate\\\",\\n    \\\"run\\\",\\n    \\\"serve\\\",\\n    \\\"status\\\",\\n    \\\"push\\\",\\n    \\\"pull\\\",\\n    \\\"export\\\",\\n]\\n\\n\\ndef test_root_help():\\n    result = runner.invoke(app, [\\\"--help\\\"])\\n    assert result.exit_code == 0\\n    assert \\\"lfx\\\" in result.output.lower()\\n\\n\\n@pytest.mark.parametrize(\\\"cmd\\\", ALL_SUBCOMMANDS)\\ndef test_subcommand_help(cmd: str):\\n    result = runner.invoke(app, [cmd, \\\"--help\\\"])\\n    assert result.exit_code == 0, f\\\"`lfx {cmd} --help` failed: {result.output}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_command_plugins.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3eaf1d0a14825573d53c8b5cd16a8d6dd4a4840d4a9d085bf5ac6845ce4f0d0c\",\"content\":\"\\\"\\\"\\\"Tests for third-party CLI command registration.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib\\nfrom dataclasses import dataclass\\nfrom typing import Any\\n\\nimport pytest\\nimport typer\\nfrom lfx.cli import command_plugins\\nfrom typer.testing import CliRunner\\n\\n\\n@dataclass\\nclass _FakeEntryPoint:\\n    name: str\\n    value: str\\n    target: Any = None\\n    error: Exception | None = None\\n\\n    def load(self) -> Any:\\n        if self.error is not None:\\n            raise self.error\\n        return self.target\\n\\n\\ndef _command_register(name: str, calls: list[str], output: str = \\\"registered\\\"):\\n    def register(app: typer.Typer) -> None:\\n        calls.append(name)\\n\\n        @app.command(name=name)\\n        def plugin_command() -> None:\\n            typer.echo(output)\\n\\n    return register\\n\\n\\ndef _group_register(name: str):\\n    def register(app: typer.Typer) -> None:\\n        app.add_typer(typer.Typer(), name=name)\\n\\n    return register\\n\\n\\ndef _callback_register(name: str):\\n    def register(app: typer.Typer) -> None:\\n        def plugin_callback() -> None:\\n            pass\\n\\n        plugin_callback.__name__ = name\\n        app.callback()(plugin_callback)\\n\\n    return register\\n\\n\\ndef test_plugins_are_discovered_from_the_documented_group_in_deterministic_order(monkeypatch):\\n    calls: list[str] = []\\n    requested_groups: list[str] = []\\n    entry_points = [\\n        _FakeEntryPoint(\\\"zeta\\\", \\\"plugins.zeta:register\\\", _command_register(\\\"zeta\\\", calls)),\\n        _FakeEntryPoint(\\\"alpha\\\", \\\"plugins.alpha:register\\\", _command_register(\\\"alpha\\\", calls)),\\n    ]\\n\\n    def discover(*, group: str):\\n        requested_groups.append(group)\\n        return entry_points\\n\\n    monkeypatch.setattr(command_plugins.metadata, \\\"entry_points\\\", discover)\\n\\n    command_plugins.register_cli_command_plugins(typer.Typer())\\n\\n    assert requested_groups == [\\\"langflow.cli_commands\\\"]\\n    assert calls == [\\\"alpha\\\", \\\"zeta\\\"]\\n\\n\\ndef test_registered_plugin_command_is_invokable(monkeypatch):\\n    app = typer.Typer()\\n\\n    @app.callback()\\n    def root() -> None:\\n        pass\\n\\n    entry_point = _FakeEntryPoint(\\n        \\\"hello\\\",\\n        \\\"plugins.hello:register\\\",\\n        _command_register(\\\"hello\\\", [], output=\\\"hello from plugin\\\"),\\n    )\\n    monkeypatch.setattr(\\n        command_plugins.metadata,\\n        \\\"entry_points\\\",\\n        lambda *, group: [entry_point] if group == \\\"langflow.cli_commands\\\" else [],\\n    )\\n\\n    command_plugins.register_cli_command_plugins(app)\\n    result = CliRunner().invoke(app, [\\\"hello\\\"])\\n\\n    assert result.exit_code == 0\\n    assert result.output == \\\"hello from plugin\\\\n\\\"\\n\\n\\ndef test_non_callable_plugin_fails_before_mutating_the_app(monkeypatch):\\n    calls: list[str] = []\\n    entry_points = [\\n        _FakeEntryPoint(\\\"alpha\\\", \\\"plugins.alpha:register\\\", _command_register(\\\"alpha\\\", calls)),\\n        _FakeEntryPoint(\\\"broken\\\", \\\"plugins.broken:not_register\\\", object()),\\n    ]\\n    monkeypatch.setattr(\\n        command_plugins.metadata,\\n        \\\"entry_points\\\",\\n        lambda *, group: entry_points if group == \\\"langflow.cli_commands\\\" else [],\\n    )\\n\\n    with pytest.raises(command_plugins.CLICommandPluginError, match=r\\\"broken.*not callable\\\"):\\n        command_plugins.register_cli_command_plugins(typer.Typer())\\n\\n    assert calls == []\\n\\n\\ndef test_plugin_load_failure_names_the_plugin_and_preserves_the_cause(monkeypatch):\\n    failure = ImportError(\\\"dependency unavailable\\\")\\n    entry_point = _FakeEntryPoint(\\\"broken\\\", \\\"plugins.broken:register\\\", error=failure)\\n    monkeypatch.setattr(\\n        command_plugins.metadata,\\n        \\\"entry_points\\\",\\n        lambda *, group: [entry_point] if group == \\\"langflow.cli_commands\\\" else [],\\n    )\\n\\n    with pytest.raises(command_plugins.CLICommandPluginError, match=r\\\"broken.*plugins.broken:register\\\") as exc_info:\\n        command_plugins.register_cli_command_plugins(typer.Typer())\\n\\n    assert exc_info.value.__cause__ is failure\\n\\n\\ndef test_plugin_registration_failure_rolls_back_all_plugin_commands(monkeypatch):\\n    app = typer.Typer()\\n\\n    @app.command(name=\\\"builtin\\\")\\n    def builtin() -> None:\\n        pass\\n\\n    def broken_register(target_app: typer.Typer) -> None:\\n        target_app.command(name=\\\"partial\\\")(lambda: None)\\n        msg = \\\"registration exploded\\\"\\n        raise RuntimeError(msg)\\n\\n    failure_entry_point = _FakeEntryPoint(\\\"broken\\\", \\\"plugins.broken:register\\\", broken_register)\\n    monkeypatch.setattr(\\n        command_plugins.metadata,\\n        \\\"entry_points\\\",\\n        lambda *, group: [failure_entry_point] if group == \\\"langflow.cli_commands\\\" else [],\\n    )\\n\\n    with pytest.raises(command_plugins.CLICommandPluginError, match=r\\\"broken.*plugins.broken:register\\\") as exc_info:\\n        command_plugins.register_cli_command_plugins(app)\\n\\n    assert isinstance(exc_info.value.__cause__, RuntimeError)\\n    assert [command.name for command in app.registered_commands] == [\\\"builtin\\\"]\\n\\n\\ndef test_plugin_command_cannot_shadow_builtin_effective_name(monkeypatch):\\n    app = typer.Typer()\\n\\n    @app.command()\\n    def existing_command() -> None:\\n        pass\\n\\n    original_commands = list(app.registered_commands)\\n    entry_point = _FakeEntryPoint(\\n        \\\"collision\\\",\\n        \\\"plugins.collision:register\\\",\\n        _command_register(\\\"existing-command\\\", []),\\n    )\\n    monkeypatch.setattr(\\n        command_plugins.metadata,\\n        \\\"entry_points\\\",\\n        lambda *, group: [entry_point] if group == \\\"langflow.cli_commands\\\" else [],\\n    )\\n\\n    with pytest.raises(\\n        command_plugins.CLICommandPluginError,\\n        match=r\\\"collision.*existing-command.*already registered\\\",\\n    ):\\n        command_plugins.register_cli_command_plugins(app)\\n\\n    assert app.registered_commands == original_commands\\n\\n\\ndef test_plugin_group_cannot_shadow_earlier_plugin_command(monkeypatch):\\n    app = typer.Typer()\\n\\n    @app.command(name=\\\"builtin\\\")\\n    def builtin() -> None:\\n        pass\\n\\n    original_commands = list(app.registered_commands)\\n    entry_points = [\\n        _FakeEntryPoint(\\\"alpha\\\", \\\"plugins.alpha:register\\\", _command_register(\\\"shared\\\", [])),\\n        _FakeEntryPoint(\\\"beta\\\", \\\"plugins.beta:register\\\", _group_register(\\\"shared\\\")),\\n    ]\\n    monkeypatch.setattr(\\n        command_plugins.metadata,\\n        \\\"entry_points\\\",\\n        lambda *, group: entry_points if group == \\\"langflow.cli_commands\\\" else [],\\n    )\\n\\n    with pytest.raises(\\n        command_plugins.CLICommandPluginError,\\n        match=r\\\"beta.*shared.*already registered\\\",\\n    ):\\n        command_plugins.register_cli_command_plugins(app)\\n\\n    assert app.registered_commands == original_commands\\n    assert app.registered_groups == []\\n\\n\\ndef test_plugin_callback_cannot_replace_builtin_callback(monkeypatch):\\n    app = typer.Typer()\\n\\n    @app.callback()\\n    def builtin_callback() -> None:\\n        pass\\n\\n    original_callback = app.registered_callback\\n    entry_point = _FakeEntryPoint(\\n        \\\"collision\\\",\\n        \\\"plugins.collision:register\\\",\\n        _callback_register(\\\"plugin\\\"),\\n    )\\n    monkeypatch.setattr(\\n        command_plugins.metadata,\\n        \\\"entry_points\\\",\\n        lambda *, group: [entry_point] if group == \\\"langflow.cli_commands\\\" else [],\\n    )\\n\\n    with pytest.raises(\\n        command_plugins.CLICommandPluginError,\\n        match=r\\\"collision.*callback.*already registered\\\",\\n    ):\\n        command_plugins.register_cli_command_plugins(app)\\n\\n    assert app.registered_callback is original_callback\\n\\n\\ndef test_plugin_callback_cannot_replace_earlier_plugin_callback(monkeypatch):\\n    app = typer.Typer()\\n    entry_points = [\\n        _FakeEntryPoint(\\\"alpha\\\", \\\"plugins.alpha:register\\\", _callback_register(\\\"alpha\\\")),\\n        _FakeEntryPoint(\\\"beta\\\", \\\"plugins.beta:register\\\", _callback_register(\\\"beta\\\")),\\n    ]\\n    monkeypatch.setattr(\\n        command_plugins.metadata,\\n        \\\"entry_points\\\",\\n        lambda *, group: entry_points if group == \\\"langflow.cli_commands\\\" else [],\\n    )\\n\\n    with pytest.raises(\\n        command_plugins.CLICommandPluginError,\\n        match=r\\\"beta.*callback.*already registered\\\",\\n    ):\\n        command_plugins.register_cli_command_plugins(app)\\n\\n    assert app.registered_callback is None\\n\\n\\ndef test_entry_point_discovery_failure_is_reported_with_its_cause(monkeypatch):\\n    failure = RuntimeError(\\\"metadata unavailable\\\")\\n\\n    def fail_discovery(*, group: str):\\n        assert group == \\\"langflow.cli_commands\\\"\\n        raise failure\\n\\n    monkeypatch.setattr(command_plugins.metadata, \\\"entry_points\\\", fail_discovery)\\n\\n    with pytest.raises(command_plugins.CLICommandPluginError, match=r\\\"discover.*langflow.cli_commands\\\") as exc_info:\\n        command_plugins.register_cli_command_plugins(typer.Typer())\\n\\n    assert exc_info.value.__cause__ is failure\\n\\n\\ndef test_lfx_root_app_does_not_discover_langflow_plugin_commands(monkeypatch):\\n    import lfx.__main__ as lfx_main\\n\\n    requested_groups: list[str] = []\\n    entry_point = _FakeEntryPoint(\\n        \\\"fixture\\\",\\n        \\\"plugins.fixture:register\\\",\\n        _command_register(\\\"fixture-plugin\\\", [], output=\\\"lfx plugin\\\"),\\n    )\\n\\n    def discover(*, group: str):\\n        requested_groups.append(group)\\n        return [entry_point] if group == \\\"langflow.cli_commands\\\" else []\\n\\n    with monkeypatch.context() as scoped_patch:\\n        scoped_patch.setattr(\\n            command_plugins.metadata,\\n            \\\"entry_points\\\",\\n            discover,\\n        )\\n        reloaded_main = importlib.reload(lfx_main)\\n        result = CliRunner().invoke(reloaded_main.app, [\\\"fixture-plugin\\\"])\\n\\n    importlib.reload(lfx_main)\\n\\n    assert \\\"langflow.cli_commands\\\" not in requested_groups\\n    assert result.exit_code == 2\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_common.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ee787524bcadbc1cbd3940e49f6b0fe030190b07f081bc7efeb1f5d43a2b59d9\",\"content\":\"\\\"\\\"\\\"Unit tests for LFX CLI common utilities.\\\"\\\"\\\"\\n\\nimport asyncio\\nimport os\\nimport socket\\nimport sys\\nimport uuid\\nfrom io import StringIO\\nfrom pathlib import Path\\nfrom unittest.mock import MagicMock, Mock, patch\\n\\nimport pytest\\nimport typer\\nfrom lfx.cli.common import (\\n    create_verbose_printer,\\n    execute_graph_with_capture,\\n    extract_result_data,\\n    flow_id_from_path,\\n    get_api_key,\\n    get_best_access_host,\\n    get_free_port,\\n    is_port_in_use,\\n    load_graph_from_path,\\n)\\n\\n\\nclass TestVerbosePrinter:\\n    \\\"\\\"\\\"Test verbose printer functionality.\\\"\\\"\\\"\\n\\n    def test_verbose_printer_when_verbose_true(self):\\n        \\\"\\\"\\\"Test that verbose printer prints when verbose is True.\\\"\\\"\\\"\\n        with patch.object(typer, \\\"echo\\\") as mock_echo:\\n            printer = create_verbose_printer(verbose=True)\\n            printer(\\\"Test message\\\")\\n            mock_echo.assert_called_once_with(\\\"Test message\\\", file=sys.stderr)\\n\\n    def test_verbose_printer_when_verbose_false(self):\\n        \\\"\\\"\\\"Test that verbose printer doesn't print when verbose is False.\\\"\\\"\\\"\\n        with patch.object(typer, \\\"echo\\\") as mock_echo:\\n            printer = create_verbose_printer(verbose=False)\\n            printer(\\\"Test message\\\")\\n            mock_echo.assert_not_called()\\n\\n\\nclass TestPortUtilities:\\n    \\\"\\\"\\\"Test port-related utilities.\\\"\\\"\\\"\\n\\n    def test_is_port_in_use_free_port(self):\\n        \\\"\\\"\\\"Test checking if a port is free.\\\"\\\"\\\"\\n        # Find a free port first\\n        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\\n            s.bind((\\\"\\\", 0))\\n            free_port = s.getsockname()[1]\\n\\n        # Port should be free after closing socket\\n        assert not is_port_in_use(free_port)\\n\\n    def test_is_port_in_use_occupied_port(self):\\n        \\\"\\\"\\\"Test checking if a port is occupied.\\\"\\\"\\\"\\n        # Occupy a port\\n        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\\n            s.bind((\\\"\\\", 0))\\n            occupied_port = s.getsockname()[1]\\n            # While socket is open, port should be in use\\n            assert is_port_in_use(occupied_port)\\n\\n    def test_get_free_port_finds_available_port(self):\\n        \\\"\\\"\\\"Test finding a free port.\\\"\\\"\\\"\\n        port = get_free_port(8000)\\n        assert isinstance(port, int)\\n        assert 8000 <= port <= 65535\\n        # Verify the port is actually free\\n        assert not is_port_in_use(port)\\n\\n    def test_get_free_port_with_occupied_starting_port(self):\\n        \\\"\\\"\\\"Test finding a free port when starting port is occupied.\\\"\\\"\\\"\\n        # Occupy a port\\n        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\\n            s.bind((\\\"\\\", 0))\\n            occupied_port = s.getsockname()[1]\\n\\n            # Should find a different port\\n            free_port = get_free_port(occupied_port)\\n            assert free_port != occupied_port\\n            assert not is_port_in_use(free_port)\\n\\n    def test_get_free_port_no_ports_available(self):\\n        \\\"\\\"\\\"Test error when no free ports are available.\\\"\\\"\\\"\\n        with patch(\\\"socket.socket\\\") as mock_socket:\\n            # Mock socket to always raise OSError (port in use)\\n            mock_socket.return_value.__enter__.return_value.bind.side_effect = OSError\\n\\n            with pytest.raises(RuntimeError, match=\\\"No free ports available\\\"):\\n                get_free_port(65534)  # Start near the end\\n\\n\\nclass TestHostUtilities:\\n    \\\"\\\"\\\"Test host-related utilities.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"input_host\\\", \\\"expected\\\"),\\n        [\\n            (\\\"0.0.0.0\\\", \\\"localhost\\\"),\\n            (\\\"\\\", \\\"localhost\\\"),\\n            (\\\"127.0.0.1\\\", \\\"127.0.0.1\\\"),\\n            (\\\"localhost\\\", \\\"localhost\\\"),\\n            (\\\"example.com\\\", \\\"example.com\\\"),\\n        ],\\n    )\\n    def test_get_best_access_host(self, input_host, expected):\\n        \\\"\\\"\\\"Test getting the best access host for display.\\\"\\\"\\\"\\n        assert get_best_access_host(input_host) == expected\\n\\n\\nclass TestApiKey:\\n    \\\"\\\"\\\"Test API key utilities.\\\"\\\"\\\"\\n\\n    def test_get_api_key_success(self):\\n        \\\"\\\"\\\"Test getting API key when it exists.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-api-key\\\"}):  # pragma: allowlist secret\\n            assert get_api_key() == \\\"test-api-key\\\"\\n\\n    def test_get_api_key_not_set(self):\\n        \\\"\\\"\\\"Test error when API key is not set.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {}, clear=True),\\n            pytest.raises(ValueError, match=\\\"LANGFLOW_API_KEY environment variable is not set\\\"),\\n        ):\\n            get_api_key()\\n\\n    def test_get_api_key_empty_string(self):\\n        \\\"\\\"\\\"Test error when API key is empty string.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"\\\"}),\\n            pytest.raises(ValueError, match=\\\"LANGFLOW_API_KEY environment variable is not set\\\"),\\n        ):\\n            get_api_key()\\n\\n\\nclass TestFlowId:\\n    \\\"\\\"\\\"Test flow ID generation.\\\"\\\"\\\"\\n\\n    def test_flow_id_from_path_deterministic(self):\\n        \\\"\\\"\\\"Test that flow ID generation is deterministic.\\\"\\\"\\\"\\n        root = Path(\\\"/test/root\\\")\\n        path = Path(\\\"/test/root/flows/example.json\\\")\\n\\n        # Generate ID multiple times\\n        id1 = flow_id_from_path(path, root)\\n        id2 = flow_id_from_path(path, root)\\n\\n        # Should be the same\\n        assert id1 == id2\\n        # Should be a valid UUID\\n        assert uuid.UUID(id1)\\n\\n    def test_flow_id_from_path_different_paths(self):\\n        \\\"\\\"\\\"Test that different paths generate different IDs.\\\"\\\"\\\"\\n        root = Path(\\\"/test/root\\\")\\n        path1 = Path(\\\"/test/root/flows/example1.json\\\")\\n        path2 = Path(\\\"/test/root/flows/example2.json\\\")\\n\\n        id1 = flow_id_from_path(path1, root)\\n        id2 = flow_id_from_path(path2, root)\\n\\n        assert id1 != id2\\n\\n\\nclass TestLoadGraph:\\n    \\\"\\\"\\\"Test graph loading functionality.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_load_graph_from_path_success(self):\\n        \\\"\\\"\\\"Test successful graph loading from JSON.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.nodes = [1, 2, 3]\\n\\n        with patch(\\\"lfx.cli.common.load_flow_from_json\\\", return_value=mock_graph) as mock_load_flow:\\n            verbose_print = Mock()\\n            path = Path(\\\"/test/flow.json\\\")\\n\\n            result = await load_graph_from_path(path, \\\".json\\\", verbose_print, verbose=True)\\n\\n            assert result == mock_graph\\n            mock_load_flow.assert_called_once_with(path, disable_logs=False)\\n            verbose_print.assert_any_call(f\\\"Analyzing JSON flow: {path}\\\")\\n            verbose_print.assert_any_call(\\\"Loading JSON flow...\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_load_graph_from_path_failure(self):\\n        \\\"\\\"\\\"Test graph loading failure.\\\"\\\"\\\"\\n        with patch(\\\"lfx.cli.common.load_flow_from_json\\\", side_effect=Exception(\\\"Load error\\\")) as mock_load_flow:\\n            verbose_print = Mock()\\n            path = Path(\\\"/test/flow.json\\\")\\n\\n            with pytest.raises(typer.Exit) as exc_info:\\n                await load_graph_from_path(path, \\\".json\\\", verbose_print, verbose=False)\\n\\n            assert exc_info.value.exit_code == 1\\n            mock_load_flow.assert_called_once_with(path, disable_logs=True)\\n            verbose_print.assert_any_call(\\\"\u2717 Failed to load graph: Load error\\\")\\n\\n\\nclass TestGraphExecution:\\n    \\\"\\\"\\\"Test graph execution utilities.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_with_capture_keeps_concurrent_logs_request_local(self):\\n        \\\"\\\"\\\"Concurrent graph output must not cross request boundaries.\\\"\\\"\\\"\\n        first_entered = asyncio.Event()\\n        second_entered = asyncio.Event()\\n        first_finished = asyncio.Event()\\n\\n        def make_graph(label: str, wait_for: asyncio.Event, entered: asyncio.Event):\\n            async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n                sys.stdout.write(f\\\"{label}-stdout-before\\\\n\\\")\\n                sys.stderr.write(f\\\"{label}-stderr-before\\\\n\\\")\\n                entered.set()\\n                await wait_for.wait()\\n                sys.stdout.write(f\\\"{label}-stdout-after\\\\n\\\")\\n                sys.stderr.write(f\\\"{label}-stderr-after\\\\n\\\")\\n                yield MagicMock(results={\\\"text\\\": label})\\n\\n            graph = MagicMock()\\n            graph.context = {}\\n            graph.async_start = mock_async_start\\n            return graph\\n\\n        first_graph = make_graph(\\\"first-secret\\\", second_entered, first_entered)\\n        second_graph = make_graph(\\\"second-secret\\\", first_finished, second_entered)\\n\\n        async def run_first():\\n            try:\\n                return await execute_graph_with_capture(first_graph, \\\"first input\\\")\\n            finally:\\n                first_finished.set()\\n\\n        original_stdout = sys.stdout\\n        original_stderr = sys.stderr\\n        try:\\n            first_task = asyncio.create_task(run_first())\\n            await first_entered.wait()\\n            second_task = asyncio.create_task(execute_graph_with_capture(second_graph, \\\"second input\\\"))\\n            (_, first_logs), (_, second_logs) = await asyncio.gather(first_task, second_task)\\n        finally:\\n            # The vulnerable implementation can restore the wrong request's\\n            # StringIO globally. Keep the regression self-contained when it fails.\\n            sys.stdout = original_stdout\\n            sys.stderr = original_stderr\\n\\n        assert \\\"first-secret-stdout-before\\\" in first_logs\\n        assert \\\"first-secret-stderr-after\\\" in first_logs\\n        assert \\\"second-secret\\\" not in first_logs\\n        assert \\\"second-secret-stdout-before\\\" in second_logs\\n        assert \\\"second-secret-stderr-after\\\" in second_logs\\n        assert \\\"first-secret\\\" not in second_logs\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_with_capture_preserves_single_request_logs(self):\\n        \\\"\\\"\\\"A normal request still receives both its stdout and stderr.\\\"\\\"\\\"\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            sys.stdout.write(\\\"single stdout\\\\n\\\")\\n            sys.stderr.write(\\\"single stderr\\\\n\\\")\\n            yield MagicMock(results={\\\"text\\\": \\\"ok\\\"})\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n\\n        process_stdout = StringIO()\\n        process_stderr = StringIO()\\n        with patch.object(sys, \\\"stdout\\\", process_stdout), patch.object(sys, \\\"stderr\\\", process_stderr):\\n            _, logs = await execute_graph_with_capture(mock_graph, \\\"test input\\\")\\n            sys.stdout.write(\\\"outside stdout\\\\n\\\")\\n            sys.stderr.write(\\\"outside stderr\\\\n\\\")\\n\\n        assert logs == \\\"single stdout\\\\nsingle stderr\\\\n\\\"\\n        assert process_stdout.getvalue() == \\\"outside stdout\\\\n\\\"\\n        assert process_stderr.getvalue() == \\\"outside stderr\\\\n\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_with_capture_deactivates_outliving_child_capture(self):\\n        \\\"\\\"\\\"A child task that outlives its graph writes to the process streams.\\\"\\\"\\\"\\n        child_started = asyncio.Event()\\n        release_child = asyncio.Event()\\n        child_task = None\\n\\n        async def write_after_graph_returns():\\n            child_started.set()\\n            await release_child.wait()\\n            sys.stdout.write(\\\"late child stdout\\\\n\\\")\\n            sys.stderr.write(\\\"late child stderr\\\\n\\\")\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            nonlocal child_task\\n            child_task = asyncio.create_task(write_after_graph_returns())\\n            await child_started.wait()\\n            sys.stdout.write(\\\"captured stdout\\\\n\\\")\\n            sys.stderr.write(\\\"captured stderr\\\\n\\\")\\n            yield MagicMock(results={\\\"text\\\": \\\"ok\\\"})\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n\\n        process_stdout = StringIO()\\n        process_stderr = StringIO()\\n        with patch.object(sys, \\\"stdout\\\", process_stdout), patch.object(sys, \\\"stderr\\\", process_stderr):\\n            _, logs = await execute_graph_with_capture(mock_graph, \\\"test input\\\")\\n            release_child.set()\\n            assert child_task is not None\\n            await child_task\\n\\n        assert logs == \\\"captured stdout\\\\ncaptured stderr\\\\n\\\"\\n        assert process_stdout.getvalue() == \\\"late child stdout\\\\n\\\"\\n        assert process_stderr.getvalue() == \\\"late child stderr\\\\n\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_with_capture_success(self):\\n        \\\"\\\"\\\"Test successful graph execution with output capture.\\\"\\\"\\\"\\n        # Mock graph and async iterator\\n        mock_result = MagicMock(results={\\\"text\\\": \\\"Test result\\\"})\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            yield mock_result\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n\\n        results, logs = await execute_graph_with_capture(mock_graph, \\\"test input\\\")\\n\\n        assert len(results) == 1\\n        assert results[0].results == {\\\"text\\\": \\\"Test result\\\"}\\n        assert logs == \\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_with_capture_with_message(self):\\n        \\\"\\\"\\\"Test graph execution with message output.\\\"\\\"\\\"\\n        # Mock result with message\\n        mock_result = MagicMock()\\n        mock_result.message.text = \\\"Message text\\\"\\n        # Ensure results attribute doesn't exist\\n        delattr(mock_result, \\\"results\\\")\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            yield mock_result\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n\\n        results, _ = await execute_graph_with_capture(mock_graph, \\\"test input\\\")\\n\\n        assert len(results) == 1\\n        assert results[0].message.text == \\\"Message text\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_activates_request_scope_from_context(self):\\n        \\\"\\\"\\\"Activate the request scope + no_env_fallback from graph.context, then reset them.\\n\\n        The flag and variables must be live during execution and cleared afterward so\\n        nothing leaks to the next request. Covers the wiring (graph.context -> ContextVars)\\n        that the serve_app tests skip by mocking out execute_graph_with_capture.\\n        \\\"\\\"\\\"\\n        from lfx.services.variable.request_scope import (\\n            get_active_request_variables,\\n            is_env_fallback_disabled,\\n        )\\n\\n        observed: dict[str, object] = {}\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            observed[\\\"scope\\\"] = get_active_request_variables()\\n            observed[\\\"no_env_fallback\\\"] = is_env_fallback_disabled()\\n            yield MagicMock(results={\\\"text\\\": \\\"ok\\\"})\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {\\n            \\\"request_variables\\\": {\\\"access_token\\\": \\\"secret\\\"},\\n            \\\"no_env_fallback\\\": True,\\n        }\\n        mock_graph.async_start = mock_async_start\\n\\n        await execute_graph_with_capture(mock_graph, \\\"test input\\\")\\n\\n        # During execution the scope reflected this request's global_vars + flag.\\n        assert observed[\\\"scope\\\"] == {\\\"access_token\\\": \\\"secret\\\"}\\n        assert observed[\\\"no_env_fallback\\\"] is True\\n        # After execution both ContextVars are reset (no bleed into the next request).\\n        assert get_active_request_variables() is None\\n        assert is_env_fallback_disabled() is False\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_with_capture_error(self):\\n        \\\"\\\"\\\"Test graph execution with error.\\\"\\\"\\\"\\n\\n        async def mock_async_start_error(inputs, **kwargs):  # noqa: ARG001\\n            msg = \\\"Execution failed\\\"\\n            raise RuntimeError(msg)\\n            yield  # This line never executes but makes it an async generator\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start_error\\n\\n        with pytest.raises(RuntimeError, match=\\\"Execution failed\\\"):\\n            await execute_graph_with_capture(mock_graph, \\\"test input\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_with_capture_autogenerates_session_id(self):\\n        \\\"\\\"\\\"Auto-generate a session_id when none is provided.\\n\\n        Message-store validators reject empty session_id, so the helper assigns one\\n        to keep streaming/persistence paths functional in lfx serve.\\n        \\\"\\\"\\\"\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            yield MagicMock(results={\\\"text\\\": \\\"ok\\\"})\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n\\n        await execute_graph_with_capture(mock_graph, \\\"test input\\\")\\n\\n        assert mock_graph.session_id, \\\"session_id should be auto-generated\\\"\\n        assert isinstance(mock_graph.session_id, str)\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_with_capture_preserves_caller_session_id(self):\\n        \\\"\\\"\\\"An explicit session_id wins over auto-generation.\\\"\\\"\\\"\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            yield MagicMock(results={\\\"text\\\": \\\"ok\\\"})\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n\\n        await execute_graph_with_capture(mock_graph, \\\"test input\\\", session_id=\\\"fixed-session\\\")\\n\\n        assert mock_graph.session_id == \\\"fixed-session\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_propagates_session_id_to_vertices(self):\\n        \\\"\\\"\\\"Session_id must reach Memory/MessageHistory inputs on the lfx serve path.\\n\\n        ``execute_graph_with_capture`` uses ``graph.async_start``, which bypasses\\n        the propagation loop in ``Graph._run``. The helper has to replicate it\\n        so served ``/run`` and ``/stream`` requests behave like the playground.\\n        \\\"\\\"\\\"\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            yield MagicMock(results={\\\"text\\\": \\\"ok\\\"})\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n        memory_vertex = MagicMock()\\n        memory_vertex.raw_params = {}\\n        memory_vertex.update_raw_params = MagicMock()\\n        mock_graph.has_session_id_vertices = [\\\"memory-1\\\"]\\n        mock_graph.get_vertex = MagicMock(return_value=memory_vertex)\\n\\n        await execute_graph_with_capture(mock_graph, \\\"test input\\\", session_id=\\\"my-conversation\\\")\\n\\n        memory_vertex.update_raw_params.assert_called_once_with({\\\"session_id\\\": \\\"my-conversation\\\"}, overwrite=True)\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_does_not_overwrite_hardcoded_session_id(self):\\n        \\\"\\\"\\\"Hardcoded session_id on a Memory component (set in flow JSON) wins over the request value.\\n\\n        Mirrors Langflow's playground precedence in ``build_graph_from_data``.\\n        \\\"\\\"\\\"\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            yield MagicMock(results={\\\"text\\\": \\\"ok\\\"})\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n        pinned_vertex = MagicMock()\\n        pinned_vertex.raw_params = {\\\"session_id\\\": \\\"hardcoded-in-flow\\\"}\\n        pinned_vertex.update_raw_params = MagicMock()\\n        mock_graph.has_session_id_vertices = [\\\"memory-pinned\\\"]\\n        mock_graph.get_vertex = MagicMock(return_value=pinned_vertex)\\n\\n        await execute_graph_with_capture(mock_graph, \\\"test input\\\", session_id=\\\"from-request\\\")\\n\\n        pinned_vertex.update_raw_params.assert_not_called()\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_autogenerates_user_id_when_unset(self):\\n        \\\"\\\"\\\"When the graph arrives without a user_id (typical for lfx serve), assign a UUID.\\n\\n        AgentComponent's variable lookup precheck requires a non-empty user_id; the\\n        env-fallback variable service does not use it for scoping, so a random UUID is\\n        ceremonial but necessary.\\n        \\\"\\\"\\\"\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            yield MagicMock(results={\\\"text\\\": \\\"ok\\\"})\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n        mock_graph.user_id = None\\n\\n        await execute_graph_with_capture(mock_graph, \\\"test input\\\")\\n\\n        assert mock_graph.user_id, \\\"user_id should be auto-assigned when graph has none\\\"\\n        assert isinstance(mock_graph.user_id, str)\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_preserves_existing_user_id(self):\\n        \\\"\\\"\\\"A user_id already set on the graph (e.g., by an upstream caller) is left alone.\\\"\\\"\\\"\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            yield MagicMock(results={\\\"text\\\": \\\"ok\\\"})\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n        mock_graph.user_id = \\\"preset-user-uuid\\\"\\n\\n        await execute_graph_with_capture(mock_graph, \\\"test input\\\")\\n\\n        assert mock_graph.user_id == \\\"preset-user-uuid\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_passes_fallback_from_settings_default(self):\\n        \\\"\\\"\\\"Default settings (fallback_to_env_var=True) reach async_start.\\n\\n        Lets components fall through to os.environ when a load_from_db variable\\n        has no DB row \u2014 matching langflow's API path behavior.\\n        \\\"\\\"\\\"\\n        captured: dict = {}\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            captured.update(kwargs)\\n            yield MagicMock(results={\\\"text\\\": \\\"ok\\\"})\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n\\n        await execute_graph_with_capture(mock_graph, \\\"test input\\\")\\n\\n        assert captured.get(\\\"fallback_to_env_vars\\\") is True\\n\\n    @pytest.mark.asyncio\\n    async def test_execute_graph_respects_disabled_fallback_setting(self):\\n        \\\"\\\"\\\"When the user opts out of env fallback in settings, the flag is False.\\\"\\\"\\\"\\n        captured: dict = {}\\n\\n        async def mock_async_start(inputs, **kwargs):  # noqa: ARG001\\n            captured.update(kwargs)\\n            yield MagicMock(results={\\\"text\\\": \\\"ok\\\"})\\n\\n        mock_graph = MagicMock()\\n        mock_graph.context = {}\\n        mock_graph.async_start = mock_async_start\\n        mock_settings = MagicMock()\\n        mock_settings.settings.fallback_to_env_var = False\\n\\n        with patch(\\\"lfx.run._defaults.get_settings_service\\\", return_value=mock_settings):\\n            await execute_graph_with_capture(mock_graph, \\\"test input\\\")\\n\\n        assert captured.get(\\\"fallback_to_env_vars\\\") is False\\n\\n\\nclass TestResultExtraction:\\n    \\\"\\\"\\\"Test result data extraction.\\\"\\\"\\\"\\n\\n    def test_extract_result_data_no_results(self):\\n        \\\"\\\"\\\"Test extraction when no results.\\\"\\\"\\\"\\n        result = extract_result_data([], \\\"some logs\\\")\\n\\n        assert result == {\\n            \\\"text\\\": \\\"No response generated\\\",\\n            \\\"success\\\": False,\\n            \\\"type\\\": \\\"error\\\",\\n            \\\"logs\\\": \\\"some logs\\\",\\n        }\\n\\n    def test_extract_result_data_dict_result(self):\\n        \\\"\\\"\\\"Test extraction with proper vertex structure.\\\"\\\"\\\"\\n        # Create mock result with proper vertex structure\\n        mock_message = MagicMock()\\n        mock_message.text = \\\"Hello world\\\"\\n\\n        mock_vertex = MagicMock()\\n        mock_vertex.custom_component.display_name = \\\"Chat Output\\\"\\n        mock_vertex.id = \\\"chat_output_id\\\"\\n\\n        mock_result = MagicMock()\\n        mock_result.vertex = mock_vertex\\n        mock_result.result_dict.results = {\\\"message\\\": mock_message}\\n\\n        results = [mock_result]\\n\\n        result = extract_result_data(results, \\\"logs\\\")\\n\\n        assert result == {\\n            \\\"result\\\": \\\"Hello world\\\",\\n            \\\"type\\\": \\\"message\\\",\\n            \\\"component\\\": \\\"Chat Output\\\",\\n            \\\"component_id\\\": \\\"chat_output_id\\\",\\n            \\\"success\\\": True,\\n            \\\"logs\\\": \\\"logs\\\",\\n        }\\n\\n    def test_extract_result_data_non_dict_result(self):\\n        \\\"\\\"\\\"Test extraction with non-Chat Output component.\\\"\\\"\\\"\\n        # Create mock result with different component type\\n        mock_vertex = MagicMock()\\n        mock_vertex.custom_component.display_name = \\\"Text Output\\\"  # Not \\\"Chat Output\\\"\\n        mock_vertex.id = \\\"text_output_id\\\"\\n\\n        mock_result = MagicMock()\\n        mock_result.vertex = mock_vertex\\n\\n        results = [mock_result]\\n\\n        result = extract_result_data(results, \\\"logs\\\")\\n\\n        # Should fall back to default since it's not Chat Output\\n        assert result == {\\n            \\\"text\\\": \\\"No response generated\\\",\\n            \\\"success\\\": False,\\n            \\\"type\\\": \\\"error\\\",\\n            \\\"logs\\\": \\\"logs\\\",\\n        }\\n\\n    def test_extract_result_data_multiple_results(self):\\n        \\\"\\\"\\\"Test extraction finds Chat Output in multiple results.\\\"\\\"\\\"\\n        # First result - not Chat Output\\n        mock_vertex1 = MagicMock()\\n        mock_vertex1.custom_component.display_name = \\\"Text Input\\\"\\n        mock_result1 = MagicMock()\\n        mock_result1.vertex = mock_vertex1\\n\\n        # Second result - Chat Output\\n        mock_message = MagicMock()\\n        mock_message.text = \\\"Final result\\\"\\n\\n        mock_vertex2 = MagicMock()\\n        mock_vertex2.custom_component.display_name = \\\"Chat Output\\\"\\n        mock_vertex2.id = \\\"final_output_id\\\"\\n\\n        mock_result2 = MagicMock()\\n        mock_result2.vertex = mock_vertex2\\n        mock_result2.result_dict.results = {\\\"message\\\": mock_message}\\n\\n        results = [mock_result1, mock_result2]\\n\\n        result = extract_result_data(results, \\\"logs\\\")\\n\\n        # Should find and use the Chat Output result\\n        assert result == {\\n            \\\"result\\\": \\\"Final result\\\",\\n            \\\"type\\\": \\\"message\\\",\\n            \\\"component\\\": \\\"Chat Output\\\",\\n            \\\"component_id\\\": \\\"final_output_id\\\",\\n            \\\"success\\\": True,\\n            \\\"logs\\\": \\\"logs\\\",\\n        }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_create_command.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a45971679f7db2e95bbcb0e5d16250f5e9792e6a62c0023dcbf4502d0d41eedb\",\"content\":\"\\\"\\\"\\\"Unit tests for ``lfx create`` and the ``--example`` seeding in ``lfx init``.\\n\\nAll tests run entirely in-process; no running Langflow instance required.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import TYPE_CHECKING\\nfrom unittest.mock import patch\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\nimport pytest\\nimport typer\\nfrom lfx.__main__ import app\\nfrom lfx.cli.create import (\\n    _load_template,\\n    _slugify,\\n    create_command,\\n    list_templates,\\n    print_templates,\\n)\\nfrom lfx.cli.init import init_command\\nfrom typer.testing import CliRunner\\n\\nrunner = CliRunner()\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n_REAL_TEMPLATES = list_templates()\\n\\n\\ndef _read_flow(path: Path) -> dict:\\n    return json.loads(path.read_text(encoding=\\\"utf-8\\\"))\\n\\n\\n# ---------------------------------------------------------------------------\\n# list_templates()\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestListTemplates:\\n    def test_returns_list_of_strings(self):\\n        result = list_templates()\\n        assert isinstance(result, list)\\n        assert all(isinstance(t, str) for t in result)\\n\\n    def test_includes_known_templates(self):\\n        result = list_templates()\\n        assert \\\"hello-world\\\" in result\\n\\n    def test_sorted(self):\\n        result = list_templates()\\n        assert result == sorted(result)\\n\\n    def test_returns_empty_when_dir_missing(self, tmp_path):\\n        fake_dir = tmp_path / \\\"nonexistent\\\"\\n        with patch(\\\"lfx.cli.create._FLOWS_TEMPLATE_DIR\\\", fake_dir):\\n            assert list_templates() == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# _slugify()\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestSlugify:\\n    def test_lowercases(self):\\n        assert _slugify(\\\"MyFlow\\\") == \\\"myflow\\\"\\n\\n    def test_spaces_to_hyphens(self):\\n        assert _slugify(\\\"My Flow Name\\\") == \\\"my-flow-name\\\"\\n\\n    def test_underscores_to_hyphens(self):\\n        assert _slugify(\\\"my_flow\\\") == \\\"my-flow\\\"\\n\\n    def test_already_slug(self):\\n        assert _slugify(\\\"my-flow\\\") == \\\"my-flow\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# _load_template()\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLoadTemplate:\\n    def test_loads_hello_world(self):\\n        flow = _load_template(\\\"hello-world\\\")\\n        assert \\\"id\\\" in flow\\n        assert \\\"name\\\" in flow\\n        assert \\\"data\\\" in flow\\n\\n    def test_raises_on_unknown_template(self):\\n        with pytest.raises(FileNotFoundError, match=\\\"not found\\\"):\\n            _load_template(\\\"does-not-exist\\\")\\n\\n    def test_error_lists_available_templates(self):\\n        with pytest.raises(FileNotFoundError, match=\\\"hello-world\\\"):\\n            _load_template(\\\"does-not-exist\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Template JSON structure (level-1 validity)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestTemplateStructure:\\n    \\\"\\\"\\\"Every bundled template must satisfy level-1 structural validation.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\\"template_name\\\", _REAL_TEMPLATES)\\n    def test_has_required_top_level_keys(self, template_name):\\n        flow = _load_template(template_name)\\n        for key in (\\\"id\\\", \\\"name\\\", \\\"data\\\"):\\n            assert key in flow, f\\\"Template {template_name!r} missing top-level key '{key}'\\\"\\n\\n    @pytest.mark.parametrize(\\\"template_name\\\", _REAL_TEMPLATES)\\n    def test_has_nodes_and_edges(self, template_name):\\n        flow = _load_template(template_name)\\n        assert \\\"nodes\\\" in flow[\\\"data\\\"]\\n        assert \\\"edges\\\" in flow[\\\"data\\\"]\\n\\n    @pytest.mark.parametrize(\\\"template_name\\\", _REAL_TEMPLATES)\\n    def test_every_node_has_id_and_data(self, template_name):\\n        flow = _load_template(template_name)\\n        for node in flow[\\\"data\\\"][\\\"nodes\\\"]:\\n            assert \\\"id\\\" in node, f\\\"Node missing 'id' in template {template_name!r}\\\"\\n            assert \\\"data\\\" in node, f\\\"Node missing 'data' in template {template_name!r}\\\"\\n\\n    @pytest.mark.parametrize(\\\"template_name\\\", _REAL_TEMPLATES)\\n    def test_every_node_has_type(self, template_name):\\n        \\\"\\\"\\\"Nodes should declare data.type to avoid validate warnings.\\\"\\\"\\\"\\n        flow = _load_template(template_name)\\n        for node in flow[\\\"data\\\"][\\\"nodes\\\"]:\\n            assert \\\"type\\\" in node[\\\"data\\\"], f\\\"Node {node['id']!r} in template {template_name!r} missing 'data.type'\\\"\\n\\n    @pytest.mark.parametrize(\\\"template_name\\\", _REAL_TEMPLATES)\\n    def test_edges_reference_existing_nodes(self, template_name):\\n        flow = _load_template(template_name)\\n        node_ids = {n[\\\"id\\\"] for n in flow[\\\"data\\\"][\\\"nodes\\\"]}\\n        for edge in flow[\\\"data\\\"][\\\"edges\\\"]:\\n            assert edge[\\\"source\\\"] in node_ids, f\\\"Edge source {edge['source']!r} not in nodes for {template_name!r}\\\"\\n            assert edge[\\\"target\\\"] in node_ids, f\\\"Edge target {edge['target']!r} not in nodes for {template_name!r}\\\"\\n\\n    def test_hello_world_has_input_and_output(self):\\n        flow = _load_template(\\\"hello-world\\\")\\n        types = {n[\\\"data\\\"][\\\"type\\\"] for n in flow[\\\"data\\\"][\\\"nodes\\\"]}\\n        assert \\\"ChatOutput\\\" in types\\n        assert len(types) >= 2\\n\\n    def test_hello_world_edge_connects_input_to_output(self):\\n        flow = _load_template(\\\"hello-world\\\")\\n        node_ids = {n[\\\"id\\\"] for n in flow[\\\"data\\\"][\\\"nodes\\\"]}\\n        for edge in flow[\\\"data\\\"][\\\"edges\\\"]:\\n            assert edge[\\\"source\\\"] in node_ids\\n            assert edge[\\\"target\\\"] in node_ids\\n\\n\\n# ---------------------------------------------------------------------------\\n# create_command() \u2014 core logic\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestCreateCommand:\\n    def test_creates_file_with_correct_name(self, tmp_path):\\n        dest = create_command(\\\"my-flow\\\", output_dir=tmp_path)\\n        assert dest == tmp_path / \\\"my-flow.json\\\"\\n        assert dest.exists()\\n\\n    def test_slugifies_name_for_filename(self, tmp_path):\\n        dest = create_command(\\\"My Cool Flow\\\", output_dir=tmp_path)\\n        assert dest.name == \\\"my-cool-flow.json\\\"\\n\\n    def test_flow_name_in_json_is_original(self, tmp_path):\\n        create_command(\\\"My Cool Flow\\\", output_dir=tmp_path)\\n        flow = _read_flow(tmp_path / \\\"my-cool-flow.json\\\")\\n        assert flow[\\\"name\\\"] == \\\"My Cool Flow\\\"\\n\\n    def test_generates_unique_uuid(self, tmp_path):\\n        dest1 = create_command(\\\"flow-a\\\", output_dir=tmp_path)\\n        dest2 = create_command(\\\"flow-b\\\", output_dir=tmp_path)\\n        id1 = _read_flow(dest1)[\\\"id\\\"]\\n        id2 = _read_flow(dest2)[\\\"id\\\"]\\n        assert id1 != id2\\n        # Must not be the placeholder\\n        assert id1 != \\\"00000000-0000-0000-0000-000000000000\\\"\\n        assert id2 != \\\"00000000-0000-0000-0000-000000000000\\\"\\n\\n    def test_uses_default_template_hello_world(self, tmp_path):\\n        dest = create_command(\\\"test\\\", output_dir=tmp_path)\\n        flow = _read_flow(dest)\\n        types = {n[\\\"data\\\"][\\\"type\\\"] for n in flow[\\\"data\\\"][\\\"nodes\\\"]}\\n        assert \\\"ChatOutput\\\" in types\\n\\n    def test_creates_output_dir_if_missing(self, tmp_path):\\n        nested = tmp_path / \\\"a\\\" / \\\"b\\\" / \\\"flows\\\"\\n        dest = create_command(\\\"my-flow\\\", output_dir=nested)\\n        assert dest.exists()\\n\\n    def test_raises_exit1_on_unknown_template(self, tmp_path):\\n        with pytest.raises(typer.Exit):\\n            create_command(\\\"test\\\", template=\\\"nonexistent\\\", output_dir=tmp_path)\\n\\n    def test_raises_exit1_if_file_exists_no_overwrite(self, tmp_path):\\n        create_command(\\\"my-flow\\\", output_dir=tmp_path)\\n        with pytest.raises(typer.Exit):\\n            create_command(\\\"my-flow\\\", output_dir=tmp_path, overwrite=False)\\n\\n    def test_overwrites_existing_file_when_flag_set(self, tmp_path):\\n        dest = create_command(\\\"my-flow\\\", output_dir=tmp_path)\\n        original_id = _read_flow(dest)[\\\"id\\\"]\\n        dest2 = create_command(\\\"my-flow\\\", output_dir=tmp_path, overwrite=True)\\n        new_id = _read_flow(dest2)[\\\"id\\\"]\\n        assert dest == dest2\\n        assert new_id != original_id  # new UUID stamped each time\\n\\n    def test_output_is_valid_json(self, tmp_path):\\n        dest = create_command(\\\"my-flow\\\", output_dir=tmp_path)\\n        # Should not raise\\n        flow = json.loads(dest.read_text(encoding=\\\"utf-8\\\"))\\n        assert isinstance(flow, dict)\\n\\n    def test_raises_exit1_when_no_templates_dir(self, tmp_path):\\n        fake_dir = tmp_path / \\\"empty\\\"\\n        with patch(\\\"lfx.cli.create._FLOWS_TEMPLATE_DIR\\\", fake_dir), pytest.raises(typer.Exit):\\n            create_command(\\\"test\\\", output_dir=tmp_path)\\n\\n\\n# ---------------------------------------------------------------------------\\n# print_templates() \u2014 smoke test\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestPrintTemplates:\\n    def test_does_not_raise(self):\\n        print_templates()  # just checking it doesn't blow up\\n\\n    def test_prints_nothing_when_no_templates(self, tmp_path):\\n        with patch(\\\"lfx.cli.create._FLOWS_TEMPLATE_DIR\\\", tmp_path / \\\"empty\\\"):\\n            print_templates()\\n\\n\\n# ---------------------------------------------------------------------------\\n# CLI integration \u2014 lfx create\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestCreateCLI:\\n    def test_creates_flow_via_cli(self, tmp_path):\\n        result = runner.invoke(\\n            app,\\n            [\\\"create\\\", \\\"hello\\\", \\\"--output-dir\\\", str(tmp_path)],\\n        )\\n        assert result.exit_code == 0, result.output\\n        assert (tmp_path / \\\"hello.json\\\").exists()\\n\\n    def test_list_flag_prints_templates_and_exits(self):\\n        result = runner.invoke(app, [\\\"create\\\", \\\"--list\\\", \\\"ignored-name\\\"])\\n        assert result.exit_code == 0\\n        assert \\\"hello-world\\\" in result.output\\n\\n    def test_unknown_template_exits_nonzero(self, tmp_path):\\n        result = runner.invoke(\\n            app,\\n            [\\\"create\\\", \\\"test\\\", \\\"--template\\\", \\\"no-such-template\\\", \\\"--output-dir\\\", str(tmp_path)],\\n        )\\n        assert result.exit_code != 0\\n\\n    def test_overwrite_flag_replaces_file(self, tmp_path):\\n        runner.invoke(app, [\\\"create\\\", \\\"my-flow\\\", \\\"--output-dir\\\", str(tmp_path)])\\n        result = runner.invoke(\\n            app,\\n            [\\\"create\\\", \\\"my-flow\\\", \\\"--output-dir\\\", str(tmp_path), \\\"--overwrite\\\"],\\n        )\\n        assert result.exit_code == 0, result.output\\n\\n    def test_no_overwrite_exits_nonzero_on_existing(self, tmp_path):\\n        runner.invoke(app, [\\\"create\\\", \\\"my-flow\\\", \\\"--output-dir\\\", str(tmp_path)])\\n        result = runner.invoke(app, [\\\"create\\\", \\\"my-flow\\\", \\\"--output-dir\\\", str(tmp_path)])\\n        assert result.exit_code != 0\\n\\n    def test_explicit_template_hello_world(self, tmp_path):\\n        result = runner.invoke(\\n            app,\\n            [\\\"create\\\", \\\"my-flow\\\", \\\"--template\\\", \\\"hello-world\\\", \\\"--output-dir\\\", str(tmp_path)],\\n        )\\n        assert result.exit_code == 0, result.output\\n        flow = _read_flow(tmp_path / \\\"my-flow.json\\\")\\n        types = {n[\\\"data\\\"][\\\"type\\\"] for n in flow[\\\"data\\\"][\\\"nodes\\\"]}\\n        assert \\\"ChatOutput\\\" in types\\n\\n\\n# ---------------------------------------------------------------------------\\n# init_command \u2014 --example seeding\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInitExampleSeeding:\\n    def test_seeds_hello_world_by_default(self, tmp_path):\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=True)\\n        assert (tmp_path / \\\"flows\\\" / \\\"hello-world.json\\\").exists()\\n\\n    def test_seeded_flow_is_valid_json(self, tmp_path):\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=True)\\n        flow = _read_flow(tmp_path / \\\"flows\\\" / \\\"hello-world.json\\\")\\n        assert \\\"id\\\" in flow\\n        assert \\\"name\\\" in flow\\n        assert flow[\\\"name\\\"] == \\\"hello-world\\\"\\n\\n    def test_no_example_does_not_create_hello_world(self, tmp_path):\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=False)\\n        assert not (tmp_path / \\\"flows\\\" / \\\"hello-world.json\\\").exists()\\n\\n    def test_no_example_creates_gitkeep(self, tmp_path):\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=False)\\n        assert (tmp_path / \\\"flows\\\" / \\\".gitkeep\\\").exists()\\n\\n    def test_example_still_creates_other_files(self, tmp_path):\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=True)\\n        assert (tmp_path / \\\".lfx\\\" / \\\"environments.yaml\\\").exists()\\n        assert (tmp_path / \\\"tests\\\" / \\\"test_flows.py\\\").exists()\\n\\n    def test_seeded_flow_has_unique_uuid(self, tmp_path):\\n        p1 = tmp_path / \\\"proj1\\\"\\n        p2 = tmp_path / \\\"proj2\\\"\\n        init_command(project_dir=p1, github_actions=False, overwrite=False, example=True)\\n        init_command(project_dir=p2, github_actions=False, overwrite=False, example=True)\\n        id1 = _read_flow(p1 / \\\"flows\\\" / \\\"hello-world.json\\\")[\\\"id\\\"]\\n        id2 = _read_flow(p2 / \\\"flows\\\" / \\\"hello-world.json\\\")[\\\"id\\\"]\\n        assert id1 != id2\\n\\n    def test_init_cli_example_flag(self, tmp_path):\\n        result = runner.invoke(\\n            app,\\n            [\\\"init\\\", str(tmp_path), \\\"--no-github-actions\\\", \\\"--example\\\"],\\n        )\\n        assert result.exit_code == 0, result.output\\n        assert (tmp_path / \\\"flows\\\" / \\\"hello-world.json\\\").exists()\\n\\n    def test_init_cli_no_example_flag(self, tmp_path):\\n        result = runner.invoke(\\n            app,\\n            [\\\"init\\\", str(tmp_path), \\\"--no-github-actions\\\", \\\"--no-example\\\"],\\n        )\\n        assert result.exit_code == 0, result.output\\n        assert not (tmp_path / \\\"flows\\\" / \\\"hello-world.json\\\").exists()\\n\\n    def test_graceful_fallback_when_template_fails(self, tmp_path):\\n        \\\"\\\"\\\"If the template dir is missing, init should warn but not crash.\\\"\\\"\\\"\\n        fake_dir = tmp_path / \\\"no-templates\\\"\\n        with patch(\\\"lfx.cli.create._FLOWS_TEMPLATE_DIR\\\", fake_dir):\\n            # Should not raise \u2014 the BLE001-guarded except swallows it\\n            init_command(\\n                project_dir=tmp_path / \\\"proj\\\",\\n                github_actions=False,\\n                overwrite=False,\\n                example=True,\\n            )\\n        assert (tmp_path / \\\"proj\\\" / \\\".lfx\\\" / \\\"environments.yaml\\\").exists()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_export_command.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e37b8f18e87850018beee930ffe5bbc5263308f0223abd113a883310096b7f79\",\"content\":\"\\\"\\\"\\\"Unit tests for lfx export -- export_command and helpers.\\n\\nAll tests run entirely in-process; no real Langflow instance or SDK required.\\nThe SDK module is replaced wholesale with MagicMock so only the export logic\\n(file normalization, output routing, remote pull, project export) is under test.\\n\\\"\\\"\\\"\\n# pragma: allowlist secret -- all credentials in this file are fake test data\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport sys\\nfrom io import StringIO\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nimport typer\\n\\n# ---------------------------------------------------------------------------\\n# Shared constants\\n# ---------------------------------------------------------------------------\\n\\n_BASE_URL = \\\"http://langflow.test\\\"\\n_API_KEY = \\\"test-api-key-export\\\"  # pragma: allowlist secret\\n_FLOW_ID = \\\"aaaaaaaa-0000-0000-0000-000000000001\\\"\\n_PROJECT_ID = \\\"bbbbbbbb-0000-0000-0000-000000000001\\\"\\n\\n_FLOW_DICT: dict = {\\n    \\\"id\\\": _FLOW_ID,\\n    \\\"name\\\": \\\"My Test Flow\\\",\\n    \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n}\\n\\n_NORMALIZED_JSON = json.dumps(_FLOW_DICT, indent=2)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Fake SDK helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _make_flow_obj(name: str = \\\"My Test Flow\\\", flow_id: str = _FLOW_ID) -> MagicMock:\\n    \\\"\\\"\\\"Return a mock flow object with .name, .model_dump().\\\"\\\"\\\"\\n    obj = MagicMock()\\n    obj.name = name\\n    obj.id = flow_id\\n    obj.model_dump.return_value = {\\\"id\\\": flow_id, \\\"name\\\": name, \\\"data\\\": {}}\\n    return obj\\n\\n\\ndef _make_project_obj(\\n    name: str = \\\"My Project\\\",\\n    project_id: str = _PROJECT_ID,\\n    flows: list | None = None,\\n) -> MagicMock:\\n    obj = MagicMock()\\n    obj.name = name\\n    obj.id = project_id\\n    obj.flows = flows if flows is not None else [_make_flow_obj()]\\n    return obj\\n\\n\\ndef _make_client_mock(\\n    flow_obj: MagicMock | None = None,\\n    project_obj: MagicMock | None = None,\\n) -> MagicMock:\\n    client = MagicMock()\\n    client.get_flow.return_value = flow_obj if flow_obj is not None else _make_flow_obj()\\n    client.get_project.return_value = project_obj if project_obj is not None else _make_project_obj()\\n    return client\\n\\n\\ndef _make_sdk_mock(client_mock: MagicMock | None = None) -> MagicMock:\\n    \\\"\\\"\\\"Return a mock langflow_sdk module wired up for export tests.\\\"\\\"\\\"\\n    if client_mock is None:\\n        client_mock = _make_client_mock()\\n    sdk = MagicMock()\\n    sdk.Client.return_value = client_mock\\n    sdk.normalize_flow_file.return_value = _FLOW_DICT\\n    sdk.normalize_flow.return_value = _FLOW_DICT\\n    sdk.flow_to_json.return_value = _NORMALIZED_JSON\\n    return sdk\\n\\n\\ndef _make_env_cfg(url: str = _BASE_URL, api_key: str | None = _API_KEY) -> MagicMock:\\n    env_cfg = MagicMock()\\n    env_cfg.url = url\\n    env_cfg.api_key = api_key\\n    return env_cfg\\n\\n\\ndef _run_export(\\n    flow_paths: list[str],\\n    *,\\n    output: str | None = None,\\n    output_dir: str | None = None,\\n    env: str | None = None,\\n    flow_id: str | None = None,\\n    project_id: str | None = None,\\n    environments_file: str | None = None,\\n    target: str | None = _BASE_URL,\\n    api_key: str | None = _API_KEY,\\n    in_place: bool = False,\\n    strip_volatile: bool = False,\\n    strip_secrets: bool = False,\\n    code_as_lines: bool = False,\\n    strip_node_volatile: bool = False,\\n    indent: int = 2,\\n    sdk_mock: MagicMock | None = None,\\n    env_cfg: MagicMock | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Invoke export_command with a mocked SDK and optional mocked env.\\\"\\\"\\\"\\n    from lfx.cli.export import export_command\\n\\n    mock = sdk_mock if sdk_mock is not None else _make_sdk_mock()\\n    resolved_env = env_cfg if env_cfg is not None else _make_env_cfg()\\n\\n    with (\\n        patch(\\\"lfx.cli.export.load_sdk\\\", return_value=mock),\\n        patch(\\\"lfx.config.resolve_environment\\\", return_value=resolved_env),\\n    ):\\n        export_command(\\n            flow_paths=flow_paths,\\n            output=output,\\n            output_dir=output_dir,\\n            env=env,\\n            flow_id=flow_id,\\n            project_id=project_id,\\n            environments_file=environments_file,\\n            target=target,\\n            api_key=api_key,\\n            in_place=in_place,\\n            strip_volatile=strip_volatile,\\n            strip_secrets=strip_secrets,\\n            code_as_lines=code_as_lines,\\n            strip_node_volatile=strip_node_volatile,\\n            indent=indent,\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# _safe_filename\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestSafeFilename:\\n    def test_alphanumeric_unchanged(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        assert _safe_filename(\\\"MyFlow123\\\") == \\\"MyFlow123\\\"\\n\\n    def test_spaces_replaced_with_underscores(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        assert _safe_filename(\\\"My Test Flow\\\") == \\\"My_Test_Flow\\\"\\n\\n    def test_special_chars_replaced_with_underscores(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        result = _safe_filename(\\\"flow/name:with*special?chars\\\")\\n        assert \\\"/\\\" not in result\\n        assert \\\":\\\" not in result\\n        assert \\\"*\\\" not in result\\n        assert \\\"?\\\" not in result\\n\\n    def test_leading_trailing_spaces_stripped(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        result = _safe_filename(\\\"  flow name  \\\")\\n        assert not result.startswith(\\\"_\\\")\\n        assert not result.endswith(\\\"_\\\")\\n        assert \\\"flow_name\\\" in result\\n\\n    def test_hyphens_and_underscores_preserved(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        result = _safe_filename(\\\"my-flow_name\\\")\\n        assert result == \\\"my-flow_name\\\"\\n\\n    def test_empty_string(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        result = _safe_filename(\\\"\\\")\\n        assert result == \\\"\\\"\\n\\n    def test_unicode_chars_replaced(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        result = _safe_filename(\\\"flow\\\\u2019s name\\\")\\n        assert \\\"\\\\u2019\\\" not in result\\n\\n    def test_all_spaces_produces_underscores(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        result = _safe_filename(\\\"a b c\\\")\\n        assert result == \\\"a_b_c\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# _write_flow\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestWriteFlow:\\n    def test_in_place_writes_to_source_path(self, tmp_path):\\n        from lfx.cli.export import _write_flow\\n\\n        src = tmp_path / \\\"flow.json\\\"\\n        src.write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        sdk = _make_sdk_mock()\\n        result = _write_flow(_FLOW_DICT, sdk=sdk, output=None, in_place=True, source_path=src, indent=2)\\n        assert result == src\\n        assert src.read_text(encoding=\\\"utf-8\\\") == _NORMALIZED_JSON\\n\\n    def test_in_place_returns_source_path(self, tmp_path):\\n        from lfx.cli.export import _write_flow\\n\\n        src = tmp_path / \\\"flow.json\\\"\\n        src.write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        sdk = _make_sdk_mock()\\n        result = _write_flow(_FLOW_DICT, sdk=sdk, output=None, in_place=True, source_path=src, indent=2)\\n        assert result == src\\n\\n    def test_output_given_writes_to_output(self, tmp_path):\\n        from lfx.cli.export import _write_flow\\n\\n        out = tmp_path / \\\"out.json\\\"\\n        sdk = _make_sdk_mock()\\n        result = _write_flow(_FLOW_DICT, sdk=sdk, output=out, in_place=False, source_path=None, indent=2)\\n        assert result == out\\n        assert out.read_text(encoding=\\\"utf-8\\\") == _NORMALIZED_JSON\\n\\n    def test_output_given_returns_output_path(self, tmp_path):\\n        from lfx.cli.export import _write_flow\\n\\n        out = tmp_path / \\\"result.json\\\"\\n        sdk = _make_sdk_mock()\\n        result = _write_flow(_FLOW_DICT, sdk=sdk, output=out, in_place=False, source_path=None, indent=2)\\n        assert result == out\\n\\n    def test_no_output_no_in_place_writes_to_stdout(self):\\n        from lfx.cli.export import _write_flow\\n\\n        sdk = _make_sdk_mock()\\n        captured = StringIO()\\n        with patch.object(sys, \\\"stdout\\\", captured):\\n            _write_flow(_FLOW_DICT, sdk=sdk, output=None, in_place=False, source_path=None, indent=2)\\n        assert _NORMALIZED_JSON in captured.getvalue()\\n\\n    def test_no_output_no_in_place_returns_none(self):\\n        from lfx.cli.export import _write_flow\\n\\n        sdk = _make_sdk_mock()\\n        captured = StringIO()\\n        with patch.object(sys, \\\"stdout\\\", captured):\\n            result = _write_flow(_FLOW_DICT, sdk=sdk, output=None, in_place=False, source_path=None, indent=2)\\n        assert result is None\\n\\n    def test_in_place_false_with_source_path_uses_output(self, tmp_path):\\n        from lfx.cli.export import _write_flow\\n\\n        src = tmp_path / \\\"src.json\\\"\\n        src.write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        out = tmp_path / \\\"dest.json\\\"\\n        sdk = _make_sdk_mock()\\n        result = _write_flow(_FLOW_DICT, sdk=sdk, output=out, in_place=False, source_path=src, indent=2)\\n        assert result == out\\n        assert out.exists()\\n\\n    def test_sdk_flow_to_json_called_with_indent(self, tmp_path):\\n        from lfx.cli.export import _write_flow\\n\\n        out = tmp_path / \\\"out.json\\\"\\n        sdk = _make_sdk_mock()\\n        _write_flow(_FLOW_DICT, sdk=sdk, output=out, in_place=False, source_path=None, indent=4)\\n        sdk.flow_to_json.assert_called_once_with(_FLOW_DICT, indent=4)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Local mode\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestExportCommandLocalMode:\\n    def test_single_file_to_stdout(self, tmp_path):\\n        src = tmp_path / \\\"flow.json\\\"\\n        src.write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n        sdk = _make_sdk_mock()\\n        captured = StringIO()\\n        with patch.object(sys, \\\"stdout\\\", captured):\\n            _run_export([str(src)], sdk_mock=sdk)\\n        sdk.normalize_flow_file.assert_called_once()\\n\\n    def test_single_file_with_output_writes_file(self, tmp_path):\\n        src = tmp_path / \\\"flow.json\\\"\\n        src.write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n        out = tmp_path / \\\"exported.json\\\"\\n        sdk = _make_sdk_mock()\\n        _run_export([str(src)], output=str(out), sdk_mock=sdk)\\n        assert out.exists()\\n        assert out.read_text(encoding=\\\"utf-8\\\") == _NORMALIZED_JSON\\n\\n    def test_single_file_in_place_overwrites_source(self, tmp_path):\\n        src = tmp_path / \\\"flow.json\\\"\\n        src.write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n        sdk = _make_sdk_mock()\\n        _run_export([str(src)], in_place=True, sdk_mock=sdk)\\n        assert src.read_text(encoding=\\\"utf-8\\\") == _NORMALIZED_JSON\\n\\n    def test_multiple_files_processed(self, tmp_path):\\n        f1 = tmp_path / \\\"a.json\\\"\\n        f2 = tmp_path / \\\"b.json\\\"\\n        f1.write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n        f2.write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n        sdk = _make_sdk_mock()\\n        captured = StringIO()\\n        with patch.object(sys, \\\"stdout\\\", captured):\\n            _run_export([str(f1), str(f2)], sdk_mock=sdk)\\n        assert sdk.normalize_flow_file.call_count == 2\\n\\n    def test_multiple_files_with_output_raises_exit_1(self, tmp_path):\\n        f1 = tmp_path / \\\"a.json\\\"\\n        f2 = tmp_path / \\\"b.json\\\"\\n        f1.write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n        f2.write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n        out = tmp_path / \\\"out.json\\\"\\n        sdk = _make_sdk_mock()\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_export([str(f1), str(f2)], output=str(out), sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_file_not_found_raises_exit_1(self, tmp_path):\\n        sdk = _make_sdk_mock()\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_export([str(tmp_path / \\\"missing.json\\\")], sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_normalize_raises_exits_1(self, tmp_path):\\n        src = tmp_path / \\\"flow.json\\\"\\n        src.write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n        sdk = _make_sdk_mock()\\n        sdk.normalize_flow_file.side_effect = ValueError(\\\"bad flow\\\")\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_export([str(src)], sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_no_flow_paths_raises_exit_1(self):\\n        sdk = _make_sdk_mock()\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_export([], sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_normalize_kwargs_passed_correctly(self, tmp_path):\\n        src = tmp_path / \\\"flow.json\\\"\\n        src.write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n        sdk = _make_sdk_mock()\\n        captured = StringIO()\\n        with patch.object(sys, \\\"stdout\\\", captured):\\n            _run_export(\\n                [str(src)],\\n                strip_volatile=True,\\n                strip_secrets=True,\\n                code_as_lines=True,\\n                strip_node_volatile=True,\\n                sdk_mock=sdk,\\n            )\\n        call_kwargs = sdk.normalize_flow_file.call_args.kwargs\\n        assert call_kwargs[\\\"strip_volatile\\\"] is True\\n        assert call_kwargs[\\\"strip_secrets\\\"] is True\\n        assert call_kwargs[\\\"code_as_lines\\\"] is True\\n        assert call_kwargs[\\\"strip_node_volatile\\\"] is True\\n\\n    def test_indent_passed_to_flow_to_json(self, tmp_path):\\n        src = tmp_path / \\\"flow.json\\\"\\n        src.write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n        out = tmp_path / \\\"out.json\\\"\\n        sdk = _make_sdk_mock()\\n        _run_export([str(src)], output=str(out), indent=4, sdk_mock=sdk)\\n        sdk.flow_to_json.assert_called_with(sdk.normalize_flow_file.return_value, indent=4)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Remote mode \u2014 single flow by ID\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestExportCommandRemoteFlowId:\\n    def test_missing_env_and_target_raises_exit_1(self):\\n        sdk = _make_sdk_mock()\\n        from lfx.cli.export import export_command\\n\\n        with patch(\\\"lfx.cli.export.load_sdk\\\", return_value=sdk), pytest.raises(typer.Exit) as exc_info:\\n            export_command(\\n                flow_paths=[],\\n                output=None,\\n                output_dir=None,\\n                env=None,\\n                flow_id=_FLOW_ID,\\n                project_id=None,\\n                environments_file=None,\\n                target=None,\\n                api_key=None,\\n                in_place=False,\\n                strip_volatile=False,\\n                strip_secrets=False,\\n                code_as_lines=False,\\n                strip_node_volatile=False,\\n                indent=2,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_flow_id_fetches_and_writes_to_output_dir(self, tmp_path):\\n        flow_obj = _make_flow_obj(name=\\\"Fetched Flow\\\")\\n        client = _make_client_mock(flow_obj=flow_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_export(\\n            [],\\n            flow_id=_FLOW_ID,\\n            env=\\\"staging\\\",\\n            output_dir=str(tmp_path),\\n            sdk_mock=sdk,\\n            env_cfg=env_cfg,\\n        )\\n        client.get_flow.assert_called_once()\\n        written = list(tmp_path.glob(\\\"*.json\\\"))\\n        assert len(written) == 1\\n\\n    def test_flow_id_filename_uses_safe_name(self, tmp_path):\\n        flow_obj = _make_flow_obj(name=\\\"My Flow: Special!\\\")\\n        client = _make_client_mock(flow_obj=flow_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_export(\\n            [],\\n            flow_id=_FLOW_ID,\\n            env=\\\"staging\\\",\\n            output_dir=str(tmp_path),\\n            sdk_mock=sdk,\\n            env_cfg=env_cfg,\\n        )\\n        written = list(tmp_path.glob(\\\"*.json\\\"))\\n        assert len(written) == 1\\n        assert \\\":\\\" not in written[0].name\\n        assert \\\"!\\\" not in written[0].name\\n\\n    def test_flow_id_creates_output_dir_if_missing(self, tmp_path):\\n        dest = tmp_path / \\\"new_dir\\\" / \\\"subdir\\\"\\n        flow_obj = _make_flow_obj()\\n        client = _make_client_mock(flow_obj=flow_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_export(\\n            [],\\n            flow_id=_FLOW_ID,\\n            env=\\\"staging\\\",\\n            output_dir=str(dest),\\n            sdk_mock=sdk,\\n            env_cfg=env_cfg,\\n        )\\n        assert dest.exists()\\n\\n    def test_flow_id_uses_cwd_when_output_dir_not_specified(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        flow_obj = _make_flow_obj(name=\\\"CwdFlow\\\")\\n        client = _make_client_mock(flow_obj=flow_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_export(\\n            [],\\n            flow_id=_FLOW_ID,\\n            env=\\\"staging\\\",\\n            output_dir=None,\\n            sdk_mock=sdk,\\n            env_cfg=env_cfg,\\n        )\\n        written = list(tmp_path.glob(\\\"*.json\\\"))\\n        assert len(written) == 1\\n\\n    def test_config_error_raises_exit_1(self, tmp_path):\\n        from lfx.cli.export import export_command\\n        from lfx.config import ConfigError\\n\\n        sdk = _make_sdk_mock()\\n        with (\\n            patch(\\\"lfx.cli.export.load_sdk\\\", return_value=sdk),\\n            patch(\\\"lfx.config.resolve_environment\\\", side_effect=ConfigError(\\\"bad config\\\")),\\n            pytest.raises(typer.Exit) as exc_info,\\n        ):\\n            export_command(\\n                flow_paths=[],\\n                output=None,\\n                output_dir=str(tmp_path),\\n                env=\\\"staging\\\",\\n                flow_id=_FLOW_ID,\\n                project_id=None,\\n                environments_file=None,\\n                target=None,\\n                api_key=None,\\n                in_place=False,\\n                strip_volatile=False,\\n                strip_secrets=False,\\n                code_as_lines=False,\\n                strip_node_volatile=False,\\n                indent=2,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_client_constructed_with_env_credentials(self, tmp_path):\\n        flow_obj = _make_flow_obj()\\n        client = _make_client_mock(flow_obj=flow_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg(url=_BASE_URL, api_key=_API_KEY)\\n        _run_export(\\n            [],\\n            flow_id=_FLOW_ID,\\n            env=\\\"staging\\\",\\n            output_dir=str(tmp_path),\\n            sdk_mock=sdk,\\n            env_cfg=env_cfg,\\n        )\\n        sdk.Client.assert_called_once_with(base_url=_BASE_URL, api_key=_API_KEY)\\n\\n    def test_normalize_flow_called_with_kwargs(self, tmp_path):\\n        flow_obj = _make_flow_obj()\\n        client = _make_client_mock(flow_obj=flow_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_export(\\n            [],\\n            flow_id=_FLOW_ID,\\n            env=\\\"staging\\\",\\n            output_dir=str(tmp_path),\\n            strip_volatile=True,\\n            strip_secrets=True,\\n            sdk_mock=sdk,\\n            env_cfg=env_cfg,\\n        )\\n        call_kwargs = sdk.normalize_flow.call_args.kwargs\\n        assert call_kwargs[\\\"strip_volatile\\\"] is True\\n        assert call_kwargs[\\\"strip_secrets\\\"] is True\\n\\n\\n# ---------------------------------------------------------------------------\\n# Remote mode \u2014 project\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestExportCommandRemoteProject:\\n    def test_project_exports_all_flows(self, tmp_path):\\n        flows = [_make_flow_obj(name=f\\\"Flow {i}\\\", flow_id=f\\\"aaaaaaaa-0000-0000-0000-{i:012d}\\\") for i in range(3)]\\n        project_obj = _make_project_obj(name=\\\"Test Project\\\", flows=flows)\\n        client = _make_client_mock(project_obj=project_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_export(\\n            [],\\n            project_id=_PROJECT_ID,\\n            env=\\\"staging\\\",\\n            output_dir=str(tmp_path),\\n            sdk_mock=sdk,\\n            env_cfg=env_cfg,\\n        )\\n        client.get_project.assert_called_once()\\n        written = list(tmp_path.glob(\\\"*.json\\\"))\\n        assert len(written) == 3\\n\\n    def test_project_creates_dir_named_after_project_when_output_dir_not_given(self, tmp_path, monkeypatch):\\n        monkeypatch.chdir(tmp_path)\\n        project_obj = _make_project_obj(name=\\\"My Project\\\")\\n        client = _make_client_mock(project_obj=project_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_export(\\n            [],\\n            project_id=_PROJECT_ID,\\n            env=\\\"staging\\\",\\n            output_dir=None,\\n            sdk_mock=sdk,\\n            env_cfg=env_cfg,\\n        )\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        expected_dir = tmp_path / _safe_filename(\\\"My Project\\\")\\n        assert expected_dir.exists()\\n\\n    def test_project_writes_json_for_each_flow(self, tmp_path):\\n        flows = [_make_flow_obj(name=\\\"Alpha\\\"), _make_flow_obj(name=\\\"Beta\\\")]\\n        project_obj = _make_project_obj(flows=flows)\\n        client = _make_client_mock(project_obj=project_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_export(\\n            [],\\n            project_id=_PROJECT_ID,\\n            env=\\\"staging\\\",\\n            output_dir=str(tmp_path),\\n            sdk_mock=sdk,\\n            env_cfg=env_cfg,\\n        )\\n        assert sdk.normalize_flow.call_count == 2\\n        assert sdk.flow_to_json.call_count == 2\\n\\n    def test_project_config_error_raises_exit_1(self, tmp_path):\\n        from lfx.cli.export import export_command\\n        from lfx.config import ConfigError\\n\\n        sdk = _make_sdk_mock()\\n        with (\\n            patch(\\\"lfx.cli.export.load_sdk\\\", return_value=sdk),\\n            patch(\\\"lfx.config.resolve_environment\\\", side_effect=ConfigError(\\\"cfg error\\\")),\\n            pytest.raises(typer.Exit) as exc_info,\\n        ):\\n            export_command(\\n                flow_paths=[],\\n                output=None,\\n                output_dir=str(tmp_path),\\n                env=\\\"staging\\\",\\n                flow_id=None,\\n                project_id=_PROJECT_ID,\\n                environments_file=None,\\n                target=None,\\n                api_key=None,\\n                in_place=False,\\n                strip_volatile=False,\\n                strip_secrets=False,\\n                code_as_lines=False,\\n                strip_node_volatile=False,\\n                indent=2,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_project_missing_env_and_target_raises_exit_1(self):\\n        from lfx.cli.export import export_command\\n\\n        sdk = _make_sdk_mock()\\n        with patch(\\\"lfx.cli.export.load_sdk\\\", return_value=sdk), pytest.raises(typer.Exit) as exc_info:\\n            export_command(\\n                flow_paths=[],\\n                output=None,\\n                output_dir=None,\\n                env=None,\\n                flow_id=None,\\n                project_id=_PROJECT_ID,\\n                environments_file=None,\\n                target=None,\\n                api_key=None,\\n                in_place=False,\\n                strip_volatile=False,\\n                strip_secrets=False,\\n                code_as_lines=False,\\n                strip_node_volatile=False,\\n                indent=2,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_project_empty_flows_exports_zero_files(self, tmp_path):\\n        project_obj = _make_project_obj(flows=[])\\n        client = _make_client_mock(project_obj=project_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_export(\\n            [],\\n            project_id=_PROJECT_ID,\\n            env=\\\"staging\\\",\\n            output_dir=str(tmp_path),\\n            sdk_mock=sdk,\\n            env_cfg=env_cfg,\\n        )\\n        written = list(tmp_path.glob(\\\"*.json\\\"))\\n        assert len(written) == 0\\n\\n    def test_project_flow_filenames_are_safe(self, tmp_path):\\n        flows = [_make_flow_obj(name=\\\"Flow: with/special*chars\\\")]\\n        project_obj = _make_project_obj(flows=flows)\\n        client = _make_client_mock(project_obj=project_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_export(\\n            [],\\n            project_id=_PROJECT_ID,\\n            env=\\\"staging\\\",\\n            output_dir=str(tmp_path),\\n            sdk_mock=sdk,\\n            env_cfg=env_cfg,\\n        )\\n        written = list(tmp_path.glob(\\\"*.json\\\"))\\n        assert len(written) == 1\\n        assert \\\":\\\" not in written[0].name\\n        assert \\\"/\\\" not in written[0].name\\n        assert \\\"*\\\" not in written[0].name\\n\\n    def test_project_target_used_without_env_name(self, tmp_path):\\n        \\\"\\\"\\\"--target alone (no --env) is sufficient for project remote mode.\\\"\\\"\\\"\\n        flows = [_make_flow_obj()]\\n        project_obj = _make_project_obj(flows=flows)\\n        client = _make_client_mock(project_obj=project_obj)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        from lfx.cli.export import export_command\\n\\n        with (\\n            patch(\\\"lfx.cli.export.load_sdk\\\", return_value=sdk),\\n            patch(\\\"lfx.config.resolve_environment\\\", return_value=env_cfg),\\n        ):\\n            export_command(\\n                flow_paths=[],\\n                output=None,\\n                output_dir=str(tmp_path),\\n                env=None,\\n                flow_id=None,\\n                project_id=_PROJECT_ID,\\n                environments_file=None,\\n                target=_BASE_URL,\\n                api_key=_API_KEY,\\n                in_place=False,\\n                strip_volatile=False,\\n                strip_secrets=False,\\n                code_as_lines=False,\\n                strip_node_volatile=False,\\n                indent=2,\\n            )\\n        client.get_project.assert_called_once()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_init_command.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d2dbd6d59a45c9b8f92106d8e29c0372a5fb05a033404d1fca269abc8b2606ab\",\"content\":\"\\\"\\\"\\\"Unit tests for ``lfx init`` \u2014 init_command and helpers.\\n\\nAll tests run entirely in-process; no running Langflow instance required.\\nFilesystem operations use ``tmp_path`` so every test gets a fresh sandbox.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\nfrom unittest.mock import patch\\n\\nimport pytest\\nimport typer\\nfrom lfx.__main__ import app\\nfrom lfx.cli.init import (\\n    _ENVIRONMENTS_YAML,\\n    _GITIGNORE,\\n    _TEMPLATES_DIR,\\n    _TEST_FLOWS_PY,\\n    _copy_template,\\n    _write,\\n    init_command,\\n)\\nfrom typer.testing import CliRunner\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\nrunner = CliRunner()\\n\\n# ---------------------------------------------------------------------------\\n# Constants / helpers\\n# ---------------------------------------------------------------------------\\n\\n_GHA_SRC = _TEMPLATES_DIR / \\\"github-actions\\\"\\n_SHELL_SRC = _TEMPLATES_DIR / \\\"shell\\\"\\n\\n\\ndef _run_init(\\n    project_dir: Path,\\n    *,\\n    github_actions: bool = False,\\n    overwrite: bool = False,\\n    example: bool = False,\\n) -> None:\\n    \\\"\\\"\\\"Thin wrapper around init_command with safe defaults for most tests.\\\"\\\"\\\"\\n    init_command(\\n        project_dir=project_dir,\\n        github_actions=github_actions,\\n        overwrite=overwrite,\\n        example=example,\\n    )\\n\\n\\n# ---------------------------------------------------------------------------\\n# _write() helper\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestWriteHelper:\\n    def test_creates_file_with_content(self, tmp_path: Path) -> None:\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        dest = tmp_path / \\\"output.txt\\\"\\n        _write(dest, \\\"hello\\\", \\\"label\\\", created, target=target, overwrite=False)\\n        assert dest.exists()\\n        assert dest.read_text(encoding=\\\"utf-8\\\") == \\\"hello\\\"\\n\\n    def test_appends_to_created_list(self, tmp_path: Path) -> None:\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        dest = tmp_path / \\\"output.txt\\\"\\n        _write(dest, \\\"content\\\", \\\"my-label\\\", created, target=target, overwrite=False)\\n        assert len(created) == 1\\n        assert created[0] == (\\\"output.txt\\\", \\\"my-label\\\")\\n\\n    def test_skips_if_exists_and_no_overwrite(self, tmp_path: Path) -> None:\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        dest = tmp_path / \\\"output.txt\\\"\\n        dest.write_text(\\\"original\\\", encoding=\\\"utf-8\\\")\\n        _write(dest, \\\"new-content\\\", \\\"label\\\", created, target=target, overwrite=False)\\n        assert dest.read_text(encoding=\\\"utf-8\\\") == \\\"original\\\"\\n        assert created == []\\n\\n    def test_overwrites_if_flag_set(self, tmp_path: Path) -> None:\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        dest = tmp_path / \\\"output.txt\\\"\\n        dest.write_text(\\\"original\\\", encoding=\\\"utf-8\\\")\\n        _write(dest, \\\"new-content\\\", \\\"label\\\", created, target=target, overwrite=True)\\n        assert dest.read_text(encoding=\\\"utf-8\\\") == \\\"new-content\\\"\\n        assert len(created) == 1\\n\\n    def test_creates_parent_directories(self, tmp_path: Path) -> None:\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        dest = tmp_path / \\\"a\\\" / \\\"b\\\" / \\\"c\\\" / \\\"file.txt\\\"\\n        _write(dest, \\\"content\\\", \\\"label\\\", created, target=target, overwrite=False)\\n        assert dest.exists()\\n\\n    def test_relative_path_in_created_list(self, tmp_path: Path) -> None:\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        dest = tmp_path / \\\"sub\\\" / \\\"file.txt\\\"\\n        _write(dest, \\\"content\\\", \\\"label\\\", created, target=target, overwrite=False)\\n        assert created[0][0] == \\\"sub/file.txt\\\"\\n\\n    def test_empty_content_creates_file(self, tmp_path: Path) -> None:\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        dest = tmp_path / \\\"empty.txt\\\"\\n        _write(dest, \\\"\\\", \\\"label\\\", created, target=target, overwrite=False)\\n        assert dest.exists()\\n        assert dest.read_text(encoding=\\\"utf-8\\\") == \\\"\\\"\\n\\n    def test_overwrite_on_nonexistent_file_creates_it(self, tmp_path: Path) -> None:\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        dest = tmp_path / \\\"new.txt\\\"\\n        _write(dest, \\\"content\\\", \\\"label\\\", created, target=target, overwrite=True)\\n        assert dest.exists()\\n        assert len(created) == 1\\n\\n\\n# ---------------------------------------------------------------------------\\n# _copy_template() helper\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestCopyTemplateHelper:\\n    def test_copies_content_from_src(self, tmp_path: Path) -> None:\\n        src = tmp_path / \\\"src.txt\\\"\\n        src.write_text(\\\"template body\\\", encoding=\\\"utf-8\\\")\\n        dest = tmp_path / \\\"output\\\" / \\\"dest.txt\\\"\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        _copy_template(src, dest, \\\"label\\\", created, target=target, overwrite=False)\\n        assert dest.read_text(encoding=\\\"utf-8\\\") == \\\"template body\\\"\\n\\n    def test_appends_to_created_list(self, tmp_path: Path) -> None:\\n        src = tmp_path / \\\"tpl.txt\\\"\\n        src.write_text(\\\"content\\\", encoding=\\\"utf-8\\\")\\n        dest = tmp_path / \\\"out\\\" / \\\"tpl.txt\\\"\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        _copy_template(src, dest, \\\"my-label\\\", created, target=target, overwrite=False)\\n        assert len(created) == 1\\n        assert created[0][1] == \\\"my-label\\\"\\n\\n    def test_skips_if_dest_exists_and_no_overwrite(self, tmp_path: Path) -> None:\\n        src = tmp_path / \\\"src.txt\\\"\\n        src.write_text(\\\"new content\\\", encoding=\\\"utf-8\\\")\\n        dest = tmp_path / \\\"dest.txt\\\"\\n        dest.write_text(\\\"original\\\", encoding=\\\"utf-8\\\")\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        _copy_template(src, dest, \\\"label\\\", created, target=target, overwrite=False)\\n        assert dest.read_text(encoding=\\\"utf-8\\\") == \\\"original\\\"\\n        assert created == []\\n\\n    def test_overwrites_dest_when_flag_set(self, tmp_path: Path) -> None:\\n        src = tmp_path / \\\"src.txt\\\"\\n        src.write_text(\\\"new content\\\", encoding=\\\"utf-8\\\")\\n        dest = tmp_path / \\\"dest.txt\\\"\\n        dest.write_text(\\\"original\\\", encoding=\\\"utf-8\\\")\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        _copy_template(src, dest, \\\"label\\\", created, target=target, overwrite=True)\\n        assert dest.read_text(encoding=\\\"utf-8\\\") == \\\"new content\\\"\\n        assert len(created) == 1\\n\\n    def test_creates_parent_directories(self, tmp_path: Path) -> None:\\n        src = tmp_path / \\\"src.txt\\\"\\n        src.write_text(\\\"content\\\", encoding=\\\"utf-8\\\")\\n        dest = tmp_path / \\\"deep\\\" / \\\"nested\\\" / \\\"dest.txt\\\"\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        _copy_template(src, dest, \\\"label\\\", created, target=target, overwrite=False)\\n        assert dest.exists()\\n\\n    def test_relative_path_stored_in_created(self, tmp_path: Path) -> None:\\n        src = tmp_path / \\\"src.txt\\\"\\n        src.write_text(\\\"content\\\", encoding=\\\"utf-8\\\")\\n        dest = tmp_path / \\\"subdir\\\" / \\\"out.txt\\\"\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        _copy_template(src, dest, \\\"label\\\", created, target=target, overwrite=False)\\n        assert created[0][0] == \\\"subdir/out.txt\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# init_command \u2014 directory creation\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInitCommandDirectoryCreation:\\n    def test_creates_flows_directory(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path / \\\"proj\\\")\\n        assert (tmp_path / \\\"proj\\\" / \\\"flows\\\").is_dir()\\n\\n    def test_creates_tests_directory(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path / \\\"proj\\\")\\n        assert (tmp_path / \\\"proj\\\" / \\\"tests\\\").is_dir()\\n\\n    def test_creates_lfx_directory(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path / \\\"proj\\\")\\n        assert (tmp_path / \\\"proj\\\" / \\\".lfx\\\").is_dir()\\n\\n    def test_creates_project_dir_if_missing(self, tmp_path: Path) -> None:\\n        target = tmp_path / \\\"brand-new-project\\\"\\n        assert not target.exists()\\n        _run_init(target)\\n        assert target.is_dir()\\n\\n    def test_creates_nested_project_dir(self, tmp_path: Path) -> None:\\n        target = tmp_path / \\\"a\\\" / \\\"b\\\" / \\\"c\\\"\\n        _run_init(target)\\n        assert target.is_dir()\\n\\n\\n# ---------------------------------------------------------------------------\\n# init_command \u2014 required files created\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInitCommandRequiredFiles:\\n    def test_creates_tests_init_py(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path)\\n        assert (tmp_path / \\\"tests\\\" / \\\"__init__.py\\\").exists()\\n\\n    def test_creates_tests_test_flows_py(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path)\\n        assert (tmp_path / \\\"tests\\\" / \\\"test_flows.py\\\").exists()\\n\\n    def test_test_flows_py_has_expected_content(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path)\\n        content = (tmp_path / \\\"tests\\\" / \\\"test_flows.py\\\").read_text(encoding=\\\"utf-8\\\")\\n        assert \\\"flow_runner\\\" in content\\n        assert \\\"pytest.mark.integration\\\" in content\\n\\n    def test_test_flows_py_content_matches_template(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path)\\n        content = (tmp_path / \\\"tests\\\" / \\\"test_flows.py\\\").read_text(encoding=\\\"utf-8\\\")\\n        assert content == _TEST_FLOWS_PY\\n\\n    def test_creates_environments_yaml(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path)\\n        assert (tmp_path / \\\".lfx\\\" / \\\"environments.yaml\\\").exists()\\n\\n    def test_environments_yaml_has_expected_content(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path)\\n        content = (tmp_path / \\\".lfx\\\" / \\\"environments.yaml\\\").read_text(encoding=\\\"utf-8\\\")\\n        assert \\\"environments:\\\" in content\\n        assert \\\"local:\\\" in content\\n        assert \\\"staging:\\\" in content\\n        assert \\\"production:\\\" in content\\n\\n    def test_environments_yaml_content_matches_template(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path)\\n        content = (tmp_path / \\\".lfx\\\" / \\\"environments.yaml\\\").read_text(encoding=\\\"utf-8\\\")\\n        assert content == _ENVIRONMENTS_YAML\\n\\n    def test_creates_gitignore(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path)\\n        assert (tmp_path / \\\".gitignore\\\").exists()\\n\\n    def test_gitignore_has_langflow_entry(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path)\\n        content = (tmp_path / \\\".gitignore\\\").read_text(encoding=\\\"utf-8\\\")\\n        assert \\\"langflow-environments.toml\\\" in content\\n\\n\\n# ---------------------------------------------------------------------------\\n# init_command \u2014 .gitignore behaviour\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInitCommandGitignore:\\n    def test_creates_new_gitignore_if_missing(self, tmp_path: Path) -> None:\\n        assert not (tmp_path / \\\".gitignore\\\").exists()\\n        _run_init(tmp_path)\\n        assert (tmp_path / \\\".gitignore\\\").exists()\\n\\n    def test_new_gitignore_content_matches_template(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path)\\n        content = (tmp_path / \\\".gitignore\\\").read_text(encoding=\\\"utf-8\\\")\\n        assert content == _GITIGNORE\\n\\n    def test_appends_rule_to_existing_gitignore_without_entry(self, tmp_path: Path) -> None:\\n        gitignore = tmp_path / \\\".gitignore\\\"\\n        gitignore.write_text(\\\"*.pyc\\\\n__pycache__/\\\\n\\\", encoding=\\\"utf-8\\\")\\n        # Directory already has .gitignore so use overwrite=True to bypass the non-empty guard\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=True, example=False)\\n        content = gitignore.read_text(encoding=\\\"utf-8\\\")\\n        assert \\\"*.pyc\\\" in content\\n        assert \\\"__pycache__/\\\" in content\\n        assert \\\"langflow-environments.toml\\\" in content\\n\\n    def test_does_not_append_duplicate_rule(self, tmp_path: Path) -> None:\\n        gitignore = tmp_path / \\\".gitignore\\\"\\n        gitignore.write_text(\\\"langflow-environments.toml\\\\n\\\", encoding=\\\"utf-8\\\")\\n        # Directory already has .gitignore so use overwrite=True to bypass the non-empty guard\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=True, example=False)\\n        content = gitignore.read_text(encoding=\\\"utf-8\\\")\\n        # Should appear exactly once\\n        assert content.count(\\\"langflow-environments.toml\\\") == 1\\n\\n    def test_existing_gitignore_preserved_and_appended(self, tmp_path: Path) -> None:\\n        gitignore = tmp_path / \\\".gitignore\\\"\\n        original = \\\"node_modules/\\\\ndist/\\\\n\\\"\\n        gitignore.write_text(original, encoding=\\\"utf-8\\\")\\n        # Directory already has .gitignore so use overwrite=True to bypass the non-empty guard\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=True, example=False)\\n        content = gitignore.read_text(encoding=\\\"utf-8\\\")\\n        # Original content is kept\\n        assert \\\"node_modules/\\\" in content\\n        assert \\\"dist/\\\" in content\\n        # Rule is appended\\n        assert \\\"langflow-environments.toml\\\" in content\\n\\n    def test_append_uses_double_newline_separator(self, tmp_path: Path) -> None:\\n        gitignore = tmp_path / \\\".gitignore\\\"\\n        gitignore.write_text(\\\"*.pyc\\\\n\\\", encoding=\\\"utf-8\\\")\\n        # Directory already has .gitignore so use overwrite=True to bypass the non-empty guard\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=True, example=False)\\n        content = gitignore.read_text(encoding=\\\"utf-8\\\")\\n        # The separator between existing content and appended block should be \\\\n\\\\n\\n        assert \\\"\\\\n\\\\n\\\" in content\\n\\n\\n# ---------------------------------------------------------------------------\\n# init_command \u2014 example=True (with seeded hello-world flow)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInitCommandExampleTrue:\\n    def test_creates_hello_world_json(self, tmp_path: Path) -> None:\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=True)\\n        assert (tmp_path / \\\"flows\\\" / \\\"hello-world.json\\\").exists()\\n\\n    def test_hello_world_is_valid_json(self, tmp_path: Path) -> None:\\n        import json\\n\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=True)\\n        content = (tmp_path / \\\"flows\\\" / \\\"hello-world.json\\\").read_text(encoding=\\\"utf-8\\\")\\n        flow = json.loads(content)\\n        assert isinstance(flow, dict)\\n\\n    def test_hello_world_has_id_and_name(self, tmp_path: Path) -> None:\\n        import json\\n\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=True)\\n        flow = json.loads((tmp_path / \\\"flows\\\" / \\\"hello-world.json\\\").read_text(encoding=\\\"utf-8\\\"))\\n        assert \\\"id\\\" in flow\\n        assert \\\"name\\\" in flow\\n        assert flow[\\\"name\\\"] == \\\"hello-world\\\"\\n\\n    def test_no_gitkeep_when_example_is_true(self, tmp_path: Path) -> None:\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=True)\\n        assert not (tmp_path / \\\"flows\\\" / \\\".gitkeep\\\").exists()\\n\\n    def test_other_files_still_created_with_example(self, tmp_path: Path) -> None:\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=True)\\n        assert (tmp_path / \\\".lfx\\\" / \\\"environments.yaml\\\").exists()\\n        assert (tmp_path / \\\"tests\\\" / \\\"test_flows.py\\\").exists()\\n        assert (tmp_path / \\\"tests\\\" / \\\"__init__.py\\\").exists()\\n\\n    def test_graceful_fallback_when_template_missing(self, tmp_path: Path) -> None:\\n        \\\"\\\"\\\"If create_command raises, init should warn but continue scaffolding.\\\"\\\"\\\"\\n        fake_dir = tmp_path / \\\"no-templates\\\"\\n        with patch(\\\"lfx.cli.create._FLOWS_TEMPLATE_DIR\\\", fake_dir):\\n            # Should not raise \u2014 BLE001-guarded except swallows the failure\\n            init_command(\\n                project_dir=tmp_path / \\\"proj\\\",\\n                github_actions=False,\\n                overwrite=False,\\n                example=True,\\n            )\\n        assert (tmp_path / \\\"proj\\\" / \\\".lfx\\\" / \\\"environments.yaml\\\").exists()\\n\\n\\n# ---------------------------------------------------------------------------\\n# init_command \u2014 example=False (with .gitkeep)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInitCommandExampleFalse:\\n    def test_creates_gitkeep_in_flows(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path, example=False)\\n        assert (tmp_path / \\\"flows\\\" / \\\".gitkeep\\\").exists()\\n\\n    def test_no_hello_world_when_example_false(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path, example=False)\\n        assert not (tmp_path / \\\"flows\\\" / \\\"hello-world.json\\\").exists()\\n\\n    def test_gitkeep_is_empty_file(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path, example=False)\\n        assert (tmp_path / \\\"flows\\\" / \\\".gitkeep\\\").read_text(encoding=\\\"utf-8\\\") == \\\"\\\"\\n\\n    def test_other_files_still_created_without_example(self, tmp_path: Path) -> None:\\n        _run_init(tmp_path, example=False)\\n        assert (tmp_path / \\\".lfx\\\" / \\\"environments.yaml\\\").exists()\\n        assert (tmp_path / \\\"tests\\\" / \\\"test_flows.py\\\").exists()\\n        assert (tmp_path / \\\"tests\\\" / \\\"__init__.py\\\").exists()\\n        assert (tmp_path / \\\".gitignore\\\").exists()\\n\\n\\n# ---------------------------------------------------------------------------\\n# init_command \u2014 GitHub Actions templates\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInitCommandGitHubActions:\\n    def test_creates_github_workflows_dir_when_gha_true(self, tmp_path: Path) -> None:\\n        if not _GHA_SRC.exists():\\n            pytest.skip(\\\"GitHub Actions templates not bundled\\\")\\n        init_command(project_dir=tmp_path, github_actions=True, overwrite=False, example=False)\\n        assert (tmp_path / \\\".github\\\" / \\\"workflows\\\").is_dir()\\n\\n    def test_copies_all_yml_templates(self, tmp_path: Path) -> None:\\n        if not _GHA_SRC.exists():\\n            pytest.skip(\\\"GitHub Actions templates not bundled\\\")\\n        expected = sorted(t.name for t in _GHA_SRC.glob(\\\"*.yml\\\"))\\n        init_command(project_dir=tmp_path, github_actions=True, overwrite=False, example=False)\\n        created = sorted(p.name for p in (tmp_path / \\\".github\\\" / \\\"workflows\\\").glob(\\\"*.yml\\\"))\\n        assert created == expected\\n\\n    def test_workflow_files_are_non_empty(self, tmp_path: Path) -> None:\\n        if not _GHA_SRC.exists():\\n            pytest.skip(\\\"GitHub Actions templates not bundled\\\")\\n        init_command(project_dir=tmp_path, github_actions=True, overwrite=False, example=False)\\n        for yml in (tmp_path / \\\".github\\\" / \\\"workflows\\\").glob(\\\"*.yml\\\"):\\n            assert yml.stat().st_size > 0, f\\\"{yml.name} should not be empty\\\"\\n\\n    def test_workflow_file_content_matches_template(self, tmp_path: Path) -> None:\\n        if not _GHA_SRC.exists():\\n            pytest.skip(\\\"GitHub Actions templates not bundled\\\")\\n        init_command(project_dir=tmp_path, github_actions=True, overwrite=False, example=False)\\n        for src_tmpl in _GHA_SRC.glob(\\\"*.yml\\\"):\\n            dest = tmp_path / \\\".github\\\" / \\\"workflows\\\" / src_tmpl.name\\n            assert dest.read_text(encoding=\\\"utf-8\\\") == src_tmpl.read_text(encoding=\\\"utf-8\\\")\\n\\n    def test_skips_github_workflows_when_gha_false(self, tmp_path: Path) -> None:\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=False)\\n        assert not (tmp_path / \\\".github\\\").exists()\\n\\n    def test_warns_when_gha_templates_dir_missing(self, tmp_path: Path) -> None:\\n        \\\"\\\"\\\"When the template directory is absent a warning is printed but no error raised.\\\"\\\"\\\"\\n        missing_templates = tmp_path / \\\"no-such-templates\\\"\\n        with patch(\\\"lfx.cli.init._TEMPLATES_DIR\\\", missing_templates):\\n            # Should not raise\\n            init_command(project_dir=tmp_path / \\\"proj\\\", github_actions=True, overwrite=False, example=False)\\n        # The project's other files should still be scaffolded\\n        assert (tmp_path / \\\"proj\\\" / \\\".lfx\\\" / \\\"environments.yaml\\\").exists()\\n\\n\\n# ---------------------------------------------------------------------------\\n# init_command \u2014 shell CI scripts (always scaffolded)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInitCommandShellScripts:\\n    def test_creates_ci_directory(self, tmp_path: Path) -> None:\\n        if not _SHELL_SRC.exists():\\n            pytest.skip(\\\"Shell templates not bundled\\\")\\n        _run_init(tmp_path)\\n        assert (tmp_path / \\\"ci\\\").is_dir()\\n\\n    def test_copies_all_sh_templates(self, tmp_path: Path) -> None:\\n        if not _SHELL_SRC.exists():\\n            pytest.skip(\\\"Shell templates not bundled\\\")\\n        expected = sorted(t.name for t in _SHELL_SRC.glob(\\\"*.sh\\\"))\\n        _run_init(tmp_path)\\n        created = sorted(p.name for p in (tmp_path / \\\"ci\\\").glob(\\\"*.sh\\\"))\\n        assert created == expected\\n\\n    def test_shell_scripts_are_executable(self, tmp_path: Path) -> None:\\n        if not _SHELL_SRC.exists():\\n            pytest.skip(\\\"Shell templates not bundled\\\")\\n        _run_init(tmp_path)\\n        import stat\\n\\n        for script in (tmp_path / \\\"ci\\\").glob(\\\"*.sh\\\"):\\n            mode = script.stat().st_mode\\n            assert mode & stat.S_IXUSR, f\\\"{script.name} should have executable bit set\\\"\\n\\n    def test_shell_script_content_matches_template(self, tmp_path: Path) -> None:\\n        if not _SHELL_SRC.exists():\\n            pytest.skip(\\\"Shell templates not bundled\\\")\\n        _run_init(tmp_path)\\n        for src_tmpl in _SHELL_SRC.glob(\\\"*.sh\\\"):\\n            dest = tmp_path / \\\"ci\\\" / src_tmpl.name\\n            assert dest.read_text(encoding=\\\"utf-8\\\") == src_tmpl.read_text(encoding=\\\"utf-8\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# init_command \u2014 non-empty directory guard\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInitCommandNonEmptyGuard:\\n    def test_exits_with_code_1_on_non_empty_dir_without_overwrite(self, tmp_path: Path) -> None:\\n        (tmp_path / \\\"existing.txt\\\").write_text(\\\"data\\\", encoding=\\\"utf-8\\\")\\n        with pytest.raises(typer.Exit) as exc_info:\\n            init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=False)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_empty_dir_does_not_raise(self, tmp_path: Path) -> None:\\n        target = tmp_path / \\\"empty\\\"\\n        target.mkdir()\\n        # Should not raise\\n        init_command(project_dir=target, github_actions=False, overwrite=False, example=False)\\n\\n    def test_nonexistent_dir_does_not_raise(self, tmp_path: Path) -> None:\\n        target = tmp_path / \\\"brand-new\\\"\\n        # Should not raise\\n        init_command(project_dir=target, github_actions=False, overwrite=False, example=False)\\n\\n    def test_git_dir_only_is_not_considered_non_empty(self, tmp_path: Path) -> None:\\n        \\\"\\\"\\\"A directory containing only .git is treated as empty by the guard.\\\"\\\"\\\"\\n        (tmp_path / \\\".git\\\").mkdir()\\n        # Should not raise \u2014 .git is excluded from the check\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=False, example=False)\\n\\n    def test_overwrite_succeeds_on_non_empty_dir(self, tmp_path: Path) -> None:\\n        (tmp_path / \\\"existing.txt\\\").write_text(\\\"data\\\", encoding=\\\"utf-8\\\")\\n        # Should not raise\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=True, example=False)\\n        assert (tmp_path / \\\".lfx\\\" / \\\"environments.yaml\\\").exists()\\n\\n\\n# ---------------------------------------------------------------------------\\n# init_command \u2014 --overwrite re-creates files\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInitCommandOverwrite:\\n    def test_overwrite_replaces_environments_yaml(self, tmp_path: Path) -> None:\\n        env_yaml = tmp_path / \\\".lfx\\\" / \\\"environments.yaml\\\"\\n        env_yaml.parent.mkdir(parents=True)\\n        env_yaml.write_text(\\\"# old content\\\\n\\\", encoding=\\\"utf-8\\\")\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=True, example=False)\\n        content = env_yaml.read_text(encoding=\\\"utf-8\\\")\\n        assert content == _ENVIRONMENTS_YAML\\n\\n    def test_overwrite_replaces_test_flows_py(self, tmp_path: Path) -> None:\\n        tests_dir = tmp_path / \\\"tests\\\"\\n        tests_dir.mkdir(parents=True)\\n        test_file = tests_dir / \\\"test_flows.py\\\"\\n        test_file.write_text(\\\"# old tests\\\\n\\\", encoding=\\\"utf-8\\\")\\n        init_command(project_dir=tmp_path, github_actions=False, overwrite=True, example=False)\\n        content = test_file.read_text(encoding=\\\"utf-8\\\")\\n        assert content == _TEST_FLOWS_PY\\n\\n    def test_no_overwrite_preserves_environments_yaml(self, tmp_path: Path) -> None:\\n        \\\"\\\"\\\"_write skips existing files when overwrite=False (tested via the helper directly).\\\"\\\"\\\"\\n        target = tmp_path\\n        created: list[tuple[str, str]] = []\\n        dest = tmp_path / \\\".lfx\\\" / \\\"environments.yaml\\\"\\n        dest.parent.mkdir(parents=True)\\n        dest.write_text(\\\"# custom content\\\\n\\\", encoding=\\\"utf-8\\\")\\n        _write(dest, _ENVIRONMENTS_YAML, \\\"label\\\", created, target=target, overwrite=False)\\n        # Original content must be preserved\\n        assert dest.read_text(encoding=\\\"utf-8\\\") == \\\"# custom content\\\\n\\\"\\n        assert created == []\\n\\n    def test_overwrite_with_github_actions_replaces_workflows(self, tmp_path: Path) -> None:\\n        if not _GHA_SRC.exists():\\n            pytest.skip(\\\"GitHub Actions templates not bundled\\\")\\n        # First init\\n        init_command(project_dir=tmp_path, github_actions=True, overwrite=False, example=False)\\n        # Corrupt one workflow file\\n        wf_dir = tmp_path / \\\".github\\\" / \\\"workflows\\\"\\n        first_wf = next(wf_dir.glob(\\\"*.yml\\\"))\\n        first_wf.write_text(\\\"# corrupted\\\\n\\\", encoding=\\\"utf-8\\\")\\n        # Overwrite init\\n        init_command(project_dir=tmp_path, github_actions=True, overwrite=True, example=False)\\n        # Content should be restored from template\\n        src_content = (_GHA_SRC / first_wf.name).read_text(encoding=\\\"utf-8\\\")\\n        assert first_wf.read_text(encoding=\\\"utf-8\\\") == src_content\\n\\n\\n# ---------------------------------------------------------------------------\\n# CLI wrapper via typer CliRunner\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInitCLI:\\n    def test_basic_init_exits_zero(self, tmp_path: Path) -> None:\\n        result = runner.invoke(app, [\\\"init\\\", str(tmp_path / \\\"proj\\\")])\\n        assert result.exit_code == 0, result.output\\n\\n    def test_basic_init_creates_environments_yaml(self, tmp_path: Path) -> None:\\n        proj = tmp_path / \\\"proj\\\"\\n        result = runner.invoke(app, [\\\"init\\\", str(proj)])\\n        assert result.exit_code == 0, result.output\\n        assert (proj / \\\".lfx\\\" / \\\"environments.yaml\\\").exists()\\n\\n    def test_basic_init_creates_test_flows_py(self, tmp_path: Path) -> None:\\n        proj = tmp_path / \\\"proj\\\"\\n        result = runner.invoke(app, [\\\"init\\\", str(proj)])\\n        assert result.exit_code == 0, result.output\\n        assert (proj / \\\"tests\\\" / \\\"test_flows.py\\\").exists()\\n\\n    def test_no_github_actions_flag(self, tmp_path: Path) -> None:\\n        proj = tmp_path / \\\"proj\\\"\\n        result = runner.invoke(app, [\\\"init\\\", str(proj), \\\"--no-github-actions\\\"])\\n        assert result.exit_code == 0, result.output\\n        assert not (proj / \\\".github\\\").exists()\\n\\n    def test_github_actions_flag_creates_workflows(self, tmp_path: Path) -> None:\\n        if not _GHA_SRC.exists():\\n            pytest.skip(\\\"GitHub Actions templates not bundled\\\")\\n        proj = tmp_path / \\\"proj\\\"\\n        result = runner.invoke(app, [\\\"init\\\", str(proj), \\\"--github-actions\\\"])\\n        assert result.exit_code == 0, result.output\\n        assert (proj / \\\".github\\\" / \\\"workflows\\\").is_dir()\\n\\n    def test_no_example_flag_creates_gitkeep(self, tmp_path: Path) -> None:\\n        proj = tmp_path / \\\"proj\\\"\\n        result = runner.invoke(app, [\\\"init\\\", str(proj), \\\"--no-github-actions\\\", \\\"--no-example\\\"])\\n        assert result.exit_code == 0, result.output\\n        assert (proj / \\\"flows\\\" / \\\".gitkeep\\\").exists()\\n        assert not (proj / \\\"flows\\\" / \\\"hello-world.json\\\").exists()\\n\\n    def test_example_flag_creates_hello_world(self, tmp_path: Path) -> None:\\n        proj = tmp_path / \\\"proj\\\"\\n        result = runner.invoke(app, [\\\"init\\\", str(proj), \\\"--no-github-actions\\\", \\\"--example\\\"])\\n        assert result.exit_code == 0, result.output\\n        assert (proj / \\\"flows\\\" / \\\"hello-world.json\\\").exists()\\n\\n    def test_overwrite_flag_reinitialises_non_empty_dir(self, tmp_path: Path) -> None:\\n        proj = tmp_path / \\\"proj\\\"\\n        proj.mkdir()\\n        (proj / \\\"some-file.txt\\\").write_text(\\\"existing\\\", encoding=\\\"utf-8\\\")\\n        result = runner.invoke(app, [\\\"init\\\", str(proj), \\\"--no-github-actions\\\", \\\"--no-example\\\", \\\"--overwrite\\\"])\\n        assert result.exit_code == 0, result.output\\n        assert (proj / \\\".lfx\\\" / \\\"environments.yaml\\\").exists()\\n\\n    def test_non_empty_dir_without_overwrite_exits_nonzero(self, tmp_path: Path) -> None:\\n        proj = tmp_path / \\\"proj\\\"\\n        proj.mkdir()\\n        (proj / \\\"some-file.txt\\\").write_text(\\\"existing\\\", encoding=\\\"utf-8\\\")\\n        result = runner.invoke(app, [\\\"init\\\", str(proj), \\\"--no-github-actions\\\"])\\n        assert result.exit_code != 0\\n\\n    def test_default_project_dir_is_current_directory(self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:\\n        \\\"\\\"\\\"When no project_dir argument is given the CLI defaults to '.'.\\\"\\\"\\\"\\n        monkeypatch.chdir(tmp_path)\\n        result = runner.invoke(app, [\\\"init\\\", \\\"--no-github-actions\\\", \\\"--no-example\\\"])\\n        assert result.exit_code == 0, result.output\\n        assert (tmp_path / \\\".lfx\\\" / \\\"environments.yaml\\\").exists()\\n\\n    def test_init_output_mentions_next_steps(self, tmp_path: Path) -> None:\\n        result = runner.invoke(app, [\\\"init\\\", str(tmp_path / \\\"proj\\\"), \\\"--no-github-actions\\\"])\\n        assert result.exit_code == 0, result.output\\n        assert \\\"Next steps\\\" in result.output\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_lazy_imports.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"db6425ba0bdc7c0e88f4a687b9ae9134f487ee7d37f61d5b9c83b72ce94677cd\",\"content\":\"\\\"\\\"\\\"Tests for CLI lazy import mechanisms.\\n\\nThese tests verify that the lazy import patterns in CLI modules work correctly\\nand help reduce cold start time.\\n\\\"\\\"\\\"\\n\\nimport json\\n\\nimport pytest\\n\\n\\nclass TestCLIModuleLazyImports:\\n    \\\"\\\"\\\"Test lazy imports in CLI __init__ module.\\\"\\\"\\\"\\n\\n    def test_serve_command_accessible_via_getattr(self):\\n        \\\"\\\"\\\"Test that serve_command can be accessed via lazy import.\\\"\\\"\\\"\\n        import lfx.cli\\n\\n        # Access serve_command - this should trigger lazy loading\\n        serve_cmd = lfx.cli.serve_command\\n        assert serve_cmd is not None\\n        assert callable(serve_cmd)\\n\\n    def test_invalid_cli_attribute_raises_error(self):\\n        \\\"\\\"\\\"Test that accessing invalid attribute raises AttributeError.\\\"\\\"\\\"\\n        import lfx.cli\\n\\n        with pytest.raises(AttributeError, match=\\\"has no attribute 'nonexistent_command'\\\"):\\n            _ = lfx.cli.nonexistent_command\\n\\n\\nclass TestMainModuleLazyImports:\\n    \\\"\\\"\\\"Test lazy imports in __main__ module.\\\"\\\"\\\"\\n\\n    def test_main_module_importable(self):\\n        \\\"\\\"\\\"Test that __main__ module can be imported without heavy dependencies.\\\"\\\"\\\"\\n        # This test verifies the module imports quickly\\n        import lfx.__main__\\n\\n        assert hasattr(lfx.__main__, \\\"main\\\")\\n        assert callable(lfx.__main__.main)\\n\\n    def test_serve_command_wrapper_exists(self):\\n        \\\"\\\"\\\"Test that serve command is registered on the app.\\\"\\\"\\\"\\n        from lfx.__main__ import app\\n\\n        command_names = [c.name for c in app.registered_commands]\\n        assert \\\"serve\\\" in command_names\\n\\n    def test_run_command_wrapper_exists(self):\\n        \\\"\\\"\\\"Test that run command is registered on the app.\\\"\\\"\\\"\\n        from lfx.__main__ import app\\n\\n        command_names = [c.name for c in app.registered_commands]\\n        assert \\\"run\\\" in command_names\\n\\n\\nclass TestRunCommandLazyImports:\\n    \\\"\\\"\\\"Test lazy imports in run.py module.\\\"\\\"\\\"\\n\\n    def test_run_module_importable(self):\\n        \\\"\\\"\\\"Test that run module can be imported.\\\"\\\"\\\"\\n        from lfx.cli import run\\n\\n        assert hasattr(run, \\\"run\\\")\\n\\n    def test_script_loader_functions_not_imported_at_module_level(self):\\n        \\\"\\\"\\\"Test that script_loader functions are imported lazily.\\\"\\\"\\\"\\n        # Import the run module\\n        from lfx.cli import run\\n\\n        # The script_loader module should NOT be in sys.modules at this point\\n        # unless something else imported it\\n        # This is a soft test - we mainly want to ensure the module loads\\n\\n        # Verify the run function exists and is callable\\n        assert hasattr(run, \\\"run\\\")\\n        assert callable(run.run)\\n\\n\\nclass TestValidationLazyImports:\\n    \\\"\\\"\\\"Test lazy imports in validation.py module.\\\"\\\"\\\"\\n\\n    def test_validation_module_importable(self):\\n        \\\"\\\"\\\"Test that validation module can be imported.\\\"\\\"\\\"\\n        from lfx.cli import validation\\n\\n        assert hasattr(validation, \\\"is_valid_env_var_name\\\")\\n        assert hasattr(validation, \\\"validate_global_variables_for_env\\\")\\n\\n    def test_is_valid_env_var_name_works(self):\\n        \\\"\\\"\\\"Test that is_valid_env_var_name function works correctly.\\\"\\\"\\\"\\n        from lfx.cli.validation import is_valid_env_var_name\\n\\n        assert is_valid_env_var_name(\\\"VALID_VAR\\\")\\n        assert is_valid_env_var_name(\\\"_PRIVATE\\\")\\n        assert is_valid_env_var_name(\\\"VAR123\\\")\\n        assert not is_valid_env_var_name(\\\"invalid-var\\\")\\n        assert not is_valid_env_var_name(\\\"123_STARTS_WITH_NUMBER\\\")\\n        assert not is_valid_env_var_name(\\\"has space\\\")\\n\\n\\nclass TestScriptLoaderLazyImports:\\n    \\\"\\\"\\\"Test lazy imports in script_loader.py module.\\\"\\\"\\\"\\n\\n    def test_script_loader_module_importable(self):\\n        \\\"\\\"\\\"Test that script_loader module can be imported.\\\"\\\"\\\"\\n        from lfx.cli import script_loader\\n\\n        assert hasattr(script_loader, \\\"load_graph_from_script\\\")\\n        assert hasattr(script_loader, \\\"find_graph_variable\\\")\\n        assert hasattr(script_loader, \\\"extract_message_from_result\\\")\\n        assert hasattr(script_loader, \\\"extract_text_from_result\\\")\\n\\n    def test_find_graph_variable_works(self, tmp_path):\\n        \\\"\\\"\\\"Test that find_graph_variable function works.\\\"\\\"\\\"\\n        from lfx.cli.script_loader import find_graph_variable\\n\\n        # Create a test script with a graph variable\\n        script_content = \\\"\\\"\\\"\\nfrom lfx.graph import Graph\\n\\ngraph = Graph.from_payload({})\\n\\\"\\\"\\\"\\n        script_path = tmp_path / \\\"test_script.py\\\"\\n        script_path.write_text(script_content)\\n\\n        result = find_graph_variable(script_path)\\n        assert result is not None\\n        assert result[\\\"type\\\"] == \\\"function_call\\\"\\n        assert \\\"Graph\\\" in result[\\\"function\\\"]\\n\\n    def test_find_graph_variable_with_get_graph_function(self, tmp_path):\\n        \\\"\\\"\\\"Test that find_graph_variable detects get_graph functions.\\\"\\\"\\\"\\n        from lfx.cli.script_loader import find_graph_variable\\n\\n        # Create a test script with get_graph function\\n        script_content = \\\"\\\"\\\"\\ndef get_graph():\\n    from lfx.graph import Graph\\n    return Graph.from_payload({})\\n\\\"\\\"\\\"\\n        script_path = tmp_path / \\\"test_script.py\\\"\\n        script_path.write_text(script_content)\\n\\n        result = find_graph_variable(script_path)\\n        assert result is not None\\n        assert result[\\\"type\\\"] == \\\"function_definition\\\"\\n        assert result[\\\"function\\\"] == \\\"get_graph\\\"\\n\\n    def test_find_graph_variable_returns_none_for_no_graph(self, tmp_path):\\n        \\\"\\\"\\\"Test that find_graph_variable returns None when no graph is found.\\\"\\\"\\\"\\n        from lfx.cli.script_loader import find_graph_variable\\n\\n        script_content = \\\"\\\"\\\"\\nx = 1\\ny = 2\\n\\\"\\\"\\\"\\n        script_path = tmp_path / \\\"test_script.py\\\"\\n        script_path.write_text(script_content)\\n\\n        result = find_graph_variable(script_path)\\n        assert result is None\\n\\n\\nclass TestFlowDictHandling:\\n    \\\"\\\"\\\"Test in-memory flow dict handling in run command.\\\"\\\"\\\"\\n\\n    def test_json_parsing_for_flow_json(self):\\n        \\\"\\\"\\\"Test that flow_json string can be parsed to dict.\\\"\\\"\\\"\\n        flow_json = '{\\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}'\\n        flow_dict = json.loads(flow_json)\\n\\n        assert isinstance(flow_dict, dict)\\n        assert \\\"data\\\" in flow_dict\\n        assert flow_dict[\\\"data\\\"][\\\"nodes\\\"] == []\\n        assert flow_dict[\\\"data\\\"][\\\"edges\\\"] == []\\n\\n    def test_json_parsing_for_complex_flow(self):\\n        \\\"\\\"\\\"Test parsing a more complex flow structure.\\\"\\\"\\\"\\n        flow_json = json.dumps(\\n            {\\n                \\\"data\\\": {\\n                    \\\"nodes\\\": [\\n                        {\\\"id\\\": \\\"node1\\\", \\\"type\\\": \\\"ChatInput\\\", \\\"data\\\": {}},\\n                        {\\\"id\\\": \\\"node2\\\", \\\"type\\\": \\\"ChatOutput\\\", \\\"data\\\": {}},\\n                    ],\\n                    \\\"edges\\\": [{\\\"source\\\": \\\"node1\\\", \\\"target\\\": \\\"node2\\\"}],\\n                }\\n            }\\n        )\\n        flow_dict = json.loads(flow_json)\\n\\n        assert len(flow_dict[\\\"data\\\"][\\\"nodes\\\"]) == 2\\n        assert len(flow_dict[\\\"data\\\"][\\\"edges\\\"]) == 1\\n        assert flow_dict[\\\"data\\\"][\\\"nodes\\\"][0][\\\"id\\\"] == \\\"node1\\\"\\n\\n    def test_invalid_json_raises_error(self):\\n        \\\"\\\"\\\"Test that invalid JSON raises appropriate error.\\\"\\\"\\\"\\n        invalid_json = '{\\\"data\\\": invalid}'\\n\\n        with pytest.raises(json.JSONDecodeError):\\n            json.loads(invalid_json)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_login_command.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e0c7d715eb594c408f50f3a891263a504e581a7af852cb52df6472632341414c\",\"content\":\"\\\"\\\"\\\"Unit tests for lfx login -- login_command and helpers.\\n\\nAll tests run entirely in-process; no real Langflow instance or SDK required.\\nThe SDK module is replaced wholesale with MagicMock so only the login logic\\n(key masking, connection probing, success/failure output) is under test.\\n\\\"\\\"\\\"\\n# pragma: allowlist secret -- all credentials in this file are fake test data\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nimport typer\\n\\n# ---------------------------------------------------------------------------\\n# Shared constants\\n# ---------------------------------------------------------------------------\\n\\n_BASE_URL = \\\"http://langflow.test\\\"\\n_API_KEY = \\\"abcdefghijklmnop\\\"  # pragma: allowlist secret  (16 chars \u2014 longer than 8)\\n_SHORT_KEY = \\\"short\\\"  # pragma: allowlist secret  (5 chars \u2014 at or under the 8-char mask threshold)\\n_EXACT_KEY = \\\"exactly8\\\"  # pragma: allowlist secret  (exactly 8 chars)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Fake SDK exception classes\\n# ---------------------------------------------------------------------------\\n\\n\\nclass _FakeLangflowAuthError(Exception):\\n    \\\"\\\"\\\"Stand-in for langflow_sdk.LangflowAuthError in unit tests.\\\"\\\"\\\"\\n\\n\\nclass _FakeLangflowConnectionError(Exception):\\n    \\\"\\\"\\\"Stand-in for langflow_sdk.LangflowConnectionError in unit tests.\\\"\\\"\\\"\\n\\n\\nclass _FakeLangflowHTTPError(Exception):\\n    \\\"\\\"\\\"Stand-in for langflow_sdk.LangflowHTTPError in unit tests.\\\"\\\"\\\"\\n\\n    def __init__(self, status_code: int, detail: str) -> None:\\n        self.status_code = status_code\\n        super().__init__(detail)\\n\\n\\n# A fake exception whose qualname contains \\\"ValidationError\\\" so _probe_connection\\n# treats it as a successful probe.\\nclass _FakeValidationError(Exception):\\n    \\\"\\\"\\\"Simulates a Pydantic ValidationError (qualname contains 'ValidationError').\\\"\\\"\\\"\\n\\n\\n_FakeValidationError.__qualname__ = \\\"ModelMetaclass.ValidationError\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# SDK / client / env helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _make_client_mock(flows: list | None = None) -> MagicMock:\\n    client = MagicMock()\\n    client.list_flows.return_value = flows if flows is not None else [MagicMock(), MagicMock()]\\n    return client\\n\\n\\ndef _make_sdk_mock(client_mock: MagicMock | None = None) -> MagicMock:\\n    \\\"\\\"\\\"Return a mock langflow_sdk module wired up for login tests.\\\"\\\"\\\"\\n    if client_mock is None:\\n        client_mock = _make_client_mock()\\n    sdk = MagicMock()\\n    sdk.Client.return_value = client_mock\\n    sdk.LangflowAuthError = _FakeLangflowAuthError\\n    sdk.LangflowConnectionError = _FakeLangflowConnectionError\\n    sdk.LangflowHTTPError = _FakeLangflowHTTPError\\n    return sdk\\n\\n\\ndef _make_env_cfg(\\n    url: str = _BASE_URL,\\n    api_key: str | None = _API_KEY,\\n    name: str = \\\"staging\\\",\\n) -> MagicMock:\\n    env_cfg = MagicMock()\\n    env_cfg.url = url\\n    env_cfg.api_key = api_key\\n    env_cfg.name = name\\n    return env_cfg\\n\\n\\ndef _run_login(\\n    *,\\n    env: str | None = \\\"staging\\\",\\n    environments_file: str | None = None,\\n    target: str | None = None,\\n    api_key: str | None = _API_KEY,\\n    sdk_mock: MagicMock | None = None,\\n    env_cfg: MagicMock | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Invoke login_command with a mocked SDK and mocked env resolution.\\\"\\\"\\\"\\n    from lfx.cli.login import login_command\\n\\n    mock = sdk_mock if sdk_mock is not None else _make_sdk_mock()\\n    resolved_env = env_cfg if env_cfg is not None else _make_env_cfg()\\n\\n    with (\\n        patch(\\\"lfx.cli.login.load_sdk\\\", return_value=mock),\\n        patch(\\\"lfx.config.resolve_environment\\\", return_value=resolved_env),\\n    ):\\n        login_command(\\n            env=env,\\n            environments_file=environments_file,\\n            target=target,\\n            api_key=api_key,\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# _mask_key\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestMaskKey:\\n    def test_long_key_shows_first_8_chars_plus_ellipsis(self):\\n        from lfx.cli.login import _mask_key\\n\\n        result = _mask_key(_API_KEY)\\n        assert result == _API_KEY[:8] + \\\"...\\\"\\n\\n    def test_key_exactly_8_chars_returns_stars(self):\\n        from lfx.cli.login import _mask_key\\n\\n        result = _mask_key(_EXACT_KEY)\\n        assert result == \\\"***\\\"\\n\\n    def test_short_key_returns_stars(self):\\n        from lfx.cli.login import _mask_key\\n\\n        result = _mask_key(_SHORT_KEY)\\n        assert result == \\\"***\\\"\\n\\n    def test_empty_key_returns_stars(self):\\n        from lfx.cli.login import _mask_key\\n\\n        result = _mask_key(\\\"\\\")\\n        assert result == \\\"***\\\"\\n\\n    def test_exactly_9_chars_key_shows_first_8_plus_ellipsis(self):\\n        from lfx.cli.login import _mask_key\\n\\n        key = \\\"123456789\\\"  # pragma: allowlist secret\\n        result = _mask_key(key)\\n        assert result == \\\"12345678...\\\"\\n\\n    def test_mask_does_not_reveal_full_key(self):\\n        from lfx.cli.login import _mask_key\\n\\n        key = \\\"supersecretkeyvalue\\\"  # pragma: allowlist secret\\n        result = _mask_key(key)\\n        assert key not in result\\n        assert result.endswith(\\\"...\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# _probe_connection\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestProbeConnection:\\n    def test_successful_list_flows_returns_ok(self):\\n        from lfx.cli.login import _probe_connection\\n\\n        flows = [MagicMock(), MagicMock(), MagicMock()]\\n        client = _make_client_mock(flows=flows)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        ok, msg, count = _probe_connection(client, sdk)\\n        assert ok is True\\n        assert msg == \\\"OK\\\"\\n        assert count == 3\\n\\n    def test_empty_flow_list_returns_ok_with_zero_count(self):\\n        from lfx.cli.login import _probe_connection\\n\\n        client = _make_client_mock(flows=[])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        ok, _msg, count = _probe_connection(client, sdk)\\n        assert ok is True\\n        assert count == 0\\n\\n    def test_auth_error_returns_auth_message(self):\\n        from lfx.cli.login import _probe_connection\\n\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = _FakeLangflowAuthError(\\\"unauthorized\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        ok, msg, count = _probe_connection(client, sdk)\\n        assert ok is False\\n        assert msg == \\\"auth\\\"\\n        assert count == 0\\n\\n    def test_connection_error_returns_connection_message(self):\\n        from lfx.cli.login import _probe_connection\\n\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = _FakeLangflowConnectionError(\\\"refused\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        ok, msg, count = _probe_connection(client, sdk)\\n        assert ok is False\\n        assert msg.startswith(\\\"connection:\\\")\\n        assert count == 0\\n\\n    def test_http_error_returns_http_message(self):\\n        from lfx.cli.login import _probe_connection\\n\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = _FakeLangflowHTTPError(503, \\\"service unavailable\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        ok, msg, count = _probe_connection(client, sdk)\\n        assert ok is False\\n        assert msg.startswith(\\\"http:\\\")\\n        assert count == 0\\n\\n    def test_validation_error_qualname_returns_ok(self):\\n        from lfx.cli.login import _probe_connection\\n\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = _FakeValidationError(\\\"schema mismatch\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        ok, msg, count = _probe_connection(client, sdk)\\n        assert ok is True\\n        assert msg == \\\"OK\\\"\\n        assert count == 0\\n\\n    def test_generic_exception_returns_error_message(self):\\n        from lfx.cli.login import _probe_connection\\n\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = RuntimeError(\\\"something went wrong\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        ok, msg, count = _probe_connection(client, sdk)\\n        assert ok is False\\n        assert msg.startswith(\\\"error:\\\")\\n        assert count == 0\\n\\n    def test_connection_error_message_contains_original_message(self):\\n        from lfx.cli.login import _probe_connection\\n\\n        original_msg = \\\"Connection refused at port 7860\\\"\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = _FakeLangflowConnectionError(original_msg)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _, msg, _ = _probe_connection(client, sdk)\\n        assert original_msg in msg\\n\\n    def test_flow_count_matches_returned_list_length(self):\\n        from lfx.cli.login import _probe_connection\\n\\n        flows = [MagicMock() for _ in range(5)]\\n        client = _make_client_mock(flows=flows)\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _, _, count = _probe_connection(client, sdk)\\n        assert count == 5\\n\\n\\n# ---------------------------------------------------------------------------\\n# login_command \u2014 success\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLoginCommandSuccess:\\n    def test_successful_probe_does_not_raise(self):\\n        client = _make_client_mock(flows=[MagicMock()])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_login(sdk_mock=sdk, env_cfg=env_cfg)  # Should not raise\\n\\n    def test_successful_probe_calls_client_list_flows(self):\\n        client = _make_client_mock(flows=[MagicMock()])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_login(sdk_mock=sdk, env_cfg=env_cfg)\\n        client.list_flows.assert_called_once_with(page=1, size=1)\\n\\n    def test_client_constructed_with_resolved_credentials(self):\\n        client = _make_client_mock()\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg(url=_BASE_URL, api_key=_API_KEY)\\n        _run_login(sdk_mock=sdk, env_cfg=env_cfg)\\n        sdk.Client.assert_called_once_with(base_url=_BASE_URL, api_key=_API_KEY)\\n\\n    def test_validation_error_probe_succeeds_without_exit(self):\\n        \\\"\\\"\\\"A ValidationError during list_flows is treated as a successful probe.\\\"\\\"\\\"\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = _FakeValidationError(\\\"schema drift\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        _run_login(sdk_mock=sdk, env_cfg=env_cfg)  # Should not raise\\n\\n\\n# ---------------------------------------------------------------------------\\n# login_command \u2014 auth failure\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLoginCommandAuthFailure:\\n    def test_auth_error_raises_exit_1(self):\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = _FakeLangflowAuthError(\\\"unauthorized\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_login(sdk_mock=sdk, env_cfg=env_cfg)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_auth_failure_with_api_key_includes_masked_key(self):\\n        \\\"\\\"\\\"When auth fails and a key is configured, masked key is shown on stderr.\\\"\\\"\\\"\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = _FakeLangflowAuthError(\\\"forbidden\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg(api_key=_API_KEY)\\n        with pytest.raises(typer.Exit):\\n            _run_login(sdk_mock=sdk, env_cfg=env_cfg)\\n\\n\\n# ---------------------------------------------------------------------------\\n# login_command \u2014 connection failure\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLoginCommandConnectionFailure:\\n    def test_connection_error_raises_exit_1(self):\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = _FakeLangflowConnectionError(\\\"timeout\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_login(sdk_mock=sdk, env_cfg=env_cfg)\\n        assert exc_info.value.exit_code == 1\\n\\n\\n# ---------------------------------------------------------------------------\\n# login_command \u2014 HTTP error\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLoginCommandHTTPError:\\n    def test_http_error_raises_exit_1(self):\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = _FakeLangflowHTTPError(500, \\\"internal server error\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_login(sdk_mock=sdk, env_cfg=env_cfg)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_http_404_raises_exit_1(self):\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = _FakeLangflowHTTPError(404, \\\"not found\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_login(sdk_mock=sdk, env_cfg=env_cfg)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_generic_error_raises_exit_1(self):\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = RuntimeError(\\\"unexpected\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg()\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_login(sdk_mock=sdk, env_cfg=env_cfg)\\n        assert exc_info.value.exit_code == 1\\n\\n\\n# ---------------------------------------------------------------------------\\n# login_command \u2014 config error\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLoginCommandConfigError:\\n    def test_config_error_raises_exit_1(self):\\n        from lfx.cli.login import login_command\\n        from lfx.config import ConfigError\\n\\n        sdk = _make_sdk_mock()\\n        with (\\n            patch(\\\"lfx.cli.login.load_sdk\\\", return_value=sdk),\\n            patch(\\\"lfx.config.resolve_environment\\\", side_effect=ConfigError(\\\"no such env\\\")),\\n            pytest.raises(typer.Exit) as exc_info,\\n        ):\\n            login_command(\\n                env=\\\"nonexistent\\\",\\n                environments_file=None,\\n                target=None,\\n                api_key=None,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_missing_environments_file_raises_exit_1(self, tmp_path):\\n        from lfx.cli.login import login_command\\n\\n        sdk = _make_sdk_mock()\\n        missing_file = str(tmp_path / \\\"no_such.yaml\\\")\\n        with (\\n            patch(\\\"lfx.cli.login.load_sdk\\\", return_value=sdk),\\n            pytest.raises(typer.Exit),\\n        ):\\n            login_command(\\n                env=\\\"myenv\\\",\\n                environments_file=missing_file,\\n                target=None,\\n                api_key=None,\\n            )\\n\\n\\n# ---------------------------------------------------------------------------\\n# login_command \u2014 no API key\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLoginCommandNoApiKey:\\n    def test_no_api_key_does_not_exit_early_on_success(self):\\n        \\\"\\\"\\\"When api_key is None, login still proceeds and succeeds if probe passes.\\\"\\\"\\\"\\n        client = _make_client_mock(flows=[MagicMock()])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg(api_key=None, name=\\\"staging\\\")\\n        _run_login(sdk_mock=sdk, env_cfg=env_cfg)  # Should not raise\\n        client.list_flows.assert_called_once()\\n\\n    def test_no_api_key_inline_env_does_not_exit_early(self):\\n        \\\"\\\"\\\"__inline__ env with no key still probes without raising.\\\"\\\"\\\"\\n        client = _make_client_mock(flows=[])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg(api_key=None, name=\\\"__inline__\\\")\\n        _run_login(sdk_mock=sdk, env_cfg=env_cfg)  # Should not raise\\n\\n    def test_no_api_key_env_env_does_not_exit_early(self):\\n        \\\"\\\"\\\"__env__ special name with no key still proceeds.\\\"\\\"\\\"\\n        client = _make_client_mock(flows=[])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg(api_key=None, name=\\\"__env__\\\")\\n        _run_login(sdk_mock=sdk, env_cfg=env_cfg)  # Should not raise\\n\\n    def test_no_api_key_client_still_constructed(self):\\n        \\\"\\\"\\\"Client is constructed even without an API key.\\\"\\\"\\\"\\n        client = _make_client_mock()\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg(api_key=None)\\n        _run_login(sdk_mock=sdk, env_cfg=env_cfg)\\n        sdk.Client.assert_called_once_with(base_url=_BASE_URL, api_key=None)\\n\\n\\n# ---------------------------------------------------------------------------\\n# login_command \u2014 SDK not installed\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLoginCommandSdkNotInstalled:\\n    def test_sdk_load_raises_bad_parameter(self):\\n        from lfx.cli.login import login_command\\n\\n        with (\\n            patch(\\n                \\\"lfx.cli.login.load_sdk\\\",\\n                side_effect=typer.BadParameter(\\\"langflow-sdk is required for lfx login\\\"),\\n            ),\\n            pytest.raises(typer.BadParameter),\\n        ):\\n            login_command(\\n                env=\\\"staging\\\",\\n                environments_file=None,\\n                target=None,\\n                api_key=None,\\n            )\\n\\n    def test_sdk_load_bad_parameter_message(self):\\n        from lfx.cli.login import login_command\\n\\n        with (\\n            patch(\\n                \\\"lfx.cli.login.load_sdk\\\",\\n                side_effect=typer.BadParameter(\\\"langflow-sdk is required\\\"),\\n            ),\\n            pytest.raises(typer.BadParameter) as exc_info,\\n        ):\\n            login_command(\\n                env=\\\"staging\\\",\\n                environments_file=None,\\n                target=None,\\n                api_key=None,\\n            )\\n        assert \\\"langflow-sdk\\\" in str(exc_info.value)\\n\\n\\n# ---------------------------------------------------------------------------\\n# login_command \u2014 inline / env-var environment behaviour\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLoginCommandInlineEnv:\\n    def test_inline_env_success_does_not_raise(self):\\n        client = _make_client_mock()\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg(name=\\\"__inline__\\\")\\n        _run_login(env=None, target=_BASE_URL, api_key=_API_KEY, sdk_mock=sdk, env_cfg=env_cfg)\\n\\n    def test_env_var_env_success_does_not_raise(self):\\n        client = _make_client_mock()\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg(name=\\\"__env__\\\")\\n        _run_login(env=None, target=_BASE_URL, api_key=_API_KEY, sdk_mock=sdk, env_cfg=env_cfg)\\n\\n    def test_named_env_success_does_not_raise(self):\\n        client = _make_client_mock()\\n        sdk = _make_sdk_mock(client_mock=client)\\n        env_cfg = _make_env_cfg(name=\\\"production\\\")\\n        _run_login(env=\\\"production\\\", sdk_mock=sdk, env_cfg=env_cfg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_prewarm_command.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a836cc0e7da5dfb3cc0d78117b3acdb251c16ba90200ae370a72f215669b7b20\",\"content\":\"\\\"\\\"\\\"Unit tests for the ``lfx prewarm`` command. Runs in-process.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom lfx.__main__ import app\\nfrom typer.testing import CliRunner\\n\\nrunner = CliRunner()\\n\\n\\ndef test_prewarm_command_runs_and_reports_summary():\\n    \\\"\\\"\\\"`lfx prewarm` imports the core set and prints a one-line summary.\\\"\\\"\\\"\\n    result = runner.invoke(app, [\\\"prewarm\\\"])\\n\\n    assert result.exit_code == 0, result.stdout\\n    # Summary reports how many modules were imported.\\n    assert \\\"imported\\\" in result.stdout.lower()\\n\\n\\ndef test_prewarm_appears_in_help():\\n    \\\"\\\"\\\"The command is discoverable from top-level help.\\\"\\\"\\\"\\n    result = runner.invoke(app, [\\\"--help\\\"])\\n\\n    assert result.exit_code == 0\\n    assert \\\"prewarm\\\" in result.stdout\\n\\n\\ndef test_prewarm_freeze_flag_accepted():\\n    \\\"\\\"\\\"`--freeze` is a valid flag and the command still succeeds.\\\"\\\"\\\"\\n    import gc\\n\\n    try:\\n        result = runner.invoke(app, [\\\"prewarm\\\", \\\"--freeze\\\"])\\n\\n        assert result.exit_code == 0, result.stdout\\n    finally:\\n        # The command froze the heap for real; don't leak that into other tests.\\n        gc.unfreeze()\\n\\n\\ndef test_dangerous_run_flag_replaces_plain_run():\\n    \\\"\\\"\\\"The execute path is gated behind an explicit, alarming flag \u2014 not a tame --run.\\\"\\\"\\\"\\n    # The tame, easy-to-fat-finger flag must not exist.\\n    assert runner.invoke(app, [\\\"prewarm\\\", \\\"--run\\\", \\\"--skip-run\\\"]).exit_code != 0\\n    # The explicit dangerous flag parses (no --flow given, so nothing actually executes).\\n    ok = runner.invoke(app, [\\\"prewarm\\\", \\\"--skip-run\\\", \\\"--unsafe-run-may-leak-connections\\\"])\\n    assert ok.exit_code == 0, ok.stdout\\n\\n\\ndef test_prewarm_survives_a_teardown_less_service_already_in_the_manager():\\n    \\\"\\\"\\\"A warmed process that already holds the shared component cache still exits 0.\\n\\n    Any ``ComponentWithCache`` (every MCP component, the run-flow tool) registers the\\n    shared component cache on construction, and that service implements a plain cache\\n    protocol with no ``teardown``. Fork-safety teardown must skip it rather than count\\n    it as a disposal failure and fail the command.\\n    \\\"\\\"\\\"\\n    from lfx.services.deps import get_shared_component_cache_service\\n\\n    get_shared_component_cache_service()\\n\\n    result = runner.invoke(app, [\\\"prewarm\\\"])\\n\\n    assert result.exit_code == 0, result.stderr\\n    assert \\\"Disposed warm services\\\" in result.stdout\\n\\n\\ndef test_prewarm_disposes_services_on_fork_safe_path():\\n    \\\"\\\"\\\"The default (fork-safe) path tears warmed services down before returning.\\\"\\\"\\\"\\n    result = runner.invoke(app, [\\\"prewarm\\\"])\\n\\n    assert result.exit_code == 0, result.stdout\\n    assert \\\"Disposed warm services\\\" in result.stdout\\n\\n\\ndef test_unsafe_run_skips_service_teardown():\\n    \\\"\\\"\\\"--unsafe-run keeps live connections (Firecracker), so no teardown happens.\\\"\\\"\\\"\\n    result = runner.invoke(app, [\\\"prewarm\\\", \\\"--skip-run\\\", \\\"--unsafe-run-may-leak-connections\\\"])\\n\\n    assert result.exit_code == 0, result.stdout\\n    assert \\\"Disposed warm services\\\" not in result.stdout\\n\\n\\ndef _write_hermetic_flow(tmp_path):\\n    \\\"\\\"\\\"Write a model-free ChatInput -> Prompt -> ChatOutput flow and return its path.\\\"\\\"\\\"\\n    import json\\n\\n    from lfx.components.input_output import ChatInput, ChatOutput\\n    from lfx.components.models_and_agents import PromptComponent\\n    from lfx.graph.graph.base import Graph\\n\\n    ci = ChatInput(_id=\\\"ci\\\")\\n    pr = PromptComponent(_id=\\\"pr\\\")\\n    pr.set(template=\\\"{m}\\\", m=ci.message_response)\\n    co = ChatOutput(_id=\\\"co\\\")\\n    co.set(input_value=pr.build_prompt)\\n    flow_path = tmp_path / \\\"hermetic.json\\\"\\n    flow_path.write_text(json.dumps(Graph(ci, co).dump(name=\\\"hermetic\\\")))\\n    return flow_path\\n\\n\\ndef test_prewarm_flow_build_only(tmp_path):\\n    \\\"\\\"\\\"`--flow` builds the given flow (no --run = no execution).\\\"\\\"\\\"\\n    flow_path = _write_hermetic_flow(tmp_path)\\n\\n    result = runner.invoke(app, [\\\"prewarm\\\", \\\"--skip-run\\\", \\\"--flow\\\", str(flow_path)])\\n\\n    assert result.exit_code == 0, result.stdout\\n    assert \\\"built\\\" in result.stdout\\n\\n\\ndef test_prewarm_warns_when_a_run_leaves_fork_unsafe_state(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"If a --flow run leaves ghost threads/connections, the CLI must emit the warning.\\n\\n    This is the user-facing safety signal (\\\"do NOT capture this before a fork\\\"); a clean\\n    model-free flow never triggers it, so inject a dirty result to exercise the path.\\n    \\\"\\\"\\\"\\n    import lfx.preload as preload_mod\\n\\n    flow_path = _write_hermetic_flow(tmp_path)\\n\\n    def _dirty_flow(*_args, **_kwargs):\\n        return preload_mod.FlowPrewarmResult(\\n            built=True, ran=True, ghost_threads=[\\\"leaked-worker\\\"], ghost_connections=[\\\"a->b (ESTABLISHED)\\\"]\\n        )\\n\\n    monkeypatch.setattr(preload_mod, \\\"prewarm_flow\\\", _dirty_flow)\\n\\n    result = runner.invoke(\\n        app, [\\\"prewarm\\\", \\\"--skip-run\\\", \\\"--flow\\\", str(flow_path), \\\"--unsafe-run-may-leak-connections\\\"]\\n    )\\n\\n    # A dirty --unsafe-run is expected (Firecracker), so it still exits 0 \u2014 but must warn loudly.\\n    assert result.exit_code == 0, result.stdout\\n    # The warning is emitted to stderr (err=True).\\n    assert \\\"fork-unsafe\\\" in result.stderr\\n    assert \\\"leaked-worker\\\" in result.stderr\\n\\n\\ndef test_prewarm_warns_about_fork_unsafe_state_even_when_run_errored(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"A run that leaves ghost state AND errors mid-run must still emit the fork-unsafe warning.\\n\\n    --unsafe-run skips teardown, so dirty state left by a failed run would otherwise go\\n    unannounced \u2014 the warning must not be gated behind the success branch.\\n    \\\"\\\"\\\"\\n    import lfx.preload as preload_mod\\n\\n    flow_path = _write_hermetic_flow(tmp_path)\\n\\n    def _dirty_and_errored(*_args, **_kwargs):\\n        return preload_mod.FlowPrewarmResult(\\n            built=True, ran=True, error=\\\"RuntimeError: boom\\\", ghost_connections=[\\\"a->b (ESTABLISHED)\\\"]\\n        )\\n\\n    monkeypatch.setattr(preload_mod, \\\"prewarm_flow\\\", _dirty_and_errored)\\n\\n    result = runner.invoke(\\n        app, [\\\"prewarm\\\", \\\"--skip-run\\\", \\\"--flow\\\", str(flow_path), \\\"--unsafe-run-may-leak-connections\\\"]\\n    )\\n\\n    assert result.exit_code == 1  # the error still fails the command\\n    assert \\\"FAIL flow\\\" in result.stderr  # error is reported\\n    assert \\\"fork-unsafe\\\" in result.stderr  # ...and the dirty-state warning still fires\\n\\n\\ndef test_prewarm_verbose_lists_imported_components():\\n    \\\"\\\"\\\"`--verbose` lists each imported component, not just the summary count.\\\"\\\"\\\"\\n    result = runner.invoke(app, [\\\"prewarm\\\", \\\"--skip-run\\\", \\\"--verbose\\\"])\\n\\n    assert result.exit_code == 0, result.stdout\\n    assert \\\"ok\\\" in result.stdout\\n    assert \\\"ChatInput\\\" in result.stdout\\n\\n\\ndef test_prewarm_unsafe_run_executes_flow_end_to_end(tmp_path):\\n    \\\"\\\"\\\"`--unsafe-run` fully executes the flow; a model-free flow runs clean (no warning).\\\"\\\"\\\"\\n    flow_path = _write_hermetic_flow(tmp_path)\\n\\n    result = runner.invoke(\\n        app, [\\\"prewarm\\\", \\\"--skip-run\\\", \\\"--flow\\\", str(flow_path), \\\"--unsafe-run-may-leak-connections\\\"]\\n    )\\n\\n    assert result.exit_code == 0, result.stdout\\n    assert \\\"built+ran\\\" in result.stdout\\n    # --unsafe-run intentionally keeps live state, so no service teardown happens.\\n    assert \\\"Disposed warm services\\\" not in result.stdout\\n    # (Connection-cleanliness of a model-free run is asserted at the library level in\\n    # test_prewarm_flow_run_reports_fork_safety; the CLI's fork-unsafe warning reflects\\n    # process-global state \u2014 incl. harness threads \u2014 so it's not asserted here.)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_pull_command.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"024c31d57a17bbdb13737ae024c9dd449dc6ddb116eed2cae7152e0e3c07bd94\",\"content\":\"\\\"\\\"\\\"Unit tests for lfx pull -- pull_command and helpers.\\n\\nAll tests run entirely in-process; no real Langflow instance or SDK required.\\nThe SDK module is replaced wholesale with MagicMock so only the pull logic\\n(flow fetching, file writing, project resolution, result rendering)\\nis under test.\\n\\\"\\\"\\\"\\n# pragma: allowlist secret -- all credentials in this file are fake test data\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom types import SimpleNamespace\\nfrom typing import TYPE_CHECKING\\nfrom unittest.mock import MagicMock, patch\\nfrom uuid import UUID\\n\\nimport pytest\\nimport typer\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n# ---------------------------------------------------------------------------\\n# Shared constants\\n# ---------------------------------------------------------------------------\\n\\n_BASE_URL = \\\"http://langflow.test\\\"\\n_API_KEY = \\\"test-key\\\"  # pragma: allowlist secret\\n_FLOW_ID = UUID(\\\"aaaaaaaa-0000-0000-0000-000000000001\\\")\\n_FLOW_ID_2 = UUID(\\\"aaaaaaaa-0000-0000-0000-000000000002\\\")\\n_PROJECT_ID = UUID(\\\"bbbbbbbb-0000-0000-0000-000000000001\\\")\\n\\n_FLOW_DICT: dict = {\\n    \\\"id\\\": str(_FLOW_ID),\\n    \\\"name\\\": \\\"My Flow\\\",\\n    \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n}\\n\\n_FLOW_DICT_2: dict = {\\n    \\\"id\\\": str(_FLOW_ID_2),\\n    \\\"name\\\": \\\"Second Flow\\\",\\n    \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n}\\n\\n_FLOW_JSON = json.dumps(_FLOW_DICT, indent=2)\\n_FLOW_JSON_2 = json.dumps(_FLOW_DICT_2, indent=2)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Test helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _fake_env_config(\\n    url: str = _BASE_URL,\\n    api_key: str = _API_KEY,\\n    name: str = \\\"local\\\",\\n) -> MagicMock:\\n    \\\"\\\"\\\"Return a MagicMock that looks like a resolved EnvironmentConfig.\\\"\\\"\\\"\\n    cfg = MagicMock()\\n    cfg.url = url\\n    cfg.api_key = api_key\\n    cfg.name = name\\n    return cfg\\n\\n\\ndef _fake_flow_obj(\\n    flow_id: UUID = _FLOW_ID,\\n    name: str = \\\"My Flow\\\",\\n    flow_dict: dict | None = None,\\n) -> MagicMock:\\n    \\\"\\\"\\\"Return a MagicMock that looks like a langflow_sdk Flow object.\\\"\\\"\\\"\\n    flow = MagicMock()\\n    flow.id = flow_id\\n    flow.name = name\\n    flow.model_dump.return_value = flow_dict if flow_dict is not None else _FLOW_DICT\\n    return flow\\n\\n\\ndef _fake_project(\\n    name: str = \\\"My Project\\\",\\n    project_id: UUID = _PROJECT_ID,\\n    flows: list | None = None,\\n) -> MagicMock:\\n    \\\"\\\"\\\"Return a MagicMock that looks like a langflow_sdk Project object.\\\"\\\"\\\"\\n    proj = MagicMock()\\n    proj.name = name\\n    proj.id = project_id\\n    proj.flows = flows if flows is not None else []\\n    return proj\\n\\n\\ndef _fake_project_summary(\\n    name: str = \\\"My Project\\\",\\n    project_id: UUID = _PROJECT_ID,\\n) -> SimpleNamespace:\\n    \\\"\\\"\\\"Return a lightweight project summary like sdk.list_projects() provides.\\\"\\\"\\\"\\n    return SimpleNamespace(name=name, id=project_id)\\n\\n\\ndef _make_client_mock(flows: list | None = None) -> MagicMock:\\n    \\\"\\\"\\\"Return a mock SDK client pre-configured for common pull scenarios.\\\"\\\"\\\"\\n    client = MagicMock()\\n    client.list_flows.return_value = flows if flows is not None else []\\n    client.list_projects.return_value = []\\n    return client\\n\\n\\ndef _make_sdk_mock(\\n    client_mock: MagicMock | None = None,\\n    flow_json: str | None = None,\\n) -> MagicMock:\\n    \\\"\\\"\\\"Return a mock langflow_sdk module wired to client_mock.\\\"\\\"\\\"\\n    if client_mock is None:\\n        client_mock = _make_client_mock()\\n\\n    sdk = MagicMock()\\n    sdk.Client.return_value = client_mock\\n    sdk.normalize_flow.side_effect = lambda d, **_kw: d\\n    sdk.flow_to_json.return_value = flow_json if flow_json is not None else _FLOW_JSON\\n    return sdk\\n\\n\\ndef _run_pull(\\n    *,\\n    tmp_path: Path | None = None,  # noqa: ARG001 \u2014 kept for call-site readability\\n    env: str | None = None,\\n    output_dir: str | None = None,\\n    flow_id: str | None = None,\\n    project: str | None = None,\\n    project_id: str | None = None,\\n    environments_file: str | None = None,\\n    strip_secrets: bool = False,\\n    indent: int = 2,\\n    sdk_mock: MagicMock | None = None,\\n    env_cfg: MagicMock | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Invoke pull_command with mocked SDK and env resolution.\\\"\\\"\\\"\\n    from lfx.cli.pull import pull_command\\n\\n    mock_sdk = sdk_mock if sdk_mock is not None else _make_sdk_mock()\\n    mock_cfg = env_cfg if env_cfg is not None else _fake_env_config()\\n\\n    with (\\n        patch(\\\"lfx.cli.pull.load_sdk\\\", return_value=mock_sdk),\\n        patch(\\\"lfx.config.resolve_environment\\\", return_value=mock_cfg),\\n    ):\\n        pull_command(\\n            env=env,\\n            output_dir=output_dir,\\n            flow_id=flow_id,\\n            project=project,\\n            project_id=project_id,\\n            environments_file=environments_file,\\n            target=_BASE_URL,\\n            api_key=_API_KEY,\\n            strip_secrets=strip_secrets,\\n            indent=indent,\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# _safe_filename\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestSafeFilename:\\n    def test_alphanumeric_passthrough(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        assert _safe_filename(\\\"MyFlow123\\\") == \\\"MyFlow123\\\"\\n\\n    def test_spaces_become_underscores(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        assert _safe_filename(\\\"My Flow\\\") == \\\"My_Flow\\\"\\n\\n    def test_multiple_spaces_become_underscores(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        assert _safe_filename(\\\"a b c\\\") == \\\"a_b_c\\\"\\n\\n    def test_special_chars_become_underscores(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        result = _safe_filename(\\\"flow@version#1!\\\")\\n        assert \\\"@\\\" not in result\\n        assert \\\"#\\\" not in result\\n        assert \\\"!\\\" not in result\\n\\n    def test_leading_whitespace_stripped(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        assert _safe_filename(\\\"  My Flow\\\") == \\\"My_Flow\\\"\\n\\n    def test_trailing_whitespace_stripped(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        assert _safe_filename(\\\"My Flow  \\\") == \\\"My_Flow\\\"\\n\\n    def test_both_ends_stripped(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        assert _safe_filename(\\\"  My Flow  \\\") == \\\"My_Flow\\\"\\n\\n    def test_hyphens_preserved(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        assert _safe_filename(\\\"my-flow\\\") == \\\"my-flow\\\"\\n\\n    def test_underscores_preserved(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        assert _safe_filename(\\\"my_flow\\\") == \\\"my_flow\\\"\\n\\n    def test_empty_string_returns_empty(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        assert _safe_filename(\\\"\\\") == \\\"\\\"\\n\\n    def test_slash_becomes_underscore(self):\\n        from lfx.cli.common import safe_filename as _safe_filename\\n\\n        result = _safe_filename(\\\"flows/version\\\")\\n        assert \\\"/\\\" not in result\\n\\n\\n# ---------------------------------------------------------------------------\\n# _write_flow helper\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestWriteFlow:\\n    def test_status_created_when_file_does_not_exist(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj()\\n        sdk = _make_sdk_mock()\\n        result = _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=2)\\n        assert result.status == \\\"created\\\"\\n\\n    def test_status_updated_when_file_exists_with_different_content(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj()\\n        sdk = _make_sdk_mock(flow_json=_FLOW_JSON)\\n        # Write different content first\\n        (tmp_path / \\\"My_Flow.json\\\").write_text(\\\"old content\\\", encoding=\\\"utf-8\\\")\\n        result = _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=2)\\n        assert result.status == \\\"updated\\\"\\n\\n    def test_status_unchanged_when_file_exists_with_same_content(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj()\\n        sdk = _make_sdk_mock(flow_json=_FLOW_JSON)\\n        # Write identical content first\\n        (tmp_path / \\\"My_Flow.json\\\").write_text(_FLOW_JSON, encoding=\\\"utf-8\\\")\\n        result = _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=2)\\n        assert result.status == \\\"unchanged\\\"\\n\\n    def test_status_error_when_normalize_raises(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj()\\n        sdk = _make_sdk_mock()\\n        sdk.normalize_flow.side_effect = RuntimeError(\\\"normalize failed\\\")\\n        result = _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=2)\\n        assert result.status == \\\"error\\\"\\n        assert result.error is not None\\n        assert \\\"normalize failed\\\" in result.error\\n\\n    def test_error_result_is_not_ok(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj()\\n        sdk = _make_sdk_mock()\\n        sdk.normalize_flow.side_effect = RuntimeError(\\\"boom\\\")\\n        result = _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=2)\\n        assert result.ok is False\\n\\n    def test_written_file_has_correct_content(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj()\\n        expected_content = json.dumps(_FLOW_DICT, indent=4)\\n        sdk = _make_sdk_mock(flow_json=expected_content)\\n        result = _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=4)\\n        assert result.path.exists()\\n        assert result.path.read_text(encoding=\\\"utf-8\\\") == expected_content\\n\\n    def test_file_not_written_when_unchanged(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj()\\n        sdk = _make_sdk_mock(flow_json=_FLOW_JSON)\\n        out_path = tmp_path / \\\"My_Flow.json\\\"\\n        out_path.write_text(_FLOW_JSON, encoding=\\\"utf-8\\\")\\n        mtime_before = out_path.stat().st_mtime\\n        _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=2)\\n        assert out_path.stat().st_mtime == mtime_before\\n\\n    def test_result_contains_correct_flow_id(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj(flow_id=_FLOW_ID)\\n        sdk = _make_sdk_mock()\\n        result = _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=2)\\n        assert result.flow_id == _FLOW_ID\\n\\n    def test_result_contains_correct_flow_name(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj(name=\\\"Special Flow\\\")\\n        sdk = _make_sdk_mock()\\n        result = _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=2)\\n        assert result.flow_name == \\\"Special Flow\\\"\\n\\n    def test_normalize_called_with_strip_secrets_true(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj()\\n        sdk = _make_sdk_mock()\\n        _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=True, indent=2)\\n        sdk.normalize_flow.assert_called_once()\\n        call_kwargs = sdk.normalize_flow.call_args.kwargs\\n        assert call_kwargs.get(\\\"strip_secrets\\\") is True\\n\\n    def test_normalize_called_with_strip_secrets_false(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj()\\n        sdk = _make_sdk_mock()\\n        _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=2)\\n        call_kwargs = sdk.normalize_flow.call_args.kwargs\\n        assert call_kwargs.get(\\\"strip_secrets\\\") is False\\n\\n    def test_flow_to_json_called_with_indent(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj()\\n        sdk = _make_sdk_mock()\\n        _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=4)\\n        sdk.flow_to_json.assert_called_once()\\n        call_kwargs = sdk.flow_to_json.call_args.kwargs\\n        assert call_kwargs.get(\\\"indent\\\") == 4\\n\\n    def test_error_result_has_dummy_path(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj(flow_id=_FLOW_ID)\\n        sdk = _make_sdk_mock()\\n        sdk.normalize_flow.side_effect = RuntimeError(\\\"fail\\\")\\n        result = _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=2)\\n        assert str(_FLOW_ID) in str(result.path)\\n\\n    def test_logs_debug_when_write_fails(self, tmp_path: Path):\\n        from lfx.cli.pull import _write_flow\\n\\n        flow = _fake_flow_obj(flow_id=_FLOW_ID)\\n        sdk = _make_sdk_mock()\\n        sdk.normalize_flow.side_effect = RuntimeError(\\\"fail\\\")\\n\\n        with patch(\\\"lfx.cli.pull.logger\\\") as mock_logger:\\n            _write_flow(flow, sdk=sdk, dest_dir=tmp_path, strip_secrets=False, indent=2)\\n\\n        mock_logger.debug.assert_called_once_with(\\\"Failed to write flow %s\\\", _FLOW_ID, exc_info=True)\\n\\n\\n# ---------------------------------------------------------------------------\\n# PullResult\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestPullResult:\\n    def test_created_is_ok(self, tmp_path: Path):\\n        from lfx.cli.pull import PullResult\\n\\n        r = PullResult(flow_id=_FLOW_ID, flow_name=\\\"F\\\", path=tmp_path / \\\"f.json\\\", status=\\\"created\\\")\\n        assert r.ok is True\\n\\n    def test_updated_is_ok(self, tmp_path: Path):\\n        from lfx.cli.pull import PullResult\\n\\n        r = PullResult(flow_id=_FLOW_ID, flow_name=\\\"F\\\", path=tmp_path / \\\"f.json\\\", status=\\\"updated\\\")\\n        assert r.ok is True\\n\\n    def test_unchanged_is_ok(self, tmp_path: Path):\\n        from lfx.cli.pull import PullResult\\n\\n        r = PullResult(flow_id=_FLOW_ID, flow_name=\\\"F\\\", path=tmp_path / \\\"f.json\\\", status=\\\"unchanged\\\")\\n        assert r.ok is True\\n\\n    def test_error_is_not_ok(self, tmp_path: Path):\\n        from lfx.cli.pull import PullResult\\n\\n        r = PullResult(flow_id=_FLOW_ID, flow_name=\\\"F\\\", path=tmp_path / \\\"f.json\\\", status=\\\"error\\\", error=\\\"timeout\\\")\\n        assert r.ok is False\\n\\n    def test_error_message_stored(self, tmp_path: Path):\\n        from lfx.cli.pull import PullResult\\n\\n        r = PullResult(flow_id=_FLOW_ID, flow_name=\\\"F\\\", path=tmp_path / \\\"f.json\\\", status=\\\"error\\\", error=\\\"some error\\\")\\n        assert r.error == \\\"some error\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# pull_command \u2014 single flow by ID\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestPullCommandSingleFlow:\\n    def test_file_is_written_to_output_dir(self, tmp_path: Path):\\n        flow = _fake_flow_obj()\\n        client = _make_client_mock()\\n        client.get_flow.return_value = flow\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _run_pull(tmp_path=tmp_path, flow_id=str(_FLOW_ID), output_dir=str(tmp_path), sdk_mock=sdk)\\n        json_files = list(tmp_path.glob(\\\"*.json\\\"))\\n        assert len(json_files) == 1\\n\\n    def test_uses_correct_flow_id_uuid(self, tmp_path: Path):\\n        flow = _fake_flow_obj()\\n        client = _make_client_mock()\\n        client.get_flow.return_value = flow\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _run_pull(tmp_path=tmp_path, flow_id=str(_FLOW_ID), output_dir=str(tmp_path), sdk_mock=sdk)\\n        client.get_flow.assert_called_once_with(_FLOW_ID)\\n\\n    def test_exits_0_on_success(self, tmp_path: Path):\\n        \\\"\\\"\\\"pull_command should not raise typer.Exit on success.\\\"\\\"\\\"\\n        flow = _fake_flow_obj()\\n        client = _make_client_mock()\\n        client.get_flow.return_value = flow\\n        sdk = _make_sdk_mock(client_mock=client)\\n        # Should not raise\\n        _run_pull(tmp_path=tmp_path, flow_id=str(_FLOW_ID), output_dir=str(tmp_path), sdk_mock=sdk)\\n\\n    def test_exits_1_if_get_flow_raises(self, tmp_path: Path):\\n        client = _make_client_mock()\\n        client.get_flow.side_effect = RuntimeError(\\\"not found\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_pull(tmp_path=tmp_path, flow_id=str(_FLOW_ID), output_dir=str(tmp_path), sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_single_flow_write_error_exits_1(self, tmp_path: Path):\\n        flow = _fake_flow_obj()\\n        client = _make_client_mock()\\n        client.get_flow.return_value = flow\\n        sdk = _make_sdk_mock(client_mock=client)\\n        sdk.normalize_flow.side_effect = RuntimeError(\\\"normalize failed\\\")\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_pull(tmp_path=tmp_path, flow_id=str(_FLOW_ID), output_dir=str(tmp_path), sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n\\n# ---------------------------------------------------------------------------\\n# pull_command \u2014 project by name\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestPullCommandProjectByName:\\n    def test_resolves_project_from_list_projects(self, tmp_path: Path):\\n        flow = _fake_flow_obj()\\n        proj = _fake_project(name=\\\"My Project\\\", flows=[flow])\\n        client = _make_client_mock()\\n        client.list_projects.return_value = [_fake_project_summary(name=\\\"My Project\\\", project_id=proj.id)]\\n        client.get_project.return_value = proj\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _run_pull(tmp_path=tmp_path, project=\\\"My Project\\\", output_dir=str(tmp_path), sdk_mock=sdk)\\n        client.list_projects.assert_called_once()\\n        client.get_project.assert_called_once_with(proj.id)\\n\\n    def test_exits_1_if_project_name_not_found(self, tmp_path: Path):\\n        client = _make_client_mock()\\n        client.list_projects.return_value = [_fake_project_summary(name=\\\"Other Project\\\")]\\n        sdk = _make_sdk_mock(client_mock=client)\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_pull(tmp_path=tmp_path, project=\\\"Nonexistent\\\", output_dir=str(tmp_path), sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_exits_1_when_no_projects_exist(self, tmp_path: Path):\\n        client = _make_client_mock()\\n        client.list_projects.return_value = []\\n        sdk = _make_sdk_mock(client_mock=client)\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_pull(tmp_path=tmp_path, project=\\\"My Project\\\", output_dir=str(tmp_path), sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_writes_all_flows_in_project(self, tmp_path: Path):\\n        flow1 = _fake_flow_obj(flow_id=_FLOW_ID, name=\\\"Flow One\\\")\\n        flow2 = _fake_flow_obj(flow_id=_FLOW_ID_2, name=\\\"Flow Two\\\")\\n        proj = _fake_project(name=\\\"My Project\\\", flows=[flow1, flow2])\\n        client = _make_client_mock()\\n        client.list_projects.return_value = [_fake_project_summary(name=\\\"My Project\\\", project_id=proj.id)]\\n        client.get_project.return_value = proj\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _run_pull(tmp_path=tmp_path, project=\\\"My Project\\\", output_dir=str(tmp_path), sdk_mock=sdk)\\n        assert sdk.normalize_flow.call_count == 2\\n\\n    def test_uses_first_matching_project(self, tmp_path: Path):\\n        proj1 = _fake_project(name=\\\"My Project\\\", project_id=_PROJECT_ID, flows=[_fake_flow_obj()])\\n        proj2 = _fake_project(\\n            name=\\\"My Project\\\",\\n            project_id=UUID(\\\"bbbbbbbb-0000-0000-0000-000000000002\\\"),\\n            flows=[],\\n        )\\n        client = _make_client_mock()\\n        client.list_projects.return_value = [\\n            _fake_project_summary(name=\\\"My Project\\\", project_id=proj1.id),\\n            _fake_project_summary(name=\\\"My Project\\\", project_id=proj2.id),\\n        ]\\n        client.get_project.return_value = proj1\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _run_pull(tmp_path=tmp_path, project=\\\"My Project\\\", output_dir=str(tmp_path), sdk_mock=sdk)\\n        # Only flows from proj1 are written (1 flow)\\n        assert sdk.normalize_flow.call_count == 1\\n\\n    def test_exits_1_if_get_project_for_name_raises(self, tmp_path: Path):\\n        client = _make_client_mock()\\n        client.list_projects.return_value = [_fake_project_summary(name=\\\"My Project\\\", project_id=_PROJECT_ID)]\\n        client.get_project.side_effect = RuntimeError(\\\"boom\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_pull(tmp_path=tmp_path, project=\\\"My Project\\\", output_dir=str(tmp_path), sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n\\n# ---------------------------------------------------------------------------\\n# pull_command \u2014 project by ID\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestPullCommandProjectById:\\n    def test_uses_get_project_with_uuid(self, tmp_path: Path):\\n        proj = _fake_project(flows=[_fake_flow_obj()])\\n        client = _make_client_mock()\\n        client.get_project.return_value = proj\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _run_pull(\\n            tmp_path=tmp_path,\\n            project_id=str(_PROJECT_ID),\\n            output_dir=str(tmp_path),\\n            sdk_mock=sdk,\\n        )\\n        client.get_project.assert_called_once_with(_PROJECT_ID)\\n\\n    def test_exits_1_if_get_project_raises(self, tmp_path: Path):\\n        client = _make_client_mock()\\n        client.get_project.side_effect = RuntimeError(\\\"not found\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_pull(\\n                tmp_path=tmp_path,\\n                project_id=str(_PROJECT_ID),\\n                output_dir=str(tmp_path),\\n                sdk_mock=sdk,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_skips_list_projects_when_project_id_given(self, tmp_path: Path):\\n        proj = _fake_project(flows=[_fake_flow_obj()])\\n        client = _make_client_mock()\\n        client.get_project.return_value = proj\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _run_pull(\\n            tmp_path=tmp_path,\\n            project_id=str(_PROJECT_ID),\\n            output_dir=str(tmp_path),\\n            sdk_mock=sdk,\\n        )\\n        client.list_projects.assert_not_called()\\n\\n    def test_writes_flows_from_fetched_project(self, tmp_path: Path):\\n        flow1 = _fake_flow_obj(flow_id=_FLOW_ID, name=\\\"Alpha\\\")\\n        flow2 = _fake_flow_obj(flow_id=_FLOW_ID_2, name=\\\"Beta\\\")\\n        proj = _fake_project(flows=[flow1, flow2])\\n        client = _make_client_mock()\\n        client.get_project.return_value = proj\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _run_pull(\\n            tmp_path=tmp_path,\\n            project_id=str(_PROJECT_ID),\\n            output_dir=str(tmp_path),\\n            sdk_mock=sdk,\\n        )\\n        assert sdk.normalize_flow.call_count == 2\\n\\n\\n# ---------------------------------------------------------------------------\\n# pull_command \u2014 all flows\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestPullCommandAllFlows:\\n    def test_calls_list_flows_with_correct_args(self, tmp_path: Path):\\n        client = _make_client_mock(flows=[_fake_flow_obj()])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _run_pull(tmp_path=tmp_path, output_dir=str(tmp_path), sdk_mock=sdk)\\n        client.list_flows.assert_called_once_with(get_all=True, remove_example_flows=True)\\n\\n    def test_prints_warning_and_returns_when_no_flows(self, tmp_path: Path):\\n        client = _make_client_mock(flows=[])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        # Should not raise, should return early\\n        _run_pull(tmp_path=tmp_path, output_dir=str(tmp_path), sdk_mock=sdk)\\n        sdk.normalize_flow.assert_not_called()\\n\\n    def test_writes_multiple_flows(self, tmp_path: Path):\\n        flow1 = _fake_flow_obj(flow_id=_FLOW_ID, name=\\\"Alpha\\\")\\n        flow2 = _fake_flow_obj(flow_id=_FLOW_ID_2, name=\\\"Beta\\\")\\n        client = _make_client_mock(flows=[flow1, flow2])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        _run_pull(tmp_path=tmp_path, output_dir=str(tmp_path), sdk_mock=sdk)\\n        assert sdk.normalize_flow.call_count == 2\\n\\n    def test_exits_1_if_list_flows_raises(self, tmp_path: Path):\\n        client = _make_client_mock()\\n        client.list_flows.side_effect = RuntimeError(\\\"connection refused\\\")\\n        sdk = _make_sdk_mock(client_mock=client)\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_pull(tmp_path=tmp_path, output_dir=str(tmp_path), sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_exits_1_if_any_flow_write_fails(self, tmp_path: Path):\\n        flow1 = _fake_flow_obj(flow_id=_FLOW_ID, name=\\\"Good\\\")\\n        flow2 = _fake_flow_obj(flow_id=_FLOW_ID_2, name=\\\"Bad\\\")\\n        client = _make_client_mock(flows=[flow1, flow2])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        call_count = 0\\n\\n        def maybe_fail(d, **_kw):\\n            nonlocal call_count\\n            call_count += 1\\n            if call_count == 2:\\n                msg = \\\"write failed\\\"\\n                raise RuntimeError(msg)\\n            return d\\n\\n        sdk.normalize_flow.side_effect = maybe_fail\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_pull(tmp_path=tmp_path, output_dir=str(tmp_path), sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_all_flows_attempted_even_on_partial_error(self, tmp_path: Path):\\n        flow1 = _fake_flow_obj(flow_id=_FLOW_ID, name=\\\"Good\\\")\\n        flow2 = _fake_flow_obj(flow_id=_FLOW_ID_2, name=\\\"Bad\\\")\\n        client = _make_client_mock(flows=[flow1, flow2])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        call_count = 0\\n\\n        def maybe_fail(d, **_kw):\\n            nonlocal call_count\\n            call_count += 1\\n            if call_count == 1:\\n                msg = \\\"first fails\\\"\\n                raise RuntimeError(msg)\\n            return d\\n\\n        sdk.normalize_flow.side_effect = maybe_fail\\n        with pytest.raises(typer.Exit):\\n            _run_pull(tmp_path=tmp_path, output_dir=str(tmp_path), sdk_mock=sdk)\\n        assert call_count == 2\\n\\n\\n# ---------------------------------------------------------------------------\\n# pull_command \u2014 error handling\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestPullCommandErrorHandling:\\n    def test_config_error_exits_1(self, tmp_path: Path):\\n        from lfx.cli.pull import pull_command\\n        from lfx.config import ConfigError\\n\\n        sdk = _make_sdk_mock()\\n        with (\\n            patch(\\\"lfx.cli.pull.load_sdk\\\", return_value=sdk),\\n            patch(\\\"lfx.config.resolve_environment\\\", side_effect=ConfigError(\\\"bad config\\\")),\\n            pytest.raises(typer.Exit) as exc_info,\\n        ):\\n            pull_command(\\n                env=\\\"nonexistent\\\",\\n                output_dir=str(tmp_path),\\n                flow_id=None,\\n                project=None,\\n                project_id=None,\\n                environments_file=None,\\n                target=None,\\n                api_key=None,\\n                strip_secrets=False,\\n                indent=2,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_sdk_not_installed_raises_bad_parameter(self, tmp_path: Path):\\n        from lfx.cli.pull import pull_command\\n\\n        with (\\n            patch(\\\"lfx.cli.pull.load_sdk\\\", side_effect=typer.BadParameter(\\\"langflow-sdk is required\\\")),\\n            pytest.raises(typer.BadParameter),\\n        ):\\n            pull_command(\\n                env=None,\\n                output_dir=str(tmp_path),\\n                flow_id=None,\\n                project=None,\\n                project_id=None,\\n                environments_file=None,\\n                target=_BASE_URL,\\n                api_key=_API_KEY,\\n                strip_secrets=False,\\n                indent=2,\\n            )\\n\\n    def test_pull_errors_exit_1(self, tmp_path: Path):\\n        flow = _fake_flow_obj()\\n        client = _make_client_mock(flows=[flow])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        sdk.normalize_flow.side_effect = RuntimeError(\\\"corrupted\\\")\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_pull(tmp_path=tmp_path, output_dir=str(tmp_path), sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_client_constructed_with_resolved_url_and_key(self, tmp_path: Path):\\n        flow = _fake_flow_obj()\\n        client = _make_client_mock(flows=[flow])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        cfg = _fake_env_config(url=\\\"http://custom.server\\\", api_key=\\\"custom-key\\\")  # pragma: allowlist secret\\n        _run_pull(tmp_path=tmp_path, output_dir=str(tmp_path), sdk_mock=sdk, env_cfg=cfg)\\n        sdk.Client.assert_called_once_with(\\n            base_url=\\\"http://custom.server\\\",\\n            api_key=\\\"custom-key\\\",  # pragma: allowlist secret\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# pull_command \u2014 output_dir behaviour\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestPullCommandOutputDir:\\n    def test_defaults_to_flows_dir_when_not_specified(self, tmp_path: Path):\\n        \\\"\\\"\\\"When output_dir is None the command uses 'flows' as the destination.\\\"\\\"\\\"\\n        from lfx.cli.pull import pull_command\\n\\n        flow = _fake_flow_obj()\\n        client = _make_client_mock(flows=[flow])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        cfg = _fake_env_config()\\n";
